window.__BOOK__ = {"meta": {"title_it": "Il Piccolo Principe", "title_zh": "小王子", "author_it": "Antoine de Saint-Exupéry", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "it-IT-ElsaNeural (edge-tts)", "ipa_note": "音标为宽式音位转写，仅供参考；重音未标注。", "n_chapters": 28, "n_paras": 738, "n_sents": 1574, "audio_paras": 738}, "chapters": [{"id": "ch00", "title_it": "A LÉON WERTH", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"it": "Chiedo scusa ai bambini per aver dedicato questo libro a un adulto.", "zh": "我请求孩子们原谅，我把这本书献给一位需要朋友的大人。", "t": [100, 4112]}, {"it": "Ho un buon motivo: questo adulto è il migliore amico che ho al mondo.", "zh": "这位大人是我世间最好的朋友。", "t": [4112, 8012]}, {"it": "Ho un altro motivo: questo adulto può capire tutto, anche i libri per bambini.", "zh": "这位大人通晓一切，即便孩童的书籍也能领会。", "t": [8012, 13125]}, {"it": "Ho un terzo motivo: questo adulto abita in Francia, dove ha fame e freddo.", "zh": "这位大人住在法国，忍饥受寒。", "t": [13125, 18500]}, {"it": "Ha un gran bisogno di essere consolato.", "zh": "他极需慰藉。", "t": [18500, 20888]}, {"it": "Se tutti questi motivi non bastano, voglio dedicare il libro al bambino che questo adulto è stato molto tempo fa.", "zh": "若这些理由尚不足以服众，我便将此书献予那位成人曾身为孩童的往昔。", "t": [20888, 27488]}, {"it": "Tutti gli adulti sono stati prima di tutto dei bambini.", "zh": "所有的大人曾经都是孩子。", "t": [27488, 30925]}, {"it": "(Ma pochi di loro se lo ricordano.) Quindi correggo la mia dedica: QUANDO ERA BAMBINO", "zh": "（但他们中很少有人记得这一点。）因此，我修正我的献词：献给还是小男孩时的列翁·维尔特。", "t": [30925, 36350]}]}]}, {"id": "ch01", "title_it": "I", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"it": "Una volta, quando avevo sei anni, in un libro sulla foresta vergine intitolato Storie vissute ho visto un’illustrazione bellissima.", "zh": "六岁那年，我在一本名为《森林生活记》的书里，看到了一幅美得令人心醉的插图。", "t": [100, 8050]}, {"it": "Raffigurava un serpente boa che divora una belva.", "zh": "蟒蛇吞噬着一只野兽。", "t": [8050, 11162]}, {"it": "Questa è una riproduzione del disegno.", "zh": "这是这幅画的复制品。", "t": [11162, 13263]}]}, {"id": "ch01p01", "audio": true, "sents": [{"it": "Il libro diceva: “I serpenti boa divorano la preda tut­t’in­tera senza masticarla.", "zh": "书中说：“蟒蛇将猎物整个吞下，未经咀嚼。”", "t": [100, 5362]}, {"it": "Dopo non riescono più a muoversi e passano i sei mesi della digestione dormendo”.", "zh": "消化期间，它们便无法动弹，整日昏睡六个月。", "t": [5362, 10225]}]}, {"id": "ch01p02", "audio": true, "sents": [{"it": "Allora ho pensato molto alle avventure della giungla e con una matita colorata sono riuscito anch’io a fare il mio primo disegno.", "zh": "于是，我也用彩色铅笔绘出了我的第一幅画。", "t": [100, 6750]}, {"it": "Il mio disegno numero 1.", "zh": "我的第一幅画。", "t": [6750, 8438]}, {"it": "Era così:", "zh": "如此便是。", "t": [8438, 9162]}]}, {"id": "ch01p03", "audio": true, "sents": [{"it": "Ho mostrato il mio capolavoro agli adulti e ho chiesto se era un disegno che faceva paura.", "zh": "我把我的杰作展示给大人看，问他们这幅画是否吓人。", "t": [100, 4937]}]}, {"id": "ch01p04", "audio": true, "sents": [{"it": "Tutti mi hanno risposto: “E perché mai un cappello dovrebbe fare paura?”.", "zh": "他们都说：“帽子怎么会吓人呢？”", "t": [100, 4025]}]}, {"id": "ch01p05", "audio": true, "sents": [{"it": "Il mio disegno non raffigurava un cappello.", "zh": "我画的并非一顶帽子。", "t": [100, 2688]}, {"it": "Raffigurava un serpente boa che digerisce un elefante.", "zh": "蟒蛇正在消化一头大象。", "t": [2688, 6125]}, {"it": "Allora ho disegnato l’interno del serpente boa, in modo che gli adulti potessero capire.", "zh": "于是，我在画中展示了蟒蛇的内部，以便大人们能够理解。", "t": [6125, 11362]}, {"it": "Hanno sempre bisogno di spiegazioni.", "zh": "他们总是需要解释。", "t": [11362, 13750]}, {"it": "Il mio disegno numero 2 era così:", "zh": "我的第二号画是这样的：", "t": [13750, 15700]}]}, {"id": "ch01p06", "audio": true, "sents": [{"it": "Gli adulti mi hanno consigliato di lasciar perdere i disegni di serpenti boa aperti o chiusi e di interessarmi invece alla geografia, alla storia, all’aritmetica e alla grammatica.", "zh": "大人们劝我别再画那些张着嘴或闭着嘴的蟒蛇，而应专注于地理、历史、算术和语法。", "t": [100, 10712]}, {"it": "È stato così che, all’età di sei anni, ho rinunciato a una brillante carriera di pittore, scoraggiato dall’insuccesso dei miei disegni numero 1 e numero 2.", "zh": "就这样，六岁那年，我因一号画和二号画的失败而放弃了成为画家的辉煌生涯。", "t": [10712, 19850]}, {"it": "Gli adulti da soli non capiscono niente, ed è stancante per i bambini dover sempre spiegare tutto...", "zh": "大人自己什么都不懂，让孩子们总是得解释，真是累人。", "t": [19850, 26150]}]}, {"id": "ch01p07", "audio": true, "sents": [{"it": "Perciò ho dovuto scegliermi un altro lavoro e ho imparato a pilotare gli aerei.", "zh": "因此，我不得不选择另一份工作，并学会了驾驶飞机。", "t": [100, 4550]}, {"it": "Ho volato un po’ in giro per il mondo.", "zh": "我在世界各地略作飞翔。", "t": [4550, 6612]}, {"it": "E in effetti la geografia mi è stata utile.", "zh": "地理确实帮了我的大忙。", "t": [6612, 9250]}, {"it": "Sapevo distinguere al primo colpo d’occhio la Cina dall’Arizona.", "zh": "我一眼就能分辨出中国和亚利桑那。", "t": [9250, 12962]}, {"it": "Torna comodo, se ti sei perso in piena notte.", "zh": "若你在漫漫长夜中迷失了方向，这倒也颇为舒适。", "t": [12962, 15700]}]}, {"id": "ch01p08", "audio": true, "sents": [{"it": "Così nella vita ho conosciuto molte persone serie.", "zh": "如此，我生命中结识了许多严肃的人。", "t": [100, 3162]}, {"it": "Ho frequentato parecchio gli adulti.", "zh": "我拜访过许多大人。", "t": [3162, 5325]}, {"it": "Li ho visti proprio da vicino.", "zh": "我亲眼目睹了它们。", "t": [5325, 7238]}, {"it": "E la mia opinione non è cambiata.", "zh": "我的看法并未改变。", "t": [7238, 9288]}, {"it": "Quando ne incontravo uno che mi sembrava abbastanza sveglio, facevo l’esperimento del mio disegno numero 1, che conservo ancora.", "zh": "当我遇到一个似乎相当聪明的大人时，我便用我保留着的第一号画进行试验。", "t": [9288, 16762]}, {"it": "Volevo capire se era davvero veloce di comprendonio.", "zh": "我想知道他是否真的理解得很快。", "t": [16762, 19962]}, {"it": "Ma tutti, invariabilmente, rispondevano: “È un cappello”.", "zh": "他们总是说：“这是一顶帽子。”", "t": [19962, 24562]}, {"it": "Allora lasciavo perdere i serpenti boa, le foreste vergini e le stelle.", "zh": "于是，我便放弃了蟒蛇、原始森林和星星。", "t": [24562, 28988]}, {"it": "Mi mettevo al suo livello.", "zh": "我与他站在同一水平线上。", "t": [28988, 30638]}, {"it": "Gli parlavo di bridge, di golf, di politica e di cravatte.", "zh": "我与他们谈论桥牌、高尔夫、政治和领带。", "t": [30638, 34575]}, {"it": "E l’adulto era felicissimo di conoscere un uomo tanto ragionevole...", "zh": "那位大人对结识如此通情达理的人感到无比高兴。", "t": [34575, 38224]}]}]}, {"id": "ch02", "title_it": "II", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"it": "Così ho vissuto solo, senza nessuno con cui poter veramente parlare, finché sei anni fa non ho avuto un incidente nel deserto del Sahara.", "zh": "如此，我独自行走，无人可真正交谈，直至六年前 Sahara 沙漠中遭遇意外。", "t": [100, 8125]}, {"it": "Si era rotto qualcosa nel motore.", "zh": "发动机里出了点故障。", "t": [8125, 10300]}, {"it": "E siccome non avevo con me né un meccanico né passeggeri, decisi di riparare da solo quel brutto guasto.", "zh": "于是，身边既无机械师，又无乘客，我决定独自修理那讨厌的故障。", "t": [10300, 16375]}, {"it": "Era una questione di vita o di morte.", "zh": "生死攸关。", "t": [16375, 18725]}, {"it": "Avevo scorte di acqua solo per otto giorni.", "zh": "仅够饮八日之水。", "t": [18725, 21087]}]}, {"id": "ch02p01", "audio": true, "sents": [{"it": "Perciò la prima sera mi sono addormentato sulla sabbia, a mille miglia da qualsiasi luogo abitato.", "zh": "于是，我那第一夜便在千里之外、人迹罕至的沙地上沉睡。", "t": [100, 5875]}, {"it": "Ero più isolato di un naufrago su una zattera in mezzo all’oceano.", "zh": "比海中孤舟上的漂流者更孤独。", "t": [5875, 10050]}, {"it": "Potete quindi immaginare la mia sorpresa quando, sul far del giorno, sono stato svegliato da una vocina che diceva:", "zh": "晨曦微露，一声细语将我唤醒。", "t": [10050, 16775]}]}, {"id": "ch02p02", "audio": true, "sents": [{"it": "“Per favore...", "zh": "请给我画一只绵羊吧……", "t": [100, 1112]}, {"it": "disegnami una pecora!”", "zh": "画一只绵羊吧！", "t": [1112, 2550]}]}, {"id": "ch02p03", "audio": true, "sents": [{"it": "“Eh?”", "zh": "你说什么？", "t": [100, 450]}]}, {"id": "ch02p04", "audio": true, "sents": [{"it": "“Disegnami una pecora...”", "zh": "画一只绵羊吧……", "t": [100, 1562]}]}, {"id": "ch02p05", "audio": true, "sents": [{"it": "Sono balzato in piedi come se fossi stato colpito da un fulmine.", "zh": "犹如被雷击中，我猛地跃起。", "t": [100, 4138]}, {"it": "Mi sono sfregato gli occhi.", "zh": "揉了揉眼睛。", "t": [4138, 5938]}, {"it": "Ho guardato bene.", "zh": "我仔细端详。", "t": [5938, 7175]}, {"it": "E ho visto uno stranissimo ometto che mi fissava con aria seria.", "zh": "我瞧见一个古怪的小家伙，正一本正经地盯着我看。", "t": [7175, 10875]}, {"it": "Questo è il ritratto migliore che poi sono riuscito a farne.", "zh": "这是我后来画得最好的一幅肖像。", "t": [10875, 14238]}]}, {"id": "ch02p06", "audio": true, "sents": [{"it": "Ma ovviamente il mio disegno è molto meno bello dell’originale.", "zh": "我的画显然比不上原画之美。", "t": [100, 3900]}, {"it": "Non è colpa mia.", "zh": "这不是我的错。", "t": [3900, 5225]}, {"it": "Quando avevo sei anni gli adulti mi avevano dissuaso dall’intraprendere la carriera di pittore, perciò non sapevo disegnare altro che i boa chiusi e i boa aperti.", "zh": "六岁时，大人们劝我放弃画家生涯，所以我只会画闭嘴的和开口的蟒蛇。", "t": [5225, 13837]}]}, {"id": "ch02p07", "audio": true, "sents": [{"it": "Guardai quindi quell’apparizione con gli occhi sbarrati dallo stupore.", "zh": "我瞪大了眼睛，惊讶地凝视着那突然出现的人影。", "t": [100, 4038]}, {"it": "Tenete presente che, come ho detto, mi trovavo a mille miglia da qualunque terra abitata.", "zh": "请记住，正如我所说，我身处千里之外，远离任何有人居住的土地。", "t": [4038, 9488]}, {"it": "E quell’ometto non sembrava essersi perso, né essere morto di stanchezza, né morto di fame, né morto di sete, né morto di paura.", "zh": "他似乎并未迷路，亦非因疲惫、饥饿、干渴或恐惧而亡。", "t": [9488, 18012]}, {"it": "Non aveva proprio l’aria di un bambino perso nel deserto, a mille miglia da qualsiasi terra abitata.", "zh": "他看上去根本不像是在沙漠中迷失了方向的孩子，远离任何有人居住的土地。", "t": [18012, 23850]}, {"it": "Quando finalmente riuscii a parlare, gli dissi:", "zh": "当我终于开口说话，我对他说：", "t": [23850, 26850]}]}, {"id": "ch02p08", "audio": true, "sents": [{"it": "“Ma...", "zh": "但是", "t": [100, 750]}, {"it": "Che ci fai tu qui?”", "zh": "你在此处做什么？", "t": [750, 1688]}]}, {"id": "ch02p09", "audio": true, "sents": [{"it": "E allora mi ripeté piano, come fosse una cosa della massima importanza:", "zh": "于是他轻声地重复，仿佛这是一件极其重要的事情：", "t": [100, 4212]}]}, {"id": "ch02p10", "audio": true, "sents": [{"it": "“Per favore...", "zh": "” 他不慌不忙地重述他的要求，像说一件很严肃的事情： “请你给我画一只绵羊……” 当神秘的东西使得你心惊肉跳的时候，你不敢不听他的命令。", "t": [100, 1112]}, {"it": "disegnami una pecora...”", "zh": "画一只绵羊吧……", "t": [1112, 2537]}]}, {"id": "ch02p11", "audio": true, "sents": [{"it": "Dinanzi a un mistero assoluto, nessuno ha il coraggio di disobbedire.", "zh": "面对绝对的神秘，无人敢违抗。", "t": [100, 4450]}, {"it": "Benché lì, a mille miglia da qualsiasi luogo abitato e in pericolo di morte, mi sembrasse una cosa del tutto strampalata, tirai fuori dalla tasca un foglio di carta e una stilografica.", "zh": "尽管身处千里之外、远离人烟且命悬一线，我还是从口袋里掏出一张纸和一支钢笔。", "t": [4450, 15588]}, {"it": "Ma allora mi ricordai che avevo studiato soprattutto la geografia, la storia, l’aritmetica e la grammatica e (con un certo malumore) dissi all’ometto che non sapevo disegnare.", "zh": "我这才想起自己主要学的不过是地理、历史、算术和语法，便带着几分不悦对那位小家伙说，我不会画画。", "t": [15588, 26475]}, {"it": "Lui mi rispose:", "zh": "他回答说：", "t": [26475, 27587]}]}, {"id": "ch02p12", "audio": true, "sents": [{"it": "“Non importa.", "zh": "没关系。", "t": [100, 1250]}, {"it": "Disegnami una pecora.”", "zh": "画一只绵羊吧。", "t": [1250, 2650]}]}, {"id": "ch02p13", "audio": true, "sents": [{"it": "Siccome non avevo mai disegnato una pecora, rifeci per lui uno degli unici due disegni che sapevo fare.", "zh": "由于我从未画过绵羊，便给他画了其中的一张，那是我唯一会画的。", "t": [100, 6450]}, {"it": "Quello del boa chiuso.", "zh": "那闭嘴的蟒蛇。", "t": [6450, 7900]}, {"it": "E con mio grande stupore udii l’ometto rispondermi:", "zh": "我惊讶地听到小家伙回答道：", "t": [7900, 10787]}]}, {"id": "ch02p14", "audio": true, "sents": [{"it": "“No, no, non voglio un elefante dentro un boa.", "zh": "不，不，我不想在蟒蛇肚子里有一只大象。", "t": [100, 3600]}, {"it": "Il boa è pericolosissimo e l’elefante è troppo grosso.", "zh": "蟒蛇太可怕，大象又太大。", "t": [3600, 7262]}, {"it": "Il posto dove sto io è molto piccolo.", "zh": "我的地方很小。", "t": [7262, 9788]}, {"it": "Mi serve una pecora.", "zh": "我需要一只绵羊。", "t": [9788, 11312]}, {"it": "Disegnami una pecora.”", "zh": "画一只绵羊吧。", "t": [11312, 12713]}]}, {"id": "ch02p15", "audio": true, "sents": [{"it": "Allora disegnai.", "zh": "于是，我画了。", "t": [100, 1187]}]}, {"id": "ch02p16", "audio": true, "sents": [{"it": "Lui guardò attentamente e poi:", "zh": "他仔细看了看，然后说：", "t": [100, 2013]}]}, {"id": "ch02p17", "audio": true, "sents": [{"it": "“No!", "zh": "不！", "t": [100, 788]}, {"it": "Questa è troppo malconcia.", "zh": "这羊病得太厉害了。", "t": [788, 2525]}, {"it": "Fanne un’altra.”", "zh": "再画一个吧。", "t": [2525, 3488]}]}, {"id": "ch02p18", "audio": true, "sents": [{"it": "Disegnai.", "zh": "画了。", "t": [100, 975]}]}, {"id": "ch02p19", "audio": true, "sents": [{"it": "Il mio amico fece un sorriso bonario e disse, paziente:", "zh": "我的朋友露出亲切可爱的微笑，耐心地说：", "t": [100, 3675]}]}, {"id": "ch02p20", "audio": true, "sents": [{"it": "“Ma no, lo vedi anche tu che non è una pecora, ma un ariete.", "zh": "这不是羊，而是公羊。", "t": [100, 4225]}, {"it": "Ha le corna...”", "zh": "它长着角哩。", "t": [4225, 4950]}]}, {"id": "ch02p21", "audio": true, "sents": [{"it": "Allora rifeci un’altra volta il disegno:", "zh": "我又画了一张。", "t": [100, 2375]}]}, {"id": "ch02p22", "audio": true, "sents": [{"it": "Ma, come i precedenti, fu rifiutato:", "zh": "然而，正如之前，这幅画也被拒绝了。", "t": [100, 3112]}]}, {"id": "ch02p23", "audio": true, "sents": [{"it": "“Questa è troppo vecchia.", "zh": "这羊太老了。", "t": [100, 1612]}, {"it": "Voglio una pecora che viva a lungo.”", "zh": "我要一只能活很久的绵羊。", "t": [1612, 3500]}]}, {"id": "ch02p24", "audio": true, "sents": [{"it": "Poiché cominciavo a perdere la pazienza, e avevo fretta di smontare il motore, scarabocchiai questo disegno:", "zh": "因我耐性渐失，急于拆卸发动机，便草草画了这幅画：", "t": [100, 6325]}]}, {"id": "ch02p25", "audio": true, "sents": [{"it": "E dissi:", "zh": "我说：", "t": [100, 800]}]}, {"id": "ch02p26", "audio": true, "sents": [{"it": "“Questa è la cassa.", "zh": "这是一只箱子。", "t": [100, 1412]}, {"it": "E dentro c’è la pecora che vuoi tu.”", "zh": "箱子里有你想要的绵羊。", "t": [1412, 3237]}]}, {"id": "ch02p27", "audio": true, "sents": [{"it": "Quale non fu il mio stupore nel vedere il viso del mio giovane giudice illuminarsi:", "zh": "我的年轻法官的面容在我面前亮了起来，那是我从未见过的惊讶。", "t": [100, 4400]}]}, {"id": "ch02p28", "audio": true, "sents": [{"it": "“Ah, è proprio come la volevo!", "zh": "这正是我想要的！", "t": [100, 2112]}, {"it": "Pensi che a questa pecora occorra tanta erba?”", "zh": "这绵羊需要很多草吗？", "t": [2112, 4450]}]}, {"id": "ch02p29", "audio": true, "sents": [{"it": "“Perché?”", "zh": "为什么？", "t": [100, 588]}]}, {"id": "ch02p30", "audio": true, "sents": [{"it": "“Perché il posto dove sto io è molto piccolo...”", "zh": "因为我的地方很小……", "t": [100, 2525]}]}, {"id": "ch02p31", "audio": true, "sents": [{"it": "“Sarà più che sufficiente.", "zh": "这已经足够了。", "t": [100, 1812]}, {"it": "Ti ho dato una pecora piccola piccola.”", "zh": "我给你的是一只很小很小的绵羊。", "t": [1812, 3750]}]}, {"id": "ch02p32", "audio": true, "sents": [{"it": "Chinò il capo verso il disegno:", "zh": "他转向画看去：", "t": [100, 1800]}]}, {"id": "ch02p33", "audio": true, "sents": [{"it": "“Mica tanto piccola...", "zh": "太小了……", "t": [100, 1662]}, {"it": "Guarda!", "zh": "看哪！", "t": [1662, 2500]}, {"it": "Si è addormentata...”", "zh": "它睡着了……", "t": [2500, 3775]}]}, {"id": "ch02p34", "audio": true, "sents": [{"it": "E fu così che feci la conoscenza del piccolo principe.", "zh": "就这样，我认识了小王子。", "t": [100, 3338]}]}]}, {"id": "ch03", "title_it": "III", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"it": "Mi ci volle un bel po’ di tempo per capire da dove veniva.", "zh": "我费了好大功夫才弄清楚他来自何方。", "t": [100, 3438]}, {"it": "Il piccolo principe mi faceva moltissime domande, ma sembrava non ascoltare mai quelle che gli facevo io.", "zh": "小王子向我问了许多问题，却似乎从未真正倾听过我向他提出的问题。", "t": [3438, 9662]}, {"it": "Solo alcune parole dette per caso mi hanno pian piano rivelato tutto.", "zh": "偶然间吐露的几句话，渐渐向我揭示了全部真相。", "t": [9662, 13638]}, {"it": "Così, quando vide per la prima volta il mio aereo (non lo disegno, è troppo difficile per me), mi domandò:", "zh": "于是，他第一次看到我的飞机（我不愿画它，太难画了），便问我：", "t": [13638, 19913]}]}, {"id": "ch03p01", "audio": true, "sents": [{"it": "“Che roba è?”", "zh": "这是什么玩意儿？", "t": [100, 688]}]}, {"id": "ch03p02", "audio": true, "sents": [{"it": "“Non è una roba.", "zh": "这不是玩意儿。", "t": [100, 1388]}, {"it": "Vola, è un aereo.", "zh": "它飞，是飞机。", "t": [1388, 3350]}, {"it": "Il mio aereo.”", "zh": "这是我的飞机。", "t": [3350, 4200]}]}, {"id": "ch03p03", "audio": true, "sents": [{"it": "Ed ero orgoglioso di fargli sapere che volavo.", "zh": "我自豪地告诉他我会飞。", "t": [100, 2750]}, {"it": "Allora esclamò:", "zh": "他突然喊道：", "t": [2750, 3750]}]}, {"id": "ch03p04", "audio": true, "sents": [{"it": "“Ma come!", "zh": "怎么！", "t": [100, 1075]}, {"it": "Sei caduto dal cielo?”", "zh": "你是从天上掉下来的吗？", "t": [1075, 2250]}]}, {"id": "ch03p05", "audio": true, "sents": [{"it": "“Sì,” feci io con modestia.", "zh": "是的，我谦逊地回答。", "t": [100, 1813]}]}, {"id": "ch03p06", "audio": true, "sents": [{"it": "“Ah, questa sì che è bella!...”", "zh": "这真美啊！……", "t": [100, 1813]}]}, {"id": "ch03p07", "audio": true, "sents": [{"it": "E il piccolo principe scoppiò in una gran risata che mi irritò molto.", "zh": "小王子突然大笑起来，那笑声让我非常恼火。", "t": [100, 4275]}, {"it": "Voglio che si prendano sul serio le mie disgrazie.", "zh": "愿他们认真对待我的不幸。", "t": [4275, 7188]}, {"it": "Poi aggiunse:", "zh": "然后他又说：", "t": [7188, 8113]}]}, {"id": "ch03p08", "audio": true, "sents": [{"it": "“Allora vieni anche tu dal cielo?", "zh": "那么，你也从天上来的？", "t": [100, 1950]}, {"it": "Di che pianeta sei?”", "zh": "你是哪个星球的人？", "t": [1950, 3200]}]}, {"id": "ch03p09", "audio": true, "sents": [{"it": "Di colpo scorsi una luce nel mistero della sua presenza, e subito gli domandai:", "zh": "蓦然间，我窥见了他的神秘所在，便立刻向他发问：", "t": [100, 4800]}]}, {"id": "ch03p10", "audio": true, "sents": [{"it": "“Quindi vieni da un altro pianeta?”", "zh": "那么，你是从另一个星球来的？", "t": [100, 1900]}]}, {"id": "ch03p11", "audio": true, "sents": [{"it": "Ma non mi rispose.", "zh": "他没有回答。", "t": [100, 1450]}, {"it": "Guardava l’aereo scuotendo piano la testa:", "zh": "他轻轻摇头，目光落在飞机上。", "t": [1450, 3825]}]}, {"id": "ch03p12", "audio": true, "sents": [{"it": "“In effetti con quest’affare non puoi venire da molto lontano...”", "zh": "实则，凭这架玩意儿，你不可能来自太远的地方……", "t": [100, 3350]}]}, {"id": "ch03p13", "audio": true, "sents": [{"it": "E restò a lungo come trasognato.", "zh": "他久久地沉醉于幻想之中。", "t": [100, 2375]}, {"it": "Poi tirò fuori dalla tasca la mia pecora e si immerse nella contemplazione del suo tesoro.", "zh": "他从口袋里掏出我画的绵羊，沉浸在对他的宝贝的凝视之中。", "t": [2375, 7650]}]}, {"id": "ch03p14", "audio": true, "sents": [{"it": "Potete ben immaginare quanto mi incuriosisse quella mezza confidenza sugli “altri pianeti”.", "zh": "您能想象得知“其他星球”的只言片语，我是多么好奇。", "t": [100, 5188]}, {"it": "Cercai quindi di saperne di più:", "zh": "于是，我设法了解更多。", "t": [5188, 7087]}]}, {"id": "ch03p15", "audio": true, "sents": [{"it": "“Da dove vieni, ometto?", "zh": "你从哪里来，小家伙？", "t": [100, 2050]}, {"it": "Qual è il posto dove stai?", "zh": "你在哪个地方？", "t": [2050, 3762]}, {"it": "Dove la vuoi portare la mia pecora?”", "zh": "你打算把我的绵羊带到哪里去？", "t": [3762, 5576]}]}, {"id": "ch03p16", "audio": true, "sents": [{"it": "Dopo un silenzio pensoso mi rispose:", "zh": "沉默片刻后，他回答道：", "t": [100, 2437]}]}, {"id": "ch03p17", "audio": true, "sents": [{"it": "“C’è di buono che la cassa che mi hai dato di notte potrà farle da casa.”", "zh": "你给我的箱子夜里可以给它当房子。", "t": [100, 3825]}]}, {"id": "ch03p18", "audio": true, "sents": [{"it": "“Certo.", "zh": "当然。", "t": [100, 1025]}, {"it": "E se fai il bravo ti darò anche una corda per legarla durante il giorno.", "zh": "若你表现好，我还会给你一根绳子，白天用来拴住它。", "t": [1025, 5162]}, {"it": "E un paletto.”", "zh": "一根桩。", "t": [5162, 6088]}]}, {"id": "ch03p19", "audio": true, "sents": [{"it": "Il piccolo principe sembrò scioccato dalla proposta:", "zh": "小王子对这提议显得惊讶不已：", "t": [100, 3163]}]}, {"id": "ch03p20", "audio": true, "sents": [{"it": "“Legarla?", "zh": "绑住它？", "t": [100, 1100]}, {"it": "Che idea assurda!”", "zh": "这主意真荒唐！", "t": [1100, 2250]}]}, {"id": "ch03p21", "audio": true, "sents": [{"it": "“Ma se non la leghi se ne andrà in giro chissà dove e si perderà.”", "zh": "若不将它拴住，它便会四处游荡，不知会迷失何方。", "t": [100, 3700]}]}, {"id": "ch03p22", "audio": true, "sents": [{"it": "E di nuovo il mio amico scoppiò a ridere:", "zh": "我的朋友又突然大笑起来：", "t": [100, 2213]}]}, {"id": "ch03p23", "audio": true, "sents": [{"it": "“Ma dove vuoi che vada?!”", "zh": "你打算让它去哪里？", "t": [100, 1312]}]}, {"id": "ch03p24", "audio": true, "sents": [{"it": "“Dove capita, prenderà la prima direzione che trova.”", "zh": "它将朝着遇到的第一个方向前行。", "t": [100, 3226]}]}, {"id": "ch03p25", "audio": true, "sents": [{"it": "Allora il piccolo principe osservò, con aria seria:", "zh": "小王子严肃地观察着。", "t": [100, 3326]}]}, {"id": "ch03p26", "audio": true, "sents": [{"it": "“Non importa, dove sto io è talmente piccolo!”", "zh": "我在乎的，不是我在哪里，而是我有多小。", "t": [100, 3000]}]}, {"id": "ch03p27", "audio": true, "sents": [{"it": "E aggiunse, forse con un’ombra di malinconia:", "zh": "他或许带着一丝忧郁地补充道：", "t": [100, 2900]}]}, {"id": "ch03p28", "audio": true, "sents": [{"it": "“Qualunque direzione si prende, non si può andare molto lontano...”", "zh": "无论朝哪个方向走，都不会走得太远……", "t": [100, 3826]}]}]}, {"id": "ch04", "title_it": "IV", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"it": "Così avevo scoperto un’altra cosa molto importante: il pianeta da cui proveniva era poco più grande di una casa!", "zh": "我于是又发现了一件事，非常关键：他来自的那个星球，比一座房子大不了多少。", "t": [100, 6413]}]}, {"id": "ch04p01", "audio": true, "sents": [{"it": "Non mi stupiva.", "zh": "我并不感到惊讶。", "t": [100, 1338]}, {"it": "Sapevo che oltre ai pianeti maggiori come la Terra, Giove, Marte, Venere, a cui abbiamo dato dei nomi, ne esistono centinaia di altri che a volte sono così piccoli che quasi non si riesce neppure a vederli con il telescopio.", "zh": "我知道，除了那些我们命名的大行星，如地球、木星、火星、金星，还有成千上万的星球，它们有时小到几乎无法用望远镜观测。", "t": [1338, 15575]}, {"it": "Quando un astronomo ne scopre uno, lo designa con un numero.", "zh": "天文学家发现一颗星，便以数字为其命名。", "t": [15575, 19288]}, {"it": "Per esempio: “asteroide 325”.", "zh": "例如：小行星325号。", "t": [19288, 22450]}]}, {"id": "ch04p02", "audio": true, "sents": [{"it": "Ho buoni motivi per credere che il pianeta da cui veniva il piccolo principe fosse l’asteroide B 612.", "zh": "我有充分的理由相信小王子来自B612号小行星。", "t": [100, 5175]}, {"it": "Questo asteroide è stato intravisto solo una volta, con il telescopio, nel 1909, da un astronomo turco.", "zh": "这颗小行星仅在一九〇九年被一位土耳其天文学家用望远镜观测到一次。", "t": [5175, 14563]}]}, {"id": "ch04p03", "audio": true, "sents": [{"it": "Lo scienziato aveva presentato la sua scoperta a un congresso internazionale di astronomia.", "zh": "这位科学家曾在国际天文大会上公布了他的发现。", "t": [100, 5512]}, {"it": "Ma nessuno gli aveva creduto, per via del modo in cui era vestito.", "zh": "无人相信他，只因他的衣着。", "t": [5512, 9675]}, {"it": "Gli adulti sono fatti così.", "zh": "大人就是这样。", "t": [9675, 11350]}]}, {"id": "ch04p04", "audio": true, "sents": [{"it": "Fu una vera fortuna, per la reputazione dell’asteroide B 612, quando un dittatore turco impose al proprio popolo, pena la morte, di vestirsi all’europea.", "zh": "土耳其独裁者为了B612小行星的声誉，强迫国民穿上欧洲式服装，违者处以死刑。", "t": [100, 11700]}, {"it": "L’astronomo rifece la presentazione nel 1920, vestito con un completo elegante.", "zh": "这位天文学家于一九二〇年身着一套考究的西装再次做了报告。", "t": [11700, 16950]}, {"it": "E stavolta tutti gli diedero retta.", "zh": "这次所有人都认可了他的观点。", "t": [16950, 18924]}]}, {"id": "ch04p05", "audio": true, "sents": [{"it": "Vi ho raccontato questi particolari sull’asteroide B 612 e vi ho rivelato il suo numero a causa degli adulti.", "zh": "我们之所以讲述B612小行星的这些细节，并透露其编号，皆因大人们的缘故。", "t": [100, 6962]}, {"it": "Agli adulti piacciono i numeri.", "zh": "大人们偏爱数字。", "t": [6962, 8875]}, {"it": "Quando raccontate loro di un nuovo amico, non vi chiedono mai le cose importanti.", "zh": "讲述新朋友时，他们从不询问那些重要之事。", "t": [8875, 13538]}, {"it": "Non vi dicono: “Com’è il suono della sua voce?", "zh": "他们不会问：“他的嗓音如何？”", "t": [13538, 16612]}, {"it": "Quali sono i suoi giochi preferiti?", "zh": "他最喜欢玩什么游戏？", "t": [16612, 18812]}, {"it": "Fa collezione di farfalle?”.", "zh": "他是否采集蝴蝶标本？", "t": [18812, 20575]}, {"it": "Le loro domande sono: “Quanti anni ha?", "zh": "他们问：“他多大年纪？”", "t": [20575, 23188]}, {"it": "Quanti fratelli?", "zh": "他有多少个兄弟？", "t": [23188, 24362]}, {"it": "Quanto pesa?", "zh": "他多重？", "t": [24362, 25438]}, {"it": "Quanto guadagna suo padre?”.", "zh": "他父亲挣多少钱？", "t": [25438, 27138]}, {"it": "Solo allora pensano di conoscerlo.", "zh": "这才开始觉得认识了他。", "t": [27138, 29375]}, {"it": "Se dite agli adulti: “Ho visto una bella casa di mattoni rosa, con gerani alle finestre e colombi sul tetto...”, loro non riescono a immaginarsi la casa.", "zh": "若对大人说：“我看见一幢粉红砖砌的房子，窗台上种着天竺葵，鸽群栖息在屋顶……”他们便无法想象这房子的模样。", "t": [29375, 38538]}, {"it": "Dovete dire: “Ho visto una casa da centomila franchi”.", "zh": "我看见一幢值十万法郎的房子。", "t": [38538, 42238]}, {"it": "Allora esclamano subito: “Oh, che bella!”.", "zh": "哦，多美啊！", "t": [42238, 45000]}]}, {"id": "ch04p06", "audio": true, "sents": [{"it": "Quindi se dite: “Il piccolo principe è esistito perché era bellissimo, rideva e voleva una pecora.", "zh": "小王子之所以存在，只因他可爱俊美，笑容满面，渴望拥有一只绵羊。", "t": [100, 6550]}, {"it": "Se qualcuno vuole una pecora significa che esiste”, loro alzeranno le spalle e diranno che siete un bambino!", "zh": "他们耸耸肩，会说你是孩子！", "t": [6550, 13162]}, {"it": "Ma se proclamate: “Il pianeta da cui veniva è l’asteroide B 612”, allora si convinceranno e vi lasceranno in pace, senza farvi domande.", "zh": "若宣称：“他来自的星球是B612号小行星”，他们便会信服，不再打扰你。", "t": [13162, 22250]}, {"it": "Sono fatti così.", "zh": "如此而已。", "t": [22250, 23562]}, {"it": "Non bisogna prendersela.", "zh": "不必生气。", "t": [23562, 25238]}, {"it": "I bambini devono avere molta pazienza con gli adulti.", "zh": "孩子们对大人应有极大的耐心。", "t": [25238, 28237]}]}, {"id": "ch04p07", "audio": true, "sents": [{"it": "Noi però che capiamo la vita ce ne infischiamo dei numeri!", "zh": "我们理解生活的人，对数字并不放在心上。", "t": [100, 3612]}, {"it": "Sarebbe stato bello cominciare questa storia come una favola.", "zh": "真希望这个故事能从一则童话开始。", "t": [3612, 7038]}, {"it": "Mi sarebbe piaciuto dire:", "zh": "我本想说的是：", "t": [7038, 8413]}]}, {"id": "ch04p08", "audio": true, "sents": [{"it": "“C’era una volta un piccolo principe che abitava su un pianeta poco più grande di lui e aveva bisogno di un amico...”.", "zh": "从前有个小王子，他住在比他大不了多少的星球上，需要一位朋友……", "t": [100, 6425]}, {"it": "Per quelli che capiscono la vita, sarebbe sembrato molto più vero.", "zh": "对懂得生活的人来说，这样讲述似乎更真实。", "t": [6425, 10012]}]}, {"id": "ch04p09", "audio": true, "sents": [{"it": "Non mi piace, infatti, che il mio libro sia letto in maniera superficiale.", "zh": "我不喜欢我的书被粗心大意地阅读。", "t": [100, 5025]}, {"it": "È molto doloroso rievocare questi ricordi.", "zh": "回忆这些往事，心中甚是痛苦。", "t": [5025, 7650]}, {"it": "Sono passati ormai sei anni da quando il mio amico se n’è andato con la sua pecora.", "zh": "六年来，我的朋友带着他的羊已经走了。", "t": [7650, 12250]}, {"it": "Se tento di descriverlo qui, è per non dimenticarlo.", "zh": "若在此处尽力描述，是为了不忘却。", "t": [12250, 15812]}, {"it": "È triste dimenticare un amico.", "zh": "遗忘朋友是痛苦的。", "t": [15812, 17812]}, {"it": "Non tutti hanno avuto un amico.", "zh": "并非人人都有过朋友。", "t": [17812, 19675]}, {"it": "E rischio di diventare come gli adulti, a cui interessano soltanto i numeri.", "zh": "我们或许会变成只关心数字的大人。", "t": [19675, 24275]}, {"it": "Per questo ho comprato una scatola di colori e delle matite.", "zh": "为此，我购置了一盒颜料和几支铅笔。", "t": [24275, 27775]}, {"it": "Alla mia età è dura rimettersi a disegnare quando gli unici tentativi che hai fatto sono stati, a sei anni, un boa chiuso e un boa aperto!", "zh": "到了我这个年纪，重新拿起画笔是困难的，因为迄今为止的唯一尝试，六岁时画的那条闭合的蟒蛇和那条开口的蟒蛇！", "t": [27775, 35950]}, {"it": "Ovviamente cercherò di fare ritratti più fedeli possibile.", "zh": "显然，我会尽力画得更逼真。", "t": [35950, 39488]}, {"it": "Ma non sono sicuro di riuscirci.", "zh": "我无法确信能否成功。", "t": [39488, 41812]}, {"it": "Un disegno viene bene, e poi un altro non è somigliante.", "zh": "一幅画得可以，另一幅却画得不像。", "t": [41812, 45638]}, {"it": "A volte mi sbaglio anche con l’altezza.", "zh": "有时连身高我也记错了。", "t": [45638, 47975]}, {"it": "Qui il piccolo principe è troppo alto.", "zh": "小王子个儿太高了。", "t": [47975, 50438]}, {"it": "Lì è troppo basso.", "zh": "他太矮了。", "t": [50438, 51862]}, {"it": "E sono incerto sul colore dei vestiti.", "zh": "我对他的衣服颜色也拿不定主意。", "t": [51862, 54412]}, {"it": "Allora vado un po’ per tentativi, così e cosà, alla meno peggio.", "zh": "于是，我就这样尝试着，一步步地，至少不会更糟。", "t": [54412, 58675]}, {"it": "Finirà che sbaglierò qualche dettaglio cruciale.", "zh": "终将错失某些关键细节。", "t": [58675, 61588]}, {"it": "Ma dovrete perdonarmi.", "zh": "请原谅我。", "t": [61588, 63238]}, {"it": "Il mio amico non dava mai spiegazioni.", "zh": "我的朋友从不解释。", "t": [63238, 65625]}, {"it": "Forse mi credeva simile a lui.", "zh": "也许他认为我和他相似。", "t": [65625, 67638]}, {"it": "Purtroppo però io non sono capace di vedere le pecore attraverso le casse.", "zh": "遗憾的是，我无法透过箱子看到绵羊。", "t": [67638, 72112]}, {"it": "Forse sono un po’ come gli adulti.", "zh": "也许我有点像大人了。", "t": [72112, 74262]}, {"it": "Devo essere invecchiato.", "zh": "我或许已老。", "t": [74262, 75625]}]}]}, {"id": "ch05", "title_it": "V", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"it": "Ogni giorno scoprivo qualcosa sul pianeta, sulla partenza e sul viaggio.", "zh": "每日，我在这颗星球、启程与旅途中有所领悟。", "t": [100, 4750]}, {"it": "Saltava fuori tra una riflessione e l’altra.", "zh": "在沉思间，它突然浮现。", "t": [4750, 7450]}, {"it": "Fu così che il terzo giorno appresi il dramma dei baobab.", "zh": "第三天，我得知了猴面包树的悲剧。", "t": [7450, 11050]}]}, {"id": "ch05p01", "audio": true, "sents": [{"it": "Anche stavolta fu grazie alla pecora, perché improvvisamente il piccolo principe mi domandò, come in preda a un grave dubbio:", "zh": "这一次也是多亏了绵羊，因为小王子突然带着严重的怀疑问我：", "t": [100, 7062]}]}, {"id": "ch05p02", "audio": true, "sents": [{"it": "“È vero, no, che le pecore mangiano gli arbusti?”", "zh": "“绵羊真的会吃灌木吗？”", "t": [100, 3250]}]}, {"id": "ch05p03", "audio": true, "sents": [{"it": "“Sì, è vero.”", "zh": "是的，是真的。", "t": [100, 1338]}]}, {"id": "ch05p04", "audio": true, "sents": [{"it": "“Ah, benissimo!”", "zh": "啊，太好了！", "t": [100, 1412]}]}, {"id": "ch05p05", "audio": true, "sents": [{"it": "Non capii perché fosse così importante che le pecore mangiassero gli arbusti.", "zh": "我不懂为什么羊吃灌木这么重要。", "t": [100, 4675]}, {"it": "Ma il piccolo principe aggiunse:", "zh": "小王子接着说：", "t": [4675, 6525]}]}, {"id": "ch05p06", "audio": true, "sents": [{"it": "“Quindi mangiano anche i baobab?”", "zh": "那么，它们也吃猴面包树了吗？", "t": [100, 1888]}]}, {"id": "ch05p07", "audio": true, "sents": [{"it": "Feci notare al piccolo principe che i baobab non sono arbusti, ma alberi alti come chiese, e che se anche avesse portato un intero branco di elefanti, il branco non sarebbe riuscito ad avere la meglio su un solo bao­bab.", "zh": "小王子，我告诉他，猴面包树并非灌木，而是像教堂一般高耸入云的树木，即便是一群大象前来，也无法将其连根拔起。", "t": [100, 13200]}]}, {"id": "ch05p08", "audio": true, "sents": [{"it": "L’idea del branco di elefanti fece ridere il piccolo principe:", "zh": "那群大象的念头让小王子忍不住笑了。", "t": [100, 3500]}]}, {"id": "ch05p09", "audio": true, "sents": [{"it": "“Bisognerebbe metterli uno sopra l’altro...”", "zh": "它们得一个压一个地叠上去……", "t": [100, 2450]}]}, {"id": "ch05p10", "audio": true, "sents": [{"it": "Ma saggiamente osservò:", "zh": "他明智地观察道：", "t": [100, 1412]}]}, {"id": "ch05p11", "audio": true, "sents": [{"it": "“All’inizio, prima di crescere, i baobab sono piccoli.”", "zh": "起初，猴面包树尚且幼小。", "t": [100, 3738]}]}, {"id": "ch05p12", "audio": true, "sents": [{"it": "“Esatto!", "zh": "是的，是真的。", "t": [100, 1138]}, {"it": "Ma perché mai le pecore dovrebbero mangiare i piccoli baobab?”", "zh": "绵羊为何要吃小猴面包树呢？", "t": [1138, 4537]}]}, {"id": "ch05p13", "audio": true, "sents": [{"it": "Mi rispose: “Insomma, dai!”, come se fosse ovvio.", "zh": "“哎哟，当然了！”他答道，仿佛这是理所当然之事。", "t": [100, 4500]}, {"it": "E dovetti fare un grande sforzo di intelligenza per venire da solo a capo del problema.", "zh": "我不得不动用全部智慧才能独自解开这个难题。", "t": [4500, 9675]}]}, {"id": "ch05p14", "audio": true, "sents": [{"it": "In effetti, come su ogni pianeta, sul pianeta del piccolo principe c’erano erbe buone ed erbe cattive.", "zh": "事实上，正如每个星球一样，小王子的星球上也有良草与恶草。", "t": [100, 7125]}, {"it": "Quindi semi buoni di erbe buone e semi cattivi di erbe cattive.", "zh": "因此，既有良草的种子，也有恶草的种子。", "t": [7125, 11525]}, {"it": "Ma i semi sono invisibili.", "zh": "种子是隐形的。", "t": [11525, 13450]}, {"it": "Dormono tutti nel segreto della terra finché a uno di loro non piglia il ghiribizzo di svegliarsi.", "zh": "它们都在大地的秘密中沉睡，直到其中一颗突然想醒过来。", "t": [13450, 19062]}, {"it": "Allora si stiracchia e fa spuntare timidamente verso il sole uno splendido, innocuo germoglio.", "zh": "它伸展身躯，怯生生地向太阳露出一个美丽、无害的嫩芽。", "t": [19062, 25438]}, {"it": "Se è un germoglio di rapanello o di rosa, puoi lasciarlo crescere come gli pare.", "zh": "若它是萝卜或玫瑰的幼苗，便可任其自然生长。", "t": [25438, 30100]}, {"it": "Ma se ti rendi conto che è una pianta cattiva, devi strapparla immediatamente.", "zh": "若你察觉它是一株恶草，便须立刻连根拔除。", "t": [30100, 34788]}, {"it": "Sul pianeta del piccolo principe c’erano alcuni semi terribili...", "zh": "小王子的星球上埋藏着可怕的种子……", "t": [34788, 38762]}, {"it": "ed erano i semi di baobab.", "zh": "那是猴面包树的种子。", "t": [38762, 40638]}, {"it": "Tutto il suolo del pianeta ne era infestato.", "zh": "整个星球都被它侵扰。", "t": [40638, 43312]}, {"it": "E se un baobab non lo strappi via subito, dopo non riesci più a liberartene.", "zh": "若不及时拔除猴面包树，此后便无法将其根除。", "t": [43312, 48250]}, {"it": "Occupa tutto il pianeta.", "zh": "它占据了整个星球。", "t": [48250, 49925]}, {"it": "Lo perfora con le radici.", "zh": "根须穿透它。", "t": [49925, 52175]}, {"it": "E se il pianeta è troppo piccolo e i baobab sono troppo numerosi, questi lo spaccano tutto.", "zh": "若星球太小，而猴面包树又太多，它们便会将星球撑裂。", "t": [52175, 57600]}]}, {"id": "ch05p15", "audio": true, "sents": [{"it": "“È una questione di disciplina,” mi disse più tardi il piccolo principe.", "zh": "“这是纪律问题，”小王子后来对我说。", "t": [100, 4075]}, {"it": "“Al mattino, finita la toilette, bisogna occuparsi della toilette del pianeta.", "zh": "清晨，梳洗完毕，便要打理好地球的梳洗。", "t": [4075, 9188]}, {"it": "Appena distingui i baobab dalle piante di rose, cui somigliano molto quando sono giovani, li devi subito strappare.", "zh": "一辨明猴面包树与玫瑰苗的相似，便须立刻连根拔除。", "t": [9188, 16388]}, {"it": "È un lavoro noiosissimo, ma molto semplice.”", "zh": "这是一件单调乏味的工作，却十分简单。", "t": [16388, 19250]}]}, {"id": "ch05p16", "audio": true, "sents": [{"it": "E un giorno mi consigliò di provare a cimentarmi con un bel disegno per far entrare questo principio nella testa dei bambini di dove sto io.", "zh": "他建议我试着画一幅美丽的画，好让那里的孩子们牢记这个道理。", "t": [100, 7825]}, {"it": "“Potrebbe essergli utile, se dovessero viaggiare.", "zh": "或许，若他们日后旅行，这会大有裨益。", "t": [7825, 10725]}, {"it": "In certi casi rimandare un lavoro non ha alcuna conseguenza.", "zh": "在某些情况下，推迟一项工作并无大碍。", "t": [10725, 14400]}, {"it": "Ma con i baobab è sempre un disastro.", "zh": "猴面包树总是带来灾难。", "t": [14400, 16962]}, {"it": "Conoscevo un pianeta abitato da un pigro.", "zh": "那颗星球上住着一个懒惰的人。", "t": [16962, 19500]}, {"it": "Aveva trascurato tre arbusti...”", "zh": "他忽略了三棵灌木……", "t": [19500, 21275]}]}, {"id": "ch05p17", "audio": true, "sents": [{"it": "Così, con le indicazioni del piccolo principe, ho disegnato quel pianeta.", "zh": "于是，在小王子的指导下，我画下了那颗星球。", "t": [100, 5125]}, {"it": "Non mi piace affatto prendere il tono del moralista.", "zh": "我根本不喜欢摆出一副道德家的架势。", "t": [5125, 8262]}, {"it": "Ma i baobab rappresentano un pericolo talmente sottovalutato, e i rischi di chi dovesse perdersi in un asteroide sono tali, che una volta tanto metto da parte ogni scrupolo.", "zh": "猴面包树的风险被如此低估，而迷失在某个小行星上的人所面临的危险又是如此之大，这一次我决定放下所有的顾虑。", "t": [8262, 18712]}, {"it": "Dico: “Bambini!", "zh": "孩子们！", "t": [18712, 20350]}, {"it": "Fate attenzione ai baobab!”.", "zh": "小心猴面包树！", "t": [20350, 22388]}, {"it": "Se ho messo tutto il mio impegno in quel disegno è stato proprio per mettere in guardia i miei amici da un pericolo cui, come me, erano esposti da tempo senza saperlo.", "zh": "我之所以在那幅画上倾注了全部心力，正是为了警示我的朋友们，让他们意识到一个我们长久以来都未察觉的潜在危险。", "t": [22388, 31825]}, {"it": "Il messaggio che davo valeva lo sforzo.", "zh": "这信息值得付出努力。", "t": [31825, 34288]}, {"it": "Vi domanderete: Perché in questo libro non ci sono altri disegni grandiosi come il disegno dei baobab?", "zh": "你们会问：为什么这本书里没有其他像猴面包树画那么雄伟的插图？", "t": [34288, 40512]}, {"it": "La risposta è molto semplice: ci ho provato, ma non ci sono riuscito.", "zh": "我尽力了，但未能成功。", "t": [40512, 45238]}, {"it": "Quando ho disegnato i baobab, ero spinto dall’urgenza.", "zh": "我画猴面包树时，被紧迫感驱使。", "t": [45238, 48624]}]}]}, {"id": "ch06", "title_it": "VI", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"it": "Ah!, piccolo principe, così ho pian piano capito come procedeva la tua vita malinconica.", "zh": "啊，小王子，就这样我渐渐明白了你的生活是多么忧郁。", "t": [100, 6125]}, {"it": "Per molto tempo il tuo unico svago era stata la dolcezza dei tramonti.", "zh": "长久以来，你唯一的慰藉便是那夕阳的温柔。", "t": [6125, 10438]}, {"it": "Ho scoperto questo ennesimo dettaglio il mattino del quarto giorno, quando mi hai detto:", "zh": "第四天早晨，当我告诉你时，我又发现了这个细节。", "t": [10438, 15276]}]}, {"id": "ch06p01", "audio": true, "sents": [{"it": "“A me piacciono molto i tramonti.", "zh": "我非常喜欢落日时分。", "t": [100, 2075]}, {"it": "Andiamo a vedere un tramonto...”", "zh": "我们去看看日落吧……", "t": [2075, 3588]}]}, {"id": "ch06p02", "audio": true, "sents": [{"it": "“Ma bisogna aspettare...”", "zh": "须得等待……", "t": [100, 1513]}]}, {"id": "ch06p03", "audio": true, "sents": [{"it": "“Aspettare cosa?”", "zh": "等待什么呢？", "t": [100, 1075]}]}, {"id": "ch06p04", "audio": true, "sents": [{"it": "“Aspettare che il sole tramonti.”", "zh": "等待太阳落山。", "t": [100, 1800]}]}, {"id": "ch06p05", "audio": true, "sents": [{"it": "Sulle prime sembravi molto stupito, poi hai riso di te stesso.", "zh": "你先是显得十分惊讶，接着又自嘲地笑了。", "t": [100, 4388]}, {"it": "E mi hai detto:", "zh": "你曾对我说：", "t": [4388, 5300]}]}, {"id": "ch06p06", "audio": true, "sents": [{"it": "“Credo sempre di essere da me!”", "zh": "我总以为我是在自己家里！", "t": [100, 1612]}]}, {"id": "ch06p07", "audio": true, "sents": [{"it": "Infatti.", "zh": "的确如此。", "t": [100, 1262]}, {"it": "Tutti sanno che quando negli Stati Uniti è mezzogiorno, in Francia è il tramonto.", "zh": "众人皆知，当美国正值正午，法国已是黄昏时分。", "t": [1262, 6712]}, {"it": "Basterebbe poter andare in Francia in un minuto per veder tramontare il sole.", "zh": "只需片刻，便能赴法国一睹落日之景。", "t": [6712, 11362]}, {"it": "Purtroppo la Francia è molto lontana.", "zh": "可惜法国太远了。", "t": [11362, 13775]}, {"it": "Ma sul tuo piccolissimo pianeta ti bastava spostare la sedia di qualche passo.", "zh": "在你的小小星球上，只需挪动椅子几步即可。", "t": [13775, 18350]}, {"it": "E guardavi il crepuscolo ogni volta che volevi...", "zh": "你总是想看日落。", "t": [18350, 20912]}]}, {"id": "ch06p08", "audio": true, "sents": [{"it": "“Un giorno ho visto il sole tramontare quarantaquattro volte!”", "zh": "那天，我目睹了四十四次日落。", "t": [100, 3512]}]}, {"id": "ch06p09", "audio": true, "sents": [{"it": "E più tardi aggiungevi:", "zh": "后来，你又说：", "t": [100, 1438]}]}, {"id": "ch06p10", "audio": true, "sents": [{"it": "“Sai...", "zh": "你知道……", "t": [100, 950]}, {"it": "quando si è molto tristi si amano i tramonti...”", "zh": "当人极度悲伤时，便爱上了落日……", "t": [950, 3462]}]}, {"id": "ch06p11", "audio": true, "sents": [{"it": "“Allora il giorno delle quarantaquattro volte eri proprio tanto triste?”", "zh": "那天，你看了四十四次日落，真是非常难过。", "t": [100, 3638]}]}, {"id": "ch06p12", "audio": true, "sents": [{"it": "Ma il piccolo principe non rispose.", "zh": "小王子没有回答。", "t": [100, 2225]}]}]}, {"id": "ch07", "title_it": "VII", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"it": "Il quinto giorno, sempre grazie alla pecora, mi fu rivelato il segreto della vita del piccolo principe.", "zh": "第五天，多亏了那只绵羊，小王子的生活秘密终于揭晓。", "t": [100, 6300]}, {"it": "Mi domandò bruscamente, di punto in bianco, come un interrogativo a lungo meditato in silenzio:", "zh": "他突然打断我，像是在心中深思熟虑已久，直截了当地问道：", "t": [6300, 12113]}]}, {"id": "ch07p01", "audio": true, "sents": [{"it": "“Una pecora, se mangia gli arbusti, mangia anche i fiori?”", "zh": "绵羊若吃灌木，也会吃花朵吗？", "t": [100, 3663]}]}, {"id": "ch07p02", "audio": true, "sents": [{"it": "“Una pecora mangia tutto quello che trova.”", "zh": "绵羊见什么吃什么。", "t": [100, 2187]}]}, {"id": "ch07p03", "audio": true, "sents": [{"it": "“Anche i fiori con le spine?”", "zh": "带刺的花也吃吗？", "t": [100, 1537]}]}, {"id": "ch07p04", "audio": true, "sents": [{"it": "“Sì.", "zh": "吃的。", "t": [100, 825]}, {"it": "Anche i fiori con le spine.”", "zh": "带刺的花也吃。", "t": [825, 2288]}]}, {"id": "ch07p05", "audio": true, "sents": [{"it": "“Allora le spine a cosa servono?”", "zh": "那么刺还有什么用呢？", "t": [100, 1900]}]}, {"id": "ch07p06", "audio": true, "sents": [{"it": "Non lo sapevo.", "zh": "我不知道。", "t": [100, 1275]}, {"it": "In quel momento ero tutto preso a svitare un bullone troppo stretto del motore.", "zh": "那一刻，我正忙于拧下发动机上过紧的螺栓。", "t": [1275, 6138]}, {"it": "Ero molto preoccupato perché il guasto cominciava a sembrarmi davvero serio e le scorte d’acqua che si riducevano mi facevano temere il peggio.", "zh": "我非常担忧，因为故障似乎变得极其严重，而水资源的减少让我担心不已。", "t": [6138, 13526]}]}, {"id": "ch07p07", "audio": true, "sents": [{"it": "“Le spine a cosa servono?”", "zh": "刺有什么用呢？", "t": [100, 1576]}]}, {"id": "ch07p08", "audio": true, "sents": [{"it": "Il piccolo principe non rinunciava mai a una domanda dopo che l’aveva fatta.", "zh": "小王子一旦提出疑问，就绝不放弃追问。", "t": [100, 4588]}, {"it": "Ero contrariato dal bullone e risposi con la prima sciocchezza che mi passò per la mente:", "zh": "我因那螺栓而心烦，便随口答道：随口而来的第一个傻话便脱口而出。", "t": [4588, 9226]}]}, {"id": "ch07p09", "audio": true, "sents": [{"it": "“Le spine non servono a niente, sono pura cattiveria da parte dei fiori!”", "zh": "刺毫无用处，那是花儿们的一时恶作剧。", "t": [100, 4350]}]}, {"id": "ch07p10", "audio": true, "sents": [{"it": "“Oh!”", "zh": "哦！", "t": [100, 562]}]}, {"id": "ch07p11", "audio": true, "sents": [{"it": "Ma dopo un attimo di silenzio sbottò, come risentito:", "zh": "沉默片刻后，他带着怨气地脱口而出：", "t": [100, 3737]}]}, {"id": "ch07p12", "audio": true, "sents": [{"it": "“Non ti credo!", "zh": "我不信你！", "t": [100, 1312]}, {"it": "I fiori sono deboli.", "zh": "花儿柔弱无力。", "t": [1312, 2888]}, {"it": "Sono ingenui.", "zh": "他们多么天真。", "t": [2888, 4112]}, {"it": "Si fanno coraggio come possono.", "zh": "它们以自己的方式壮胆。", "t": [4112, 6112]}, {"it": "E con le spine pensano di mettere paura...”", "zh": "她们以为长刺就能吓人……", "t": [6112, 8412]}]}, {"id": "ch07p13", "audio": true, "sents": [{"it": "Non risposi nulla.", "zh": "无言以对。", "t": [100, 1538]}, {"it": "In quel momento pensavo: “Se questo bullone non si allenta, lo faccio saltare con una martellata”.", "zh": "那时我心想：“若这螺栓不解开，我便用锤子砸它。”", "t": [1538, 7412]}, {"it": "Il piccolo principe interruppe di nuovo le mie riflessioni:", "zh": "小王子再次打断了我的沉思：", "t": [7412, 10700]}]}, {"id": "ch07p14", "audio": true, "sents": [{"it": "“E tu credi che i fiori...”", "zh": "你相信，花儿……", "t": [100, 1425]}]}, {"id": "ch07p15", "audio": true, "sents": [{"it": "“Ma no!", "zh": "但不是！", "t": [100, 875]}, {"it": "Ma no!", "zh": "但不是！", "t": [875, 1650]}, {"it": "Non credo un bel niente!", "zh": "我什么都不信！", "t": [1650, 3500]}, {"it": "Ho detto la prima cosa che capitava.", "zh": "我说出了最先想到的话。", "t": [3500, 5712]}, {"it": "Ho faccende ben più serie a cui pensare, io!”", "zh": "我还有更严肃的事情要思考！”", "t": [5712, 8462]}]}, {"id": "ch07p16", "audio": true, "sents": [{"it": "Mi guardò stupefatto.", "zh": "他惊讶地望着我。", "t": [100, 1563]}]}, {"id": "ch07p17", "audio": true, "sents": [{"it": "“Faccende ben più serie!”", "zh": "这事情要紧多了！", "t": [100, 1638]}]}, {"id": "ch07p18", "audio": true, "sents": [{"it": "Mi vedeva con il martello in mano, le dita nere di grasso, alle prese con un oggetto che a lui sembrava molto brutto.", "zh": "他见我手持锤子，指间沾满油污，正忙于一件在他看来颇为丑陋的物件。", "t": [100, 6937]}]}, {"id": "ch07p19", "audio": true, "sents": [{"it": "“Parli come gli adulti!”", "zh": "你说话就像大人！", "t": [100, 1463]}]}, {"id": "ch07p20", "audio": true, "sents": [{"it": "Provai un po’ di vergogna.", "zh": "我感到有些羞愧。", "t": [100, 1788]}, {"it": "Ma lui, implacabile, aggiunse:", "zh": "然而，他毫不留情地补充道：", "t": [1788, 4450]}]}, {"id": "ch07p21", "audio": true, "sents": [{"it": "“Confondi tutto...", "zh": "你把一切都搞混了……", "t": [100, 1375]}, {"it": "mescoli tutto!”", "zh": "你把一切都搞混了！", "t": [1375, 2338]}]}, {"id": "ch07p22", "audio": true, "sents": [{"it": "Era davvero molto irritato.", "zh": "他真的气坏了。", "t": [100, 1850]}, {"it": "Scuoteva al vento i capelli dorati:", "zh": "风中摇曳着金发。", "t": [1850, 3862]}]}, {"id": "ch07p23", "audio": true, "sents": [{"it": "“Conosco un pianeta dove c’è un signore con la faccia paonazza.", "zh": "我知道一个星球上住着一位红脸先生。", "t": [100, 3825]}, {"it": "Non ha mai annusato un fiore.", "zh": "他从没闻过一朵花。", "t": [3825, 5625]}, {"it": "Non ha mai guardato una stella.", "zh": "他从没看过一颗星星。", "t": [5625, 7488]}, {"it": "Non ha mai amato nessuno.", "zh": "他从没爱过任何人。", "t": [7488, 9188]}, {"it": "Non ha mai fatto altro che addizioni.", "zh": "他从未做过别的，只是做加法。", "t": [9188, 11425]}, {"it": "E tutto il giorno ripete come te: ‘Sono un uomo serio!", "zh": "他整天就像你一样，反复地唠叨：“我是一个认真的人！”", "t": [11425, 15025]}, {"it": "Sono un uomo serio!’ e questo lo riempie di orgoglio.", "zh": "“我是一个认真的人！”这话让他充满自豪。", "t": [15025, 18550]}, {"it": "Ma non è un uomo, è un fungo!”", "zh": "他并非凡人，乃是一朵蘑菇！", "t": [18550, 20687]}]}, {"id": "ch07p24", "audio": true, "sents": [{"it": "“Un cosa?”", "zh": "“这究竟是什么？”", "t": [100, 787]}]}, {"id": "ch07p25", "audio": true, "sents": [{"it": "“Un fungo.”", "zh": "那是一朵蘑菇。", "t": [100, 888]}]}, {"id": "ch07p26", "audio": true, "sents": [{"it": "Adesso il piccolo principe era pallido di rabbia.", "zh": "小王子气得脸色苍白。", "t": [100, 2863]}]}, {"id": "ch07p27", "audio": true, "sents": [{"it": "“Da milioni di anni i fiori mettono le spine.", "zh": "自百万年以来，花儿便长着刺。", "t": [100, 2775]}, {"it": "Da milioni di anni le pecore mangiano ugualmente i fiori.", "zh": "自百万年以来，羊也一并吞噬着花朵。", "t": [2775, 6138]}, {"it": "E non è forse una cosa seria cercare di capire perché i fiori si danno tanta pena per mettere spine che non servono a niente?", "zh": "难道探寻花儿为何费尽心思长出无用的刺，不是一件严肃的事吗？", "t": [6138, 12912]}, {"it": "Non è forse importante la guerra delle pecore e dei fiori?", "zh": "羊与花的战争，难道这不重要吗？", "t": [12912, 16312]}, {"it": "Non è forse più seria e importante delle addizioni di un signore grasso e rosso?", "zh": "这难道不比那位红脸胖子的加法更严肃、更重要吗？", "t": [16312, 20962]}, {"it": "E se io conosco un fiore unico al mondo, che esiste soltanto sul mio pianeta, e che una piccola pecora improvvisamente può distruggere, così, una mattina, senza neppure rendersene conto, non è forse importante?”", "zh": "若我知晓这朵世间独一无二的花，仅存在于我的星球，而一只小绵羊却在不经意间，一个清晨将其毁去，这难道不是重要的事吗？", "t": [20962, 34675]}]}, {"id": "ch07p28", "audio": true, "sents": [{"it": "Arrossì, poi continuò:", "zh": "于是，他继续说道：", "t": [100, 1975]}]}, {"id": "ch07p29", "audio": true, "sents": [{"it": "“Chi ama un fiore di cui esiste un solo esemplare fra milioni e milioni di stelle, basta che guardi le stelle e si sente felice.", "zh": "爱上一朵世间独一无二的花，只需仰望星空，便觉幸福满怀。", "t": [100, 7500]}, {"it": "Può pensare: ‘Il mio fiore è lì da qualche parte...’.", "zh": "我的花儿就在某个地方。", "t": [7500, 10638]}, {"it": "Ma se la pecora mangia il fiore, è come se di colpo tutte le stelle si spegnessero!", "zh": "若羊儿吃了这朵花，仿佛瞬间所有的星星都熄灭了。", "t": [10638, 15638]}, {"it": "E ti sembra che questo non sia importante!”", "zh": "这难道不重要吗？", "t": [15638, 17950]}]}, {"id": "ch07p30", "audio": true, "sents": [{"it": "Non poté dire altro.", "zh": "他无法再说别的。", "t": [100, 1575]}, {"it": "All’improvviso scoppiò in singhiozzi.", "zh": "突然放声大哭。", "t": [1575, 4150]}, {"it": "Era scesa la notte.", "zh": "夜幕降临。", "t": [4150, 5612]}, {"it": "Avevo posato i miei utensili.", "zh": "我放下我的工具。", "t": [5612, 7512]}, {"it": "Non mi importava niente del martello, del bullone, della sete e della morte.", "zh": "锤子、螺栓、干渴与死亡，我皆不萦怀。", "t": [7512, 12400]}, {"it": "Su una stella, su un pianeta, il mio, la Terra, c’era un piccolo principe da consolare!", "zh": "在遥远的星球上，我的星球——地球上，有一个小王子需要安慰！", "t": [12400, 18938]}, {"it": "Lo presi tra le braccia.", "zh": "将他紧紧抱在怀里。", "t": [18938, 20688]}, {"it": "Lo cullai.", "zh": "轻抚他。", "t": [20688, 21738]}, {"it": "Gli dicevo: “Il fiore che ami non è in pericolo...", "zh": "我对他说：“你爱的那朵花并无危险……”", "t": [21738, 24838]}, {"it": "Disegnerò una museruola per la tua pecora...", "zh": "我将为你的绵羊画一个口罩……", "t": [24838, 27800]}, {"it": "E per il tuo fiore disegnerò un’armatura...", "zh": "为你的玫瑰绘一副盔甲……", "t": [27800, 30462]}, {"it": "Io...”.", "zh": "我抚慰他：“你爱的那朵花不会有危险的……我给你的绵羊画一个口罩……我给你的花儿画一副铠甲……我……”我也不知道我还说了什么话，只觉得自己笨嘴笨舌，不懂得该怎样安慰他，打动他……眼泪的王国太神秘了。", "t": [30462, 31188]}, {"it": "Non sapevo cosa dire.", "zh": "我不知该如何开口。", "t": [31188, 32712]}, {"it": "Mi sentivo impacciato.", "zh": "我感到局促不安。", "t": [32712, 34350]}, {"it": "Non sapevo come avvicinarmi a lui, dove trovare un accesso al suo cuore...", "zh": "不知如何靠近他，何处能触及他的心房……", "t": [34350, 38738]}, {"it": "È talmente misterioso, il paese delle lacrime!", "zh": "泪之国的奥秘，难以言表。", "t": [38738, 41825]}]}]}, {"id": "ch08", "title_it": "VIII", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"it": "Presto imparai a conoscere meglio quel fiore.", "zh": "很快，我更深入地了解了那朵花。", "t": [100, 2675]}, {"it": "Sul pianeta del piccolo principe c’erano sempre stati alcuni fiori molto semplici, con una sola raggiera di petali, che occupavano poco spazio e non disturbavano nessuno.", "zh": "小王子的星球上，始终生长着一些极为简单的花朵，花瓣仅一环，占地不多，也不扰人。", "t": [2675, 13100]}, {"it": "Apparivano un mattino nell’erba e la sera morivano.", "zh": "清晨在草地上绽放，夜晚便凋零。", "t": [13100, 16362]}, {"it": "Poi un giorno era spuntato quello, da un seme giunto da chissà dove, e il piccolo principe aveva tenuto d’occhio quel germoglio diverso da tutti gli altri.", "zh": "那日，一朵来自不知名之处的种子破土而出，小王子便开始留意这与众不同的嫩芽。", "t": [16362, 25450]}, {"it": "Poteva essere un nuovo genere di baobab.", "zh": "可能是一种新的猴面包树。", "t": [25450, 28012]}, {"it": "Ben presto però l’arbusto smise di crescere e cominciò a preparare un fiore.", "zh": "很快，这灌木停止了生长，开始孕育一朵花。", "t": [28012, 32662]}, {"it": "Il piccolo principe assisteva allo schiudersi di un enorme bocciolo e sentiva che ne sarebbe venuta un’apparizione miracolosa, ma la corolla indugiava, e si faceva bella, chiusa nella sua camera verde.", "zh": "小王子凝视着那硕大的花蕾绽放，预感它将呈现奇迹般的景象，然而花瓣却迟迟未展，仿佛在绿色的屋子里精心打扮。", "t": [32662, 44412]}, {"it": "Con cura sceglieva i colori.", "zh": "她精心挑选着色彩。", "t": [44412, 46288]}, {"it": "Si vestiva piano, accomodando i petali a uno a uno.", "zh": "她缓缓地，一片片地搭配她的花瓣。", "t": [46288, 49950]}, {"it": "Non voleva uscire tutta stropicciata, come fanno i papaveri.", "zh": "她不愿像罂粟花那样，皱巴巴地就露面。", "t": [49950, 53750]}, {"it": "Voleva mostrarsi solo nel pieno fulgore della propria bellezza.", "zh": "她想在美丽最盛时展露芳华。", "t": [53750, 57688]}, {"it": "Eh sì!", "zh": "唉，是啊！", "t": [57688, 58538]}, {"it": "Era molto vanitosa.", "zh": "她极爱虚荣。", "t": [58538, 60012]}, {"it": "La sua segreta toilette era durata giorni e giorni.", "zh": "她的秘密梳妆持续了数日之久。", "t": [60012, 63250]}, {"it": "Ed ecco che una mattina, con il sorgere del sole, era apparsa una rosa.", "zh": "太阳初升，玫瑰露面。", "t": [63250, 67938]}]}, {"id": "ch08p01", "audio": true, "sents": [{"it": "Si era preparata con grande cura, e tuttavia disse sbadigliando:", "zh": "她精心打扮了许久，却打着哈欠说：", "t": [100, 3738]}]}, {"id": "ch08p02", "audio": true, "sents": [{"it": "“Ah!", "zh": "唉！", "t": [100, 750]}, {"it": "Mi sono svegliata proprio ora...", "zh": "我刚醒来……", "t": [750, 2562]}, {"it": "Scusatemi...", "zh": "请原谅……", "t": [2562, 3650]}, {"it": "Sono ancora tutta in disordine...”", "zh": "我仍是一团糟……", "t": [3650, 5463]}]}, {"id": "ch08p03", "audio": true, "sents": [{"it": "Il piccolo principe non poté trattenere la propria ammirazione:", "zh": "小王子忍不住赞叹不已：", "t": [100, 3500]}]}, {"id": "ch08p04", "audio": true, "sents": [{"it": "“Come sei bella!”", "zh": "您真美啊！", "t": [100, 1063]}]}, {"id": "ch08p05", "audio": true, "sents": [{"it": "“Eh sì,” rispose piano la rosa.", "zh": "“是啊，”玫瑰轻声回答。", "t": [100, 2075]}, {"it": "“E sono nata insieme con il sole...”", "zh": "我与太阳同日而生……", "t": [2075, 3913]}]}, {"id": "ch08p06", "audio": true, "sents": [{"it": "Il piccolo principe capì subito che non era granché modesta, ma era così toccante!", "zh": "小王子立刻明白，她并不谦虚，却如此动人。", "t": [100, 5088]}]}, {"id": "ch08p07", "audio": true, "sents": [{"it": "“Credo sia ora di colazione,” aveva poi aggiunto, “saresti così gentile da pensare a me...”", "zh": "“现在正是用早餐的时候了，”她接着说，“你能不能为我着想一下……”", "t": [100, 4926]}]}, {"id": "ch08p08", "audio": true, "sents": [{"it": "E il piccolo principe, confuso, era andato a prendere un innaffiatoio pieno di acqua fresca e aveva servito la rosa.", "zh": "小王子困惑地取来一满壶清凉的清水，为玫瑰浇水。", "t": [100, 7312]}]}, {"id": "ch08p09", "audio": true, "sents": [{"it": "Ben presto lei aveva cominciato a tormentarlo con la sua vanità un po’ ombrosa.", "zh": "她很快便开始用那略显阴暗的虚荣心折磨他。", "t": [100, 4862]}, {"it": "Un giorno, per esempio, parlando delle sue quattro spine aveva detto al principe:", "zh": "有一天，比如，她向小王子提起她那四根刺的用途。", "t": [4862, 9825]}]}, {"id": "ch08p10", "audio": true, "sents": [{"it": "“Che vengano pure, le tigri, con i loro artigli!”", "zh": "老虎们，尽管带着锋利的爪子来吧！", "t": [100, 3276]}]}, {"id": "ch08p11", "audio": true, "sents": [{"it": "“Sul mio pianeta non ci sono tigri,” aveva obiettato il principe, “e comunque le tigri non mangiano l’erba.”", "zh": "“在我的星球上没有老虎，”小王子曾断言，“而且老虎也不吃草。”", "t": [100, 5862]}]}, {"id": "ch08p12", "audio": true, "sents": [{"it": "“Ma io non sono erba,” aveva risposto dolcemente la rosa.", "zh": "“我可不是草，”玫瑰轻声回答。", "t": [100, 3238]}]}, {"id": "ch08p13", "audio": true, "sents": [{"it": "“Scusami...!”", "zh": "请原谅……", "t": [100, 800]}]}, {"id": "ch08p14", "audio": true, "sents": [{"it": "“Non ho nessunissima paura delle tigri, ma ho il terrore delle correnti d’aria.", "zh": "我并不怎么怕老虎，但害怕风。", "t": [100, 4612]}, {"it": "Non avresti un paravento?”", "zh": "您没有屏风吗？", "t": [4612, 6050]}]}, {"id": "ch08p15", "audio": true, "sents": [{"it": "“Il terrore delle correnti d’aria...", "zh": "风之恐惧...", "t": [100, 2250]}, {"it": "È una bella sfortuna, per una pianta,” aveva osservato il piccolo principe.", "zh": "这是一场不幸，对于一个植物来说。", "t": [2250, 6925]}, {"it": "“Questo fiore è proprio complicato...”", "zh": "这朵花真是复杂得很……", "t": [6925, 8787]}]}, {"id": "ch08p16", "audio": true, "sents": [{"it": "“La sera devi mettermi sotto una campana di vetro.", "zh": "你晚上得给我罩上玻璃罩。", "t": [100, 3262]}, {"it": "Qui da te fa molto freddo.", "zh": "这里很冷。", "t": [3262, 5038]}, {"it": "È un posto proprio disagevole.", "zh": "真是个令人不快的所在。", "t": [5038, 7062]}, {"it": "Da dove vengo io...”", "zh": "我从哪里来……", "t": [7062, 8124]}]}, {"id": "ch08p17", "audio": true, "sents": [{"it": "Ma la rosa si era interrotta.", "zh": "玫瑰突然打住了。", "t": [100, 2175]}, {"it": "Era giunta lì sotto forma di seme.", "zh": "那日，她以种子之形降临。", "t": [2175, 4425]}, {"it": "Non poteva sapere nulla degli altri mondi.", "zh": "她无法了解其他星球。", "t": [4425, 6850]}, {"it": "Umiliata per essere stata sorpresa a inventare quella grossolana bugia, aveva tossito due o tre volte, per mettere il principe dalla parte del torto:", "zh": "羞愧于被揭穿那荒谬的谎言，她咳嗽了两三声，企图将错处推到小王子身上：", "t": [6850, 15363]}]}, {"id": "ch08p18", "audio": true, "sents": [{"it": "“Allora, questo paravento?”", "zh": "那么，这扇屏风呢？", "t": [100, 1900]}]}, {"id": "ch08p19", "audio": true, "sents": [{"it": "“Stavo andando a prenderlo, ma tu mi parlavi!”", "zh": "我正要去取，你却和我说话！", "t": [100, 2762]}]}, {"id": "ch08p20", "audio": true, "sents": [{"it": "E la rosa aveva accentuato la tosse per farlo sentire in colpa.", "zh": "玫瑰加重了咳嗽，让他感到愧疚。", "t": [100, 3650]}]}, {"id": "ch08p21", "audio": true, "sents": [{"it": "Così, nonostante la buona volontà del proprio amore, ben presto il piccolo principe aveva dubitato di lei.", "zh": "尽管小王子满心爱意，但很快便对她产生了怀疑。", "t": [100, 6612]}, {"it": "Aveva preso sul serio parole senza importanza, ed era diventato molto infelice.", "zh": "他认真对待了无关紧要的话语，因而变得非常不幸。", "t": [6612, 11588]}]}, {"id": "ch08p22", "audio": true, "sents": [{"it": "“Non avrei dovuto ascoltarla,” mi confidò un giorno, “non bisogna mai ascoltare i fiori.", "zh": "那天，他向我吐露：“我本不该听她的话。”", "t": [100, 5200]}, {"it": "Bisogna guardarli e annusarli.", "zh": "需得呵护与细嗅。", "t": [5200, 7362]}, {"it": "La mia rosa profumava tutto il pianeta, ma io non sapevo gioirne.", "zh": "我的玫瑰芬芳了整个星球，我却不知如何欢喜。", "t": [7362, 11462]}, {"it": "La storia degli artigli, che mi aveva così irritato, avrebbe dovuto intenerirmi...”", "zh": "那关于爪子的故事，本应让我心软……", "t": [11462, 16400]}]}, {"id": "ch08p23", "audio": true, "sents": [{"it": "E mi confidò ancora:", "zh": "他还向我吐露：", "t": [100, 1387]}]}, {"id": "ch08p24", "audio": true, "sents": [{"it": "“Non ho capito niente!", "zh": "我完全不懂！", "t": [100, 1688]}, {"it": "Avrei dovuto giudicarla dalle sue azioni e non dalle sue parole.", "zh": "我应该根据她的行为而非言语来评判她。", "t": [1688, 5338]}, {"it": "Mi profumava e mi illuminava.", "zh": "它为我增添了芬芳，照亮了我的生命。", "t": [5338, 7312]}, {"it": "Non avrei mai dovuto andarmene!", "zh": "我本不该离她而去。", "t": [7312, 9275]}, {"it": "Avrei dovuto intuire l’affetto che stava dietro i suoi poveri trucchi.", "zh": "我本应洞察她那拙劣手段背后的深情。", "t": [9275, 13100]}, {"it": "I fiori sono così contraddittori!", "zh": "花儿是如此矛盾。", "t": [13100, 15450]}, {"it": "Ma ero troppo giovane per saperla amare.”", "zh": "那时我太年轻，不懂如何去爱。", "t": [15450, 17650]}]}]}, {"id": "ch09", "title_it": "IX", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"it": "Credo che per la sua fuga approfittò di una migrazione di uccelli selvatici.", "zh": "他或许是在鸟儿迁徙时悄悄离去的。", "t": [100, 4825]}, {"it": "Il mattino della partenza rassettò per bene il pianeta.", "zh": "清晨，他仔细整理了那颗星球。", "t": [4825, 8400]}, {"it": "Pulì con cura i vulcani attivi.", "zh": "他细心地清理了活火山。", "t": [8400, 10562]}, {"it": "Ne possedeva due.", "zh": "他拥有两座。", "t": [10562, 12038]}, {"it": "Ed erano molto comodi per scaldare la colazione.", "zh": "早餐加热颇为方便。", "t": [12038, 15000]}, {"it": "Possedeva anche un vulcano spento.", "zh": "他还拥有一座熄灭的火山。", "t": [15000, 17325]}, {"it": "Ma, come diceva lui: “Non si sa mai!”.", "zh": "然而，正如他所说：“世事难料！”", "t": [17325, 20212]}, {"it": "Quindi pulì anche il vulcano spento.", "zh": "于是，他也清理了那座熄灭的火山。", "t": [20212, 22700]}, {"it": "Se sono tenuti puliti, i vulcani bruciano piano e in maniera uniforme, senza eruzioni.", "zh": "火山清理得当，火焰便平稳均匀地燃烧，不会喷发。", "t": [22700, 28538]}, {"it": "Le eruzioni vulcaniche sono come i fuochi nel caminetto.", "zh": "火山喷发犹如壁炉中的火焰。", "t": [28538, 32075]}, {"it": "Naturalmente sulla Terra siamo troppo piccoli per pulire i vulcani.", "zh": "自然，在地球上，我们太小了，无法清理火山。", "t": [32075, 36100]}, {"it": "Per questo ci causano tanti problemi.", "zh": "因此，它们给我们带来诸多麻烦。", "t": [36100, 38200]}]}, {"id": "ch09p01", "audio": true, "sents": [{"it": "Con un po’ di malinconia, il piccolo principe strappò anche gli ultimi germogli di baobab.", "zh": "带着一丝忧郁，小王子拔除了最后几株猴面包树苗。", "t": [100, 5738]}, {"it": "Pensava che non sarebbe mai più tornato.", "zh": "他以为从此不再归来。", "t": [5738, 8162]}, {"it": "Ma quella mattina tutti i lavori consueti gli parvero molto piacevoli.", "zh": "那天早晨，所有日常琐事都让他感到格外愉悦。", "t": [8162, 12588]}, {"it": "E quando innaffiò un’ultima volta la rosa, e si accinse a metterla sotto la campana, scoprì di aver voglia di piangere.", "zh": "最后一次给玫瑰浇水，准备给她罩上玻璃罩，他突然觉得想要哭泣。", "t": [12588, 19500]}]}, {"id": "ch09p02", "audio": true, "sents": [{"it": "“Addio,” le disse.", "zh": "“再见了，”他对她说。", "t": [100, 1287]}]}, {"id": "ch09p03", "audio": true, "sents": [{"it": "Ma lei non gli rispose.", "zh": "她没有回答。", "t": [100, 1538]}]}, {"id": "ch09p04", "audio": true, "sents": [{"it": "“Addio,” ripeté.", "zh": "“再见了，”他又说。", "t": [100, 1100]}]}, {"id": "ch09p05", "audio": true, "sents": [{"it": "La rosa tossì.", "zh": "玫瑰咳嗽。", "t": [100, 1425]}, {"it": "Ma non era a causa del raffreddore.", "zh": "并非因感冒所致。", "t": [1425, 3462]}]}, {"id": "ch09p06", "audio": true, "sents": [{"it": "“Sono stata sciocca,” gli disse infine.", "zh": "她终于说：“我以前真傻。”", "t": [100, 2488]}, {"it": "“Ti chiedo scusa.", "zh": "请原谅。", "t": [2488, 3712]}, {"it": "Cerca di essere felice.”", "zh": "努力寻找幸福吧。", "t": [3712, 5087]}]}, {"id": "ch09p07", "audio": true, "sents": [{"it": "Lo stupì l’assenza di rimproveri.", "zh": "她没有责备的意思。", "t": [100, 2325]}, {"it": "Se ne stava lì, tutto sottosopra, con la campana di vetro in mano.", "zh": "他手握玻璃钟，整个世界颠倒混乱。", "t": [2325, 6762]}, {"it": "Non capiva quella dolcezza tranquilla.", "zh": "那宁静的甜美他无法理解。", "t": [6762, 8900]}]}, {"id": "ch09p08", "audio": true, "sents": [{"it": "“Insomma, io ti amo,” gli disse la rosa.", "zh": "“总之，我爱你，”玫瑰说。", "t": [100, 2900]}, {"it": "“E per colpa mia non l’hai capito.", "zh": "都是我的错，你并未察觉。", "t": [2900, 4775]}, {"it": "Non importa.", "zh": "无关紧要。", "t": [4775, 5925]}, {"it": "Ma sei stato stupido quanto me.", "zh": "你和我一样傻。", "t": [5925, 7950]}, {"it": "Cerca di essere felice...", "zh": "努力寻找幸福吧……", "t": [7950, 9662]}, {"it": "Lascia stare quella campana, non la voglio più.”", "zh": "别管那个钟，我再也不想要了。", "t": [9662, 12250]}]}, {"id": "ch09p09", "audio": true, "sents": [{"it": "“Ma il vento...”", "zh": "可是风……", "t": [100, 1062]}]}, {"id": "ch09p10", "audio": true, "sents": [{"it": "“Non sono poi così raffreddata...", "zh": "我并非如此怕冷……", "t": [100, 2112]}, {"it": "L’aria fresca della notte mi farà bene.", "zh": "夜间的清新空气将对我大有裨益。", "t": [2112, 4512]}, {"it": "In fondo, sono un fiore.”", "zh": "归根结底，我只是一朵花。", "t": [4512, 6150]}]}, {"id": "ch09p11", "audio": true, "sents": [{"it": "“Ma gli animali...”", "zh": "“可是动物……”", "t": [100, 1012]}]}, {"id": "ch09p12", "audio": true, "sents": [{"it": "“Devo pur sopportare due o tre bruchi se voglio conoscere le farfalle.", "zh": "我若想认识蝴蝶，就得忍受两三条毛虫。", "t": [100, 4225]}, {"it": "Pare che siano bellissime.", "zh": "宛如仙境。", "t": [4225, 5950]}, {"it": "Altrimenti chi mi verrà a trovare?", "zh": "否则，谁来拜访我呢？", "t": [5950, 8062]}, {"it": "Tu sarai lontano.", "zh": "你将远行。", "t": [8062, 9400]}, {"it": "Quanto alle bestie grandi, non ho paura.", "zh": "对于大动物，我并不害怕。", "t": [9400, 12125]}, {"it": "Ho i miei artigli.”", "zh": "我有我的刺。", "t": [12125, 13262]}]}, {"id": "ch09p13", "audio": true, "sents": [{"it": "E mostrava ingenuamente le sue quattro spine.", "zh": "她天真地露出了她的四根刺。", "t": [100, 2888]}, {"it": "Poi aggiunse:", "zh": "然后他又说：", "t": [2888, 3813]}]}, {"id": "ch09p14", "audio": true, "sents": [{"it": "“Non tirarla tanto per le lunghe, che è seccante.", "zh": "别拖得太久，免得无聊。", "t": [100, 3375]}, {"it": "Hai deciso di partire, e allora vai.”", "zh": "你既已决定启程，那就去吧。", "t": [3375, 5600]}]}, {"id": "ch09p15", "audio": true, "sents": [{"it": "Non voleva che lui la vedesse piangere.", "zh": "她不愿让他看到自己哭泣。", "t": [100, 2438]}, {"it": "Era un fiore talmente orgoglioso...", "zh": "她是一朵如此骄傲的花儿……", "t": [2438, 4437]}]}]}, {"id": "ch10", "title_it": "X", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"it": "Lui si trovava nella regione degli asteroidi 325, 326, 327, 328, 329 e 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 10038]}, {"it": "Decise quindi di visitarli per cercarvi un’occupazione e per istruirsi.", "zh": "于是决定去拜访它们，以寻找一份工作并增长见识。", "t": [10038, 16062]}]}, {"id": "ch10p01", "audio": true, "sents": [{"it": "Il primo era abitato da un re.", "zh": "那颗星球上住着一位国王。", "t": [100, 2088]}, {"it": "Il re sedeva vestito di porpora e di ermellino su un trono semplicissimo e tuttavia maestoso.", "zh": "国王身着紫红袍，坐在一张简单却威严的宝座上。", "t": [2088, 7424]}]}, {"id": "ch10p02", "audio": true, "sents": [{"it": "“Ah!", "zh": "啊！", "t": [100, 750]}, {"it": "Ecco un suddito,” esclamò il re quando scorse il piccolo principe.", "zh": "这是一个臣民，”国王在小王子出现时大声宣布。", "t": [750, 4625]}]}, {"id": "ch10p03", "audio": true, "sents": [{"it": "E il piccolo principe si domandò:", "zh": "小王子心想：这是怎么回事？", "t": [100, 1963]}]}, {"id": "ch10p04", "audio": true, "sents": [{"it": "“Come fa a riconoscermi se non mi ha mai visto?”", "zh": "他从未见过我，怎么认得出我呢？", "t": [100, 2462]}]}, {"id": "ch10p05", "audio": true, "sents": [{"it": "Non sapeva che per i re il mondo è alquanto semplificato.", "zh": "国王们认为世界相当简单。", "t": [100, 3875]}, {"it": "Tutti gli uomini sono sudditi.", "zh": "世人皆为臣民。", "t": [3875, 5600]}]}, {"id": "ch10p06", "audio": true, "sents": [{"it": "“Avvicinati, che ti voglio vedere meglio,” gli disse il re, tutto fiero di essere finalmente il re di qualcuno.", "zh": "“走近些，我要好好看看你，”国王骄傲地说，他终于成了某个人的国王。", "t": [100, 6387]}]}, {"id": "ch10p07", "audio": true, "sents": [{"it": "Il piccolo principe cercò con gli occhi dove sedersi, ma il pianeta era tutto occupato dallo splendido mantello di ermellino.", "zh": "小王子四处张望，寻找可以坐下之处，但整个星球已被那件华丽的鼬皮大衣占据了。", "t": [100, 7575]}, {"it": "Quindi rimase in piedi e, poiché era stanco, sbadigliò.", "zh": "于是他站着，因为疲惫，打了个哈欠。", "t": [7575, 11338]}]}, {"id": "ch10p08", "audio": true, "sents": [{"it": "“È contrario all’etichetta sbadigliare in presenza di un re,” gli disse il monarca.", "zh": "在国王面前打哈欠，有失礼节。", "t": [100, 4562]}, {"it": "“Te lo proibisco.”", "zh": "我禁止你这样做。", "t": [4562, 5576]}]}, {"id": "ch10p09", "audio": true, "sents": [{"it": "“Non posso evitarlo,” rispose il piccolo principe, imbarazzato.", "zh": "我忍不住，小王子尴尬地回答。", "t": [100, 4362]}, {"it": "“Ho fatto un lungo viaggio e non ho dormito...”", "zh": "长途跋涉，未曾安眠……", "t": [4362, 6474]}]}, {"id": "ch10p10", "audio": true, "sents": [{"it": "“Allora,” gli disse il re, “ti ordino di sbadigliare.", "zh": "“那么，”国王说，“我命令你打哈欠。", "t": [100, 3512]}, {"it": "Sono anni che non vedo nessuno sbadigliare.", "zh": "多年未见有人打哈欠了。", "t": [3512, 6100]}, {"it": "E per me gli sbadigli sono vere e proprie curiosità.", "zh": "打哈欠对我来说，是真正的奇闻趣事。", "t": [6100, 9412]}, {"it": "Forza!", "zh": "加油！", "t": [9412, 10300]}, {"it": "Sbadiglia di nuovo.", "zh": "再打一个哈欠。", "t": [10300, 11712]}, {"it": "È un ordine.”", "zh": "这是命令。", "t": [11712, 12487]}]}, {"id": "ch10p11", "audio": true, "sents": [{"it": "“Mi mette soggezione...", "zh": "他使我臣服……", "t": [100, 1688]}, {"it": "non riesco...” fece il piccolo principe arrossendo.", "zh": "小王子涨红了脸。", "t": [1688, 4788]}]}, {"id": "ch10p12", "audio": true, "sents": [{"it": "“Hum!", "zh": "哼！", "t": [100, 838]}, {"it": "Hum!” rispose il re.", "zh": "哼！国王应道。", "t": [838, 2925]}, {"it": "“Allora...", "zh": "那时……", "t": [2925, 3788]}, {"it": "allora ti ordino di sbadigliare e poi di non...”", "zh": "那么，我命令你打哈欠，然后别再打。", "t": [3788, 6600]}]}, {"id": "ch10p13", "audio": true, "sents": [{"it": "Farfugliava e sembrava indispettito.", "zh": "他烦躁不安，似乎很不高兴。", "t": [100, 2362]}]}, {"id": "ch10p14", "audio": true, "sents": [{"it": "Al re infatti stava molto a cuore che la sua autorità fosse rispettata.", "zh": "他非常看重自己的权威受到尊重。", "t": [100, 4312]}, {"it": "Non tollerava la disobbedienza.", "zh": "不容许违抗。", "t": [4312, 6388]}, {"it": "Era un monarca assoluto.", "zh": "这是一个绝对君主。", "t": [6388, 8050]}, {"it": "Ma poiché era buono, dava ordini ragionevoli.", "zh": "然而，他心地善良，下达的命令合情合理。", "t": [8050, 10863]}]}, {"id": "ch10p15", "audio": true, "sents": [{"it": "“Se ordinassi,” diceva abitualmente, “se ordinassi a un generale di trasformarsi in un uccello marino, e se il generale non obbedisse, non sarebbe colpa del generale.", "zh": "“若是我下令，若是一个将军不遵从，那错不在将军，而在我自己。”", "t": [100, 10075]}, {"it": "Sarebbe colpa mia.”", "zh": "这是我的错。", "t": [10075, 11176]}]}, {"id": "ch10p16", "audio": true, "sents": [{"it": "“Posso sedermi?” domandò timidamente il piccolo principe.", "zh": "小王子怯怯地问：“我可以坐下来吗？”", "t": [100, 3737]}]}, {"id": "ch10p17", "audio": true, "sents": [{"it": "“Ti ordino di sederti,” gli rispose il re, tirando cerimoniosamente a sé un lembo del mantello di ermellino.", "zh": "“我命令你坐下，”国王威严地一挥白鼬皮袍角回应道。", "t": [100, 6237]}]}, {"id": "ch10p18", "audio": true, "sents": [{"it": "Ma il piccolo principe era perplesso.", "zh": "小王子感到困惑。", "t": [100, 2538]}, {"it": "Il pianeta era minuscolo.", "zh": "这颗星球小得惊人。", "t": [2538, 4300]}, {"it": "Su cosa poteva mai regnare il re?", "zh": "国王统治着什么？", "t": [4300, 6187]}]}, {"id": "ch10p19", "audio": true, "sents": [{"it": "“Maestà...” gli disse, “mi scusi se ho l’ardire di farle una domanda...”", "zh": "“陛下……请原谅我斗胆问您一个问题……”", "t": [100, 4500]}]}, {"id": "ch10p20", "audio": true, "sents": [{"it": "“Ti ordino di farmi una domanda,” si affrettò a dire il re.", "zh": "“我命令你向我提个问题。”国王急忙说。", "t": [100, 3087]}]}, {"id": "ch10p21", "audio": true, "sents": [{"it": "“Maestà...", "zh": "威严……", "t": [100, 1000]}, {"it": "lei su che cosa regna?”", "zh": "陛下，您统治着什么？", "t": [1000, 2276]}]}, {"id": "ch10p22", "audio": true, "sents": [{"it": "“Su tutto,” rispose il re, con assoluto candore.", "zh": "“统治一切，”国王以绝对的坦率回答。", "t": [100, 3162]}]}, {"id": "ch10p23", "audio": true, "sents": [{"it": "Con un gesto discreto il re indicò il proprio pianeta, gli altri pianeti e le stelle.", "zh": "国王轻轻一指，便指向了他的星球、其他星球以及那些星星。", "t": [100, 5150]}]}, {"id": "ch10p24", "audio": true, "sents": [{"it": "“Su tutto questo?” disse il piccolo principe.", "zh": "“这所有的一切？”小王子说。", "t": [100, 2963]}]}, {"id": "ch10p25", "audio": true, "sents": [{"it": "“Su tutto questo...” rispose il re.", "zh": "“统治这一切……”国王回答道。", "t": [100, 2300]}]}, {"id": "ch10p26", "audio": true, "sents": [{"it": "Infatti non era soltanto un monarca assoluto, era anche un monarca universale.", "zh": "他不仅是绝对的君主，还是宇宙的君主。", "t": [100, 4924]}]}, {"id": "ch10p27", "audio": true, "sents": [{"it": "“E le stelle le obbediscono?”", "zh": "星星都服从吗？", "t": [100, 1612]}]}, {"id": "ch10p28", "audio": true, "sents": [{"it": "“Certamente,” disse il re.", "zh": "当然，国王说。", "t": [100, 1925]}, {"it": "“Io non tollero la disobbedienza.”", "zh": "我无法容忍违抗。", "t": [1925, 3788]}]}, {"id": "ch10p29", "audio": true, "sents": [{"it": "Il piccolo principe rimase incantato da tanto potere.", "zh": "小王子被如此大的权力所迷醉。", "t": [100, 3638]}, {"it": "Se l’avesse avuto, avrebbe potuto assistere non a quarantaquattro ma a settantadue, o anche a cento, o anche a duecento tramonti nello stesso giorno, senza dover mai spostare la sedia!", "zh": "若是他能，便能观赏到七十二次，甚至一百次，或两百次日落，而无需挪动椅子！", "t": [3638, 15188]}, {"it": "E, poiché si sentiva un po’ triste al ricordo del piccolo pianeta abbandonato, si azzardò a chiedere un favore al re:", "zh": "由于想起那颗被遗弃的小行星而感到有些伤感，小王子便胆怯地向国王提出一个请求：", "t": [15188, 22176]}]}, {"id": "ch10p30", "audio": true, "sents": [{"it": "“Vorrei tanto vedere un tramonto...", "zh": "我多么想看一场日落……", "t": [100, 2088]}, {"it": "Per piacere...", "zh": "想到被他遗弃的小行星，他有点伤感惆怅。", "t": [2088, 3188]}, {"it": "Ordini al sole di tramontare...”", "zh": "命令太阳落山吧……", "t": [3188, 4926]}]}, {"id": "ch10p31", "audio": true, "sents": [{"it": "“Se ordinassi a un generale di volare di fiore in fiore come una farfalla, o di scrivere una tragedia o di trasformarsi in un uccello marino, e se il generale non eseguisse l’ordine ricevuto, chi avrebbe torto fra lui e me?”", "zh": "若我命令一位将军像蝴蝶般在花间飞舞，或撰写一部悲剧，或变成一只海鸟，而将军不遵从命令，那么错在谁？", "t": [100, 12962]}]}, {"id": "ch10p32", "audio": true, "sents": [{"it": "“Lei,” disse convinto il piccolo principe.", "zh": "“你说得对，”小王子坚定地说。", "t": [100, 2712]}]}, {"id": "ch10p33", "audio": true, "sents": [{"it": "“Esatto.", "zh": "正是如此。", "t": [100, 1150]}, {"it": "Bisogna pretendere da ciascuno quel che ciascuno può dare,” proseguì il re.", "zh": "每位臣民都应尽其所能，国王继续说道。", "t": [1150, 5500]}, {"it": "“L’autorità si fonda in primo luogo sulla ragione.", "zh": "权威首先建立在理性之上。", "t": [5500, 8525]}, {"it": "Se ordini al tuo popolo di andare a gettarsi in mare, quello farà la rivoluzione.", "zh": "若你命令你的百姓跳海，他们便会起义。", "t": [8525, 13475]}, {"it": "Ho il diritto di pretendere l’obbedienza perché i miei ordini sono ragionevoli.”", "zh": "我有权要求服从，因为我的命令合乎情理。", "t": [13475, 17562]}]}, {"id": "ch10p34", "audio": true, "sents": [{"it": "“Allora, il mio tramonto?” tornò alla carica il piccolo principe, che non rinunciava mai a una domanda dopo che l’aveva fatta.", "zh": "那么，我的日落呢？小王子再次追问，一旦提问便绝不放弃。", "t": [100, 7400]}]}, {"id": "ch10p35", "audio": true, "sents": [{"it": "“Lo avrai, il tuo tramonto.", "zh": "你将看到你的日落。", "t": [100, 2162]}, {"it": "Lo esigerò.", "zh": "我命令你。", "t": [2162, 3325]}, {"it": "Ma, forte della mia esperienza di governo, aspetterò che si presentino le condizioni favorevoli.”", "zh": "凭借我的治国经验，我将等待有利条件的出现。", "t": [3325, 9150]}]}, {"id": "ch10p36", "audio": true, "sents": [{"it": "“E quando sarà?” volle sapere il piccolo principe.", "zh": "“那会是什么时候？”小王子想知道。", "t": [100, 3224]}]}, {"id": "ch10p37", "audio": true, "sents": [{"it": "“Ehm!", "zh": "嗯！", "t": [100, 838]}, {"it": "Ehm!” rispose il re, che subito consultò un grosso calendario.", "zh": "“嗯！”国王回答，随即查阅了一本厚重的日历。", "t": [838, 5325]}, {"it": "“Ehm, ehm, sarà verso...", "zh": "嗯，嗯，大概在……", "t": [5325, 7688]}, {"it": "verso...", "zh": "他转过身去，背对着小王子。", "t": [7688, 8575]}, {"it": "sarà stasera, verso le sette e quaranta!", "zh": "今晚十时四十分左右！", "t": [8575, 11600]}, {"it": "E vedrai come mi obbedirà!”", "zh": "你将看到他们如何服从我！", "t": [11600, 13037]}]}, {"id": "ch10p38", "audio": true, "sents": [{"it": "Il piccolo principe sbadigliò.", "zh": "小王子打了个哈欠。", "t": [100, 2188]}, {"it": "Si rammaricava per il mancato tramonto.", "zh": "他遗憾地错过了日落。", "t": [2188, 4650]}, {"it": "E cominciava ad annoiarsi un po’:", "zh": "他开始感到有些厌烦了。", "t": [4650, 6450]}]}, {"id": "ch10p39", "audio": true, "sents": [{"it": "“Non ho più niente da fare qui,” disse al re.", "zh": "“在这儿我已无事可做，”他对国王说。", "t": [100, 2700]}, {"it": "“Me ne vado!”", "zh": "我走了！", "t": [2700, 3488]}]}, {"id": "ch10p40", "audio": true, "sents": [{"it": "“Non te ne andare,” rispose il re, talmente fiero di avere un suddito.", "zh": "“别走，”国王回答，自豪地拥有一个臣民。", "t": [100, 4188]}, {"it": "“Non te ne andare, ti faccio ministro!”", "zh": "别走，我封你为部长！", "t": [4188, 6362]}]}, {"id": "ch10p41", "audio": true, "sents": [{"it": "“Ministro di cosa?”", "zh": "司法部长？", "t": [100, 1187]}]}, {"id": "ch10p42", "audio": true, "sents": [{"it": "“Di...", "zh": "“你为何而来？”", "t": [100, 850]}, {"it": "della Giustizia!”", "zh": "司法部！", "t": [850, 1850]}]}, {"id": "ch10p43", "audio": true, "sents": [{"it": "“Ma non c’è nessuno da giudicare!”", "zh": "无人可审。", "t": [100, 1850]}]}, {"id": "ch10p44", "audio": true, "sents": [{"it": "“Non lo sappiamo,” gli disse il re.", "zh": "我们不知道。", "t": [100, 2175]}, {"it": "“Non ho ancora visitato tutto il mio regno.", "zh": "我尚未游览过我的整个王国。", "t": [2175, 4538]}, {"it": "Sono molto vecchio, non ho spazio per una carrozza e camminare mi stanca.”", "zh": "我年事已高，没有地方停放马车，走路又累得要命。", "t": [4538, 8650]}]}, {"id": "ch10p45", "audio": true, "sents": [{"it": "“Oh!", "zh": "啊！", "t": [100, 812]}, {"it": "Ma io ho già visto,” disse il piccolo principe che si sporse a gettare ancora un’occhiata verso l’altro lato del pianeta.", "zh": "“我已经看过了，”小王子说着，又朝星球的另一端瞥了一眼。", "t": [812, 7450]}, {"it": "“Non c’è nessuno neanche di là...”", "zh": "那边也没有人……", "t": [7450, 9113]}]}, {"id": "ch10p46", "audio": true, "sents": [{"it": "“Allora giudicherai te stesso,” gli rispose il re.", "zh": "那么，你将审判自己。", "t": [100, 3000]}, {"it": "“È la cosa più difficile.", "zh": "这是最难的事。", "t": [3000, 4600]}, {"it": "È molto più difficile giudicare se stessi che giudicare gli altri.", "zh": "评判自己远比评判他人困难。", "t": [4600, 8300]}, {"it": "Se riesci a giudicarti bene, significa che sei un vero saggio.”", "zh": "若你能公正地评判自己，便算得上真正的智者。", "t": [8300, 12050]}]}, {"id": "ch10p47", "audio": true, "sents": [{"it": "“Io,” disse il piccolo principe, “posso giudicare me stesso ovunque.", "zh": "我，小王子说，我可以在任何地方审判自己。", "t": [100, 4338]}, {"it": "Non occorre che viva qui.”", "zh": "这里无需我居住。", "t": [4338, 5913]}]}, {"id": "ch10p48", "audio": true, "sents": [{"it": "“Ehm, ehm,” fece il re, “credo proprio che da qualche parte qui sul mio pianeta ci sia un vecchio topo.", "zh": "嗯，嗯，国王说，我相信在这颗星球上某个角落里，有一只老耗子。", "t": [100, 6138]}, {"it": "Lo sento la notte.", "zh": "夜深人静，我听到了。", "t": [6138, 7612]}, {"it": "Potrai giudicare quel vecchio topo.", "zh": "你将审判那只老耗子。", "t": [7612, 9762]}, {"it": "Ogni tanto lo condannerai a morte.", "zh": "时而将他判处死刑。", "t": [9762, 12088]}, {"it": "Così la sua vita dipenderà dalla tua giustizia.", "zh": "他的生命将取决于你的公正。", "t": [12088, 14925]}, {"it": "E poi lo grazierai, così potremo tenercelo.", "zh": "然后你将赦免它，这样我们就能保留它了。", "t": [14925, 18000]}, {"it": "Visto che ce n’è uno solo.”", "zh": "既然只有一个。", "t": [18000, 19450]}]}, {"id": "ch10p49", "audio": true, "sents": [{"it": "“A me non piace condannare a morte,” rispose il piccolo principe, “e credo proprio che me ne andrò.”", "zh": "我不喜欢判人死刑，我觉得我该走了。", "t": [100, 5276]}]}, {"id": "ch10p50", "audio": true, "sents": [{"it": "“No,” disse il re.", "zh": "“不，”国王说。", "t": [100, 1250]}]}, {"id": "ch10p51", "audio": true, "sents": [{"it": "Ma, finiti i preparativi, il piccolo principe non volle dare un dispiacere al vecchio monarca:", "zh": "然而，准备就绪后，小王子不愿给这位老国王添麻烦：", "t": [100, 5862]}]}, {"id": "ch10p52", "audio": true, "sents": [{"it": "“Se Sua Maestà volesse essere prontamente obbedita, potrebbe darmi un ordine ragionevole.", "zh": "若陛下希望令出即行，可以给我一个合理的命令。", "t": [100, 5262]}, {"it": "Per esempio, potrebbe ordinarmi di partire fra un minuto.", "zh": "或许，他可以命令我立刻离开。", "t": [5262, 8775]}, {"it": "Mi sembra che ci siano le condizioni favorevoli...”", "zh": "似乎条件已具备……", "t": [8775, 11525]}]}, {"id": "ch10p53", "audio": true, "sents": [{"it": "Poiché il re non rispose nulla, il piccolo principe dapprima esitò, poi con un sospiro se ne andò.", "zh": "国王无言以对，小王子犹豫片刻，然后叹了口气，转身离去。", "t": [100, 6162]}]}, {"id": "ch10p54", "audio": true, "sents": [{"it": "“Ti nomino mio ambasciatore,” si affrettò allora a gridare il re.", "zh": "“我封你为大使，”国王急忙喊道。", "t": [100, 3375]}]}, {"id": "ch10p55", "audio": true, "sents": [{"it": "Aveva un atteggiamento di grande autorità.", "zh": "威严地端坐。", "t": [100, 2362]}]}, {"id": "ch10p56", "audio": true, "sents": [{"it": "“Gli adulti sono proprio curiosi,” disse tra sé il piccolo principe durante il viaggio.", "zh": "大人真是好奇啊，小王子在旅途中自言自语。", "t": [100, 4738]}]}]}, {"id": "ch11", "title_it": "XI", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"it": "Il secondo pianeta era abitato da un vanitoso: “Ah!", "zh": "第二颗星球住着一个爱慕虚荣的人：“啊！”", "t": [100, 3862]}, {"it": "Ecco la visita di un ammiratore!” esclamò da lontano il vanitoso appena scorse il piccolo principe.", "zh": "啊！崇拜我的人访问我啦！", "t": [3862, 9862]}]}, {"id": "ch11p01", "audio": true, "sents": [{"it": "Per i vanitosi, infatti, gli altri uomini sono degli ammiratori.", "zh": "虚荣者眼中，他人皆是崇拜者。", "t": [100, 4450]}]}, {"id": "ch11p02", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe, “ha proprio uno strano cappello!”", "zh": "“你好，”小王子说，“你这顶帽子真奇怪！”", "t": [100, 4375]}]}, {"id": "ch11p03", "audio": true, "sents": [{"it": "“È per salutare,” gli rispose il vanitoso.", "zh": "“这是为了敬礼，”爱慕虚荣的人回答道。", "t": [100, 2662]}, {"it": "“È per salutare quando mi acclamano.", "zh": "这是为了在有人欢呼时敬礼。", "t": [2662, 4738]}, {"it": "Disgraziatamente, da qui non passa mai nessuno.”", "zh": "遗憾的是，这里从来没有人经过。", "t": [4738, 7750]}]}, {"id": "ch11p04", "audio": true, "sents": [{"it": "“Ah sì?” disse il piccolo principe, che non capiva.", "zh": "“啊？小王子说，他不懂。”", "t": [100, 3563]}]}, {"id": "ch11p05", "audio": true, "sents": [{"it": "“Batti le mani una contro l’altra,” consigliò quindi il vanitoso.", "zh": "请你互相拍手。", "t": [100, 3500]}]}, {"id": "ch11p06", "audio": true, "sents": [{"it": "Il piccolo principe batté le mani una contro l’altra.", "zh": "小王子拍着手掌。", "t": [100, 3488]}, {"it": "Il vanitoso fece un gran saluto sollevando il cappello.", "zh": "他举起帽子，行了一个大礼。", "t": [3488, 6800]}]}, {"id": "ch11p07", "audio": true, "sents": [{"it": "“È più divertente della visita al re,” si disse il piccolo principe.", "zh": "比拜访国王有趣多了。", "t": [100, 3825]}, {"it": "E ricominciò a battere le mani.", "zh": "他再次拍起手来。", "t": [3825, 5850]}, {"it": "Il vanitoso ricominciò a salutare sollevando il cappello.", "zh": "虚荣者又举起帽子，开始打招呼。", "t": [5850, 9137]}]}, {"id": "ch11p08", "audio": true, "sents": [{"it": "Dopo cinque minuti il piccolo principe si stancò di quel giochetto sempre uguale:", "zh": "五分钟后，小王子厌倦了这单调的游戏。", "t": [100, 4637]}]}, {"id": "ch11p09", "audio": true, "sents": [{"it": "“E per fare cadere il cappello cosa bisogna fare?” domandò.", "zh": "“要怎样做才能让这顶帽子放下？”他问道。", "t": [100, 3413]}]}, {"id": "ch11p10", "audio": true, "sents": [{"it": "Ma il vanitoso non lo sentì.", "zh": "虚荣者并未察觉。", "t": [100, 2012]}, {"it": "I vanitosi sentono solo le lodi.", "zh": "虚荣者只听见赞美之词。", "t": [2012, 4113]}]}, {"id": "ch11p11", "audio": true, "sents": [{"it": "“Tu mi ammiri davvero molto?” domandò al piccolo principe.", "zh": "你真的非常崇拜我吗？", "t": [100, 3350]}]}, {"id": "ch11p12", "audio": true, "sents": [{"it": "“Che cosa significa ‘ammirare’?”", "zh": "“‘崇拜’是什么意思？”", "t": [100, 1700]}]}, {"id": "ch11p13", "audio": true, "sents": [{"it": "“‘Ammirare’ significa riconoscere che sono l’uomo più bello, meglio vestito, più ricco e più intelligente del pianeta.”", "zh": "“‘崇拜’意味着承认我是这个星球上最英俊、衣着最讲究、最富有、最聪明的人。”", "t": [100, 6974]}]}, {"id": "ch11p14", "audio": true, "sents": [{"it": "“Ma sei solo, sul tuo pianeta!”", "zh": "你孤身一人，在你的星球上！", "t": [100, 2124]}]}, {"id": "ch11p15", "audio": true, "sents": [{"it": "“Fammi questo favore.", "zh": "请帮个忙。", "t": [100, 1538]}, {"it": "Ammirami lo stesso!”", "zh": "依然崇拜我吧！", "t": [1538, 2775]}]}, {"id": "ch11p16", "audio": true, "sents": [{"it": "“Ti ammiro,” disse il piccolo principe alzando un po’ le spalle, “ma che cosa te ne viene?”", "zh": "“我崇拜你，”小王子耸耸肩，“这对你来说又算得了什么呢？”", "t": [100, 4888]}]}, {"id": "ch11p17", "audio": true, "sents": [{"it": "E il piccolo principe se ne andò.", "zh": "小王子便离去了。", "t": [100, 1900]}]}, {"id": "ch11p18", "audio": true, "sents": [{"it": "“Gli adulti sono proprio strani,” disse semplicemente tra sé durante il viaggio.", "zh": "大人们真是奇怪。", "t": [100, 4400]}]}]}, {"id": "ch12", "title_it": "XII", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": [{"it": "Il pianeta seguente era abitato da un bevitore.", "zh": "下一颗星球住着个酒徒。", "t": [100, 2887]}]}, {"id": "ch12p01", "audio": true, "sents": [{"it": "La visita fu molto breve, ma destò nel piccolo principe una gran malinconia:", "zh": "这次访问虽短，却让小王子心中泛起深深的忧郁。", "t": [100, 4788]}]}, {"id": "ch12p02", "audio": true, "sents": [{"it": "“Che fai qui?” disse al bevitore, che trovò seduto davanti a una sfilza di bottiglie, metà delle quali vuote e metà piene.", "zh": "“你在干什么？”他对坐在一瓶瓶酒前的酒徒说。", "t": [100, 7438]}]}, {"id": "ch12p03", "audio": true, "sents": [{"it": "“Bevo,” rispose il bevitore con aria cupa.", "zh": "“我在喝酒，”酒徒带着忧郁的语气回答。", "t": [100, 2375]}]}, {"id": "ch12p04", "audio": true, "sents": [{"it": "“Perché bevi?” gli domandò il piccolo principe.", "zh": "“你为何饮酒？”小王子问道。", "t": [100, 3050]}]}, {"id": "ch12p05", "audio": true, "sents": [{"it": "“Per dimenticare,” rispose il bevitore.", "zh": "为了忘却，酒徒答道。", "t": [100, 2237]}]}, {"id": "ch12p06", "audio": true, "sents": [{"it": "“Per dimenticare cosa?” volle sapere il piccolo principe, che già lo compativa.", "zh": "“为了忘却什么？”小王子想了解，心中已对他生出了同情。", "t": [100, 4975]}]}, {"id": "ch12p07", "audio": true, "sents": [{"it": "“Per dimenticare che mi vergogno,” ammise il bevitore abbassando la testa.", "zh": "为了忘却我羞愧，酒徒低下头，老实承认。", "t": [100, 4100]}]}, {"id": "ch12p08", "audio": true, "sents": [{"it": "“Ti vergogni di cosa?” lo interrogò il piccolo principe che desiderava aiutarlo.", "zh": "小王子问他，为了什么而感到羞愧。", "t": [100, 4938]}]}, {"id": "ch12p09", "audio": true, "sents": [{"it": "“Mi vergogno di bere!” concluse il bevitore che si chiuse definitivamente nel silenzio.", "zh": "我为喝酒感到羞愧！酒徒说完，终于彻底陷入了沉默。", "t": [100, 5112]}]}, {"id": "ch12p10", "audio": true, "sents": [{"it": "E il piccolo principe se ne andò, perplesso.", "zh": "小王子困惑地走了。", "t": [100, 2750]}]}, {"id": "ch12p11", "audio": true, "sents": [{"it": "“Gli adulti sono proprio molto strani,” diceva tra sé durante il viaggio.", "zh": "大人真是古怪，他边走边自言自语。", "t": [100, 3913]}]}]}, {"id": "ch13", "title_it": "XIII", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"it": "Il quarto pianeta era quello dell’uomo d’affari.", "zh": "第四颗星球是商人的星球。", "t": [100, 2912]}, {"it": "Era un uomo talmente occupato che non alzò neppure la testa all’arrivo del piccolo principe.", "zh": "他如此忙碌，以至于小王子到来时，他连头都没抬一下。", "t": [2912, 8074]}]}, {"id": "ch13p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse quest’ultimo.", "zh": "“你好，”最后一位说。", "t": [100, 2200]}, {"it": "“Ha la sigaretta spenta.”", "zh": "烟已经抽完了。", "t": [2200, 3537]}]}, {"id": "ch13p02", "audio": true, "sents": [{"it": "“Tre più due cinque.", "zh": "三加二等于五。", "t": [100, 1488]}, {"it": "Cinque più sette dodici.", "zh": "五加七等于十二。", "t": [1488, 3750]}, {"it": "Dodici più tre quindici.", "zh": "十二加三等于十五。", "t": [3750, 5975]}, {"it": "Buongiorno.", "zh": "你好。", "t": [5975, 7025]}, {"it": "Quindici più sette ventidue.", "zh": "十五加七等于二十二。", "t": [7025, 8988]}, {"it": "Ventidue più sei ventotto.", "zh": "二十二加二十八。", "t": [8988, 10888]}, {"it": "Non ho tempo di riaccenderla.", "zh": "没时间再点烟了。", "t": [10888, 12838]}, {"it": "Ventisei più cinque trentuno.", "zh": "二十六加五等于三十一。", "t": [12838, 14950]}, {"it": "Uff!", "zh": "唉！", "t": [14950, 15712]}, {"it": "Quindi fanno cinquecentouno milioni seicento ventiduemila settecentotrentuno.”", "zh": "五亿零一百六十二万二千七百三十一。", "t": [15712, 20626]}]}, {"id": "ch13p03", "audio": true, "sents": [{"it": "“Cinquecento milioni di cosa?”", "zh": "五亿零一百六十二万二千七百三十一个什么？", "t": [100, 1737]}]}, {"id": "ch13p04", "audio": true, "sents": [{"it": "“Eh?", "zh": "唉？", "t": [100, 712]}, {"it": "Sei ancora qui?", "zh": "你还在这儿？", "t": [712, 1988]}, {"it": "Cinquecentouno milioni di...", "zh": "五亿零一百一十一万...", "t": [1988, 3950]}, {"it": "non mi ricordo più...", "zh": "我已记不清了。", "t": [3950, 5350]}, {"it": "ho tanto di quel lavoro!", "zh": "如此忙碌，无暇他顾。", "t": [5350, 6925]}, {"it": "Sono una persona seria, io, mica perdo tempo con le stupidaggini!", "zh": "我是个正经人，不跟傻事浪费时间。", "t": [6925, 11300]}, {"it": "Due più cinque sette...”", "zh": "二加五七……", "t": [11300, 12825]}]}, {"id": "ch13p05", "audio": true, "sents": [{"it": "“Cinquecentouno milioni di cosa?” ripeté il piccolo principe che in vita sua non aveva mai rinunciato a una domanda dopo che l’aveva fatta.", "zh": "“五亿零一百一十一万……这是什么？”小王子重复道，他一生从未在提出问题后就此放弃。", "t": [100, 7813]}]}, {"id": "ch13p06", "audio": true, "sents": [{"it": "L’uomo d’affari alzò la testa:", "zh": "商人抬起头：", "t": [100, 1987]}]}, {"id": "ch13p07", "audio": true, "sents": [{"it": "“Abito in questo pianeta da cinquantaquattro anni e sono stato disturbato solo tre volte.", "zh": "在这颗星球上住了五十四年，只被打扰过三次。", "t": [100, 5500]}, {"it": "La prima volta è stata ventidue anni fa, da un maggiolino caduto chissà da dove.", "zh": "第一次，是在二十二年前，一个小孩从不知名的地方掉落。", "t": [5500, 10412]}, {"it": "Faceva un rumore spaventoso e mi sono scappati quattro errori in un’addizione.", "zh": "那声音吓人一跳，我加减法里出了四个错。", "t": [10412, 15225]}, {"it": "La seconda volta è stata undici anni fa, da un attacco di reumatismi.", "zh": "第二次，是在十一年前，因患风湿病。", "t": [15225, 19650]}, {"it": "Non faccio abbastanza moto.", "zh": "我运动得还不够。", "t": [19650, 21438]}, {"it": "Non ho tempo di andare a spasso.", "zh": "我没有时间闲逛。", "t": [21438, 23388]}, {"it": "Sono una persona seria, io.", "zh": "我是个正经人。", "t": [23388, 25550]}, {"it": "La terza volta, eccola!", "zh": "第三次，它又出现了！", "t": [25550, 27688]}, {"it": "Dicevo quindi cinquecentouno milioni...”", "zh": "我说：“五亿零一百一十一万……”", "t": [27688, 30176]}]}, {"id": "ch13p08", "audio": true, "sents": [{"it": "“Milioni di cosa?”", "zh": "五亿零一百一十一万个什么？", "t": [100, 1125]}]}, {"id": "ch13p09", "audio": true, "sents": [{"it": "L’uomo d’affari capì che non aveva speranza di essere lasciato in pace:", "zh": "商人意识到自己别想再安宁了。", "t": [100, 3724]}]}, {"id": "ch13p10", "audio": true, "sents": [{"it": "“Milioni di quelle cosettine che ogni tanto si vedono in cielo.”", "zh": "满天这些小东西，偶尔可见。", "t": [100, 3400]}]}, {"id": "ch13p11", "audio": true, "sents": [{"it": "“Mosche?”", "zh": "苍蝇吗？", "t": [100, 738]}]}, {"id": "ch13p12", "audio": true, "sents": [{"it": "“Ma no, quelle cosettine gialle.”", "zh": "那些金色的小东西。", "t": [100, 2237]}]}, {"id": "ch13p13", "audio": true, "sents": [{"it": "“Api?”", "zh": "“是蜜蜂吗？”", "t": [100, 600]}]}, {"id": "ch13p14", "audio": true, "sents": [{"it": "“Ma no, quelle cosettine dorate che fanno sognare i perdigiorno.", "zh": "那些金色的小东西，能让迷失的人梦想成真。", "t": [100, 4138]}, {"it": "Io però sono una persona seria!", "zh": "然而，我是一个严肃的人！", "t": [4138, 6338]}, {"it": "Mica ho tempo di perdermi nei sogni.”", "zh": "我没有时间沉溺于梦想。", "t": [6338, 8513]}]}, {"id": "ch13p15", "audio": true, "sents": [{"it": "“Ah, le stelle?”", "zh": "啊，星星？", "t": [100, 1174]}]}, {"id": "ch13p16", "audio": true, "sents": [{"it": "“Esatto.", "zh": "正是如此。", "t": [100, 1150]}, {"it": "Le stelle.”", "zh": "繁星点点。", "t": [1150, 1976]}]}, {"id": "ch13p17", "audio": true, "sents": [{"it": "“E cosa te ne fai di cinquecento milioni di stelle?”", "zh": "你拿五亿颗星星做什么呢？", "t": [100, 2825]}]}, {"id": "ch13p18", "audio": true, "sents": [{"it": "“Cinquecentouno milioni seicentoventiduemila settecentotrentuno.", "zh": "五亿零一百六十二万二千七百三十一", "t": [100, 4662]}, {"it": "Sono una persona seria, io, una persona precisa!”", "zh": "我是个严肃的人，一个一丝不苟的人。", "t": [4662, 8300]}]}, {"id": "ch13p19", "audio": true, "sents": [{"it": "“E cosa te ne fai di tutte quelle stelle?”", "zh": "你拿这些星星有何用？", "t": [100, 2200]}]}, {"id": "ch13p20", "audio": true, "sents": [{"it": "“Cosa me ne faccio?”", "zh": "我拿它有何用？", "t": [100, 1037]}]}, {"id": "ch13p21", "audio": true, "sents": [{"it": "“Sì.”", "zh": "是的。", "t": [100, 562]}]}, {"id": "ch13p22", "audio": true, "sents": [{"it": "“Niente.", "zh": "没什么。", "t": [100, 1025]}, {"it": "Le possiedo.”", "zh": "我拥有。", "t": [1025, 1912]}]}, {"id": "ch13p23", "audio": true, "sents": [{"it": "“Possiedi le stelle?”", "zh": "你拥有星星吗？", "t": [100, 1224]}]}, {"id": "ch13p24", "audio": true, "sents": [{"it": "“Sì.”", "zh": "是的。", "t": [100, 562]}]}, {"id": "ch13p25", "audio": true, "sents": [{"it": "“Ma io ho già visto un re che...”", "zh": "我见过一个国王，他……", "t": [100, 1676]}]}, {"id": "ch13p26", "audio": true, "sents": [{"it": "“I re non possiedono niente.", "zh": "他们一无所有。", "t": [100, 2012]}, {"it": "Loro ‘regnano’.", "zh": "他们统治着。", "t": [2012, 3138]}, {"it": "È ben diverso.”", "zh": "大不相同。", "t": [3138, 4062]}]}, {"id": "ch13p27", "audio": true, "sents": [{"it": "“E a cosa ti serve possedere le stelle?”", "zh": "你拥有星星有何用？", "t": [100, 2200]}]}, {"id": "ch13p28", "audio": true, "sents": [{"it": "“Mi serve a essere ricco.”", "zh": "我需要变得富有。", "t": [100, 1387]}]}, {"id": "ch13p29", "audio": true, "sents": [{"it": "“E a cosa ti serve essere ricco?”", "zh": "你变得富有有何用？", "t": [100, 1763]}]}, {"id": "ch13p30", "audio": true, "sents": [{"it": "“A comprare altre stelle, se qualcuno le trova.”", "zh": "若有人发现新星星，便去购买。", "t": [100, 2763]}]}, {"id": "ch13p31", "audio": true, "sents": [{"it": "“Questo qui,” disse tra sé il piccolo principe, “ragiona un po’ come il mio ubriacone.”", "zh": "“这东西，”小王子自言自语道，“像我的酒鬼一样思考。”", "t": [100, 4787]}]}, {"id": "ch13p32", "audio": true, "sents": [{"it": "Tuttavia fece ancora qualche domanda:", "zh": "然而，他还是问了几句。", "t": [100, 2138]}]}, {"id": "ch13p33", "audio": true, "sents": [{"it": "“Come si fa a possedere le stelle?”", "zh": "如何拥有星星？", "t": [100, 1875]}]}, {"id": "ch13p34", "audio": true, "sents": [{"it": "“Di chi sono?” ribatté, stizzito, l’uomo d’affari.", "zh": "商人怒斥道：“这关你什么事？”", "t": [100, 4000]}]}, {"id": "ch13p35", "audio": true, "sents": [{"it": "“Non lo so.", "zh": "我不知道。", "t": [100, 1012]}, {"it": "Di nessuno.”", "zh": "无人知晓。", "t": [1012, 1925]}]}, {"id": "ch13p36", "audio": true, "sents": [{"it": "“Allora sono mie, perché ho avuto per primo l’idea.”", "zh": "那么，它们就归我所有，因为我第一个想到了。", "t": [100, 2950]}]}, {"id": "ch13p37", "audio": true, "sents": [{"it": "“È sufficiente?”", "zh": "这够了吗？", "t": [100, 1125]}]}, {"id": "ch13p38", "audio": true, "sents": [{"it": "“Certo.", "zh": "当然。", "t": [100, 1025]}, {"it": "Quando trovi un diamante che non è di nessuno, allora è tuo.", "zh": "你发现一颗无主的钻石，它便属于你。", "t": [1025, 4962]}, {"it": "Quando sei il primo ad avere un’idea, la fai brevettare ed è tua.", "zh": "当你是第一个想到主意的人，你就可以申请专利，那主意就归你了。", "t": [4962, 9075]}, {"it": "E io possiedo le stelle, perché a nessuno prima di me è venuto in mente di possederle.”", "zh": "我拥有星星，因为在我之前，无人想过拥有它们。", "t": [9075, 13774]}]}, {"id": "ch13p39", "audio": true, "sents": [{"it": "“È vero,” disse il piccolo principe.", "zh": "“没错，”小王子说。", "t": [100, 2275]}, {"it": "“E che cosa te ne fai?”", "zh": "你拿它有何用？", "t": [2275, 3476]}]}, {"id": "ch13p40", "audio": true, "sents": [{"it": "“Le gestisco.", "zh": "我管理着。", "t": [100, 1350]}, {"it": "Le conto e le riconto,” disse l’uomo d’affari.", "zh": "“账目与账目，”商人说。", "t": [1350, 4188]}, {"it": "“È difficile.", "zh": "这很困难。", "t": [4188, 5275]}, {"it": "Ma io sono un uomo serio!”", "zh": "我是个严肃的人！", "t": [5275, 6862]}]}, {"id": "ch13p41", "audio": true, "sents": [{"it": "Il piccolo principe non era ancora soddisfatto.", "zh": "小王子仍未满足。", "t": [100, 2887]}]}, {"id": "ch13p42", "audio": true, "sents": [{"it": "“Se possiedo un fazzoletto posso mettermelo al collo e portarlo con me.", "zh": "我若拥有一条围巾，便可以围在脖子上带走。", "t": [100, 4250]}, {"it": "Se possiedo un fiore posso coglier­lo e portarlo con me.", "zh": "若我拥有这朵花，便可摘下它，随身携带。", "t": [4250, 7612]}, {"it": "Ma tu non puoi cogliere le stelle!”", "zh": "你无法捉摸星星。", "t": [7612, 9526]}]}, {"id": "ch13p43", "audio": true, "sents": [{"it": "“No, ma posso metterle in banca.”", "zh": "不，但我可以把它们存进银行。", "t": [100, 2237]}]}, {"id": "ch13p44", "audio": true, "sents": [{"it": "“Che cosa vuol dire?”", "zh": "这究竟是什么意思？", "t": [100, 1162]}]}, {"id": "ch13p45", "audio": true, "sents": [{"it": "“Vuol dire che scrivo su un foglio il numero delle mie stelle.", "zh": "我在一张小纸条上写下我的星星数目。", "t": [100, 3562]}, {"it": "E poi chiudo a chiave il foglio in un cassetto.”", "zh": "我将纸条锁进抽屉里。", "t": [3562, 6050]}]}, {"id": "ch13p46", "audio": true, "sents": [{"it": "“Ed è sufficiente?”", "zh": "这还不够吗？", "t": [100, 1163]}]}, {"id": "ch13p47", "audio": true, "sents": [{"it": "“Certo!”", "zh": "当然！", "t": [100, 762]}]}, {"id": "ch13p48", "audio": true, "sents": [{"it": "“È divertente,” pensò il piccolo principe.", "zh": "这挺有趣的，小王子心想。", "t": [100, 2650]}, {"it": "“È molto poetico.", "zh": "这颇为诗意。", "t": [2650, 4038]}, {"it": "Ma non è granché serio.”", "zh": "这并不怎么严肃。", "t": [4038, 5425]}]}, {"id": "ch13p49", "audio": true, "sents": [{"it": "Il piccolo principe aveva idee molto diverse dagli adulti riguardo alle cose serie.", "zh": "小王子对所谓“严肃”之事的看法与大人迥异。", "t": [100, 4713]}]}, {"id": "ch13p50", "audio": true, "sents": [{"it": "“Io,” disse ancora, “possiedo una rosa che innaffio tutti i giorni.", "zh": "“我，”他又说，“拥有一朵玫瑰，我每天都给它浇水。”", "t": [100, 4338]}, {"it": "Possiedo tre vulcani che pulisco tutte le settimane.", "zh": "我每周都清理三座火山。", "t": [4338, 7762]}, {"it": "Perché pulisco anche quello spento.", "zh": "我连那熄灭的也清理。", "t": [7762, 10012]}, {"it": "Non si sa mai.", "zh": "无人能知。", "t": [10012, 11175]}, {"it": "Il fatto che io li possieda è utile ai miei vulcani ed è utile alla mia rosa.", "zh": "拥有它们对我火山有益，对玫瑰也有益。", "t": [11175, 15950]}, {"it": "Invece tu non sei utile alle stelle...”", "zh": "你对于星星并无用处……", "t": [15950, 18037]}]}, {"id": "ch13p51", "audio": true, "sents": [{"it": "L’uomo d’affari aprì la bocca ma non trovò nulla da rispondere, e il piccolo principe se ne andò.", "zh": "商人张口结舌，无言以对，小王子便离去了。", "t": [100, 5387]}]}, {"id": "ch13p52", "audio": true, "sents": [{"it": "“Gli adulti sono veramente stravaganti,” diceva semplicemente tra sé durante il viaggio.", "zh": "大人真是古怪。", "t": [100, 4750]}]}]}, {"id": "ch14", "title_it": "XIV", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"it": "Il quinto pianeta era davvero curioso.", "zh": "第五颗星球真是奇妙。", "t": [100, 2525]}, {"it": "Era il più piccolo di tutti.", "zh": "那是所有星球中最小的一颗。", "t": [2525, 4412]}, {"it": "C’era spazio solo per un lampione e un lampionaio.", "zh": "那里仅能容纳一盏路灯和一个点灯人。", "t": [4412, 7625]}, {"it": "Il piccolo principe non riusciva a spiegarsi a cosa potessero servire, in un punto del cielo, su un pia­neta senza case né popolazione, un lampione e un lampionaio.", "zh": "小王子无法理解，在这片无屋无人的天际，那盏路灯和点灯人究竟有何用。", "t": [7625, 17800]}, {"it": "Tuttavia disse tra sé:", "zh": "然而他自言自语道：", "t": [17800, 19088]}]}, {"id": "ch14p01", "audio": true, "sents": [{"it": "“Forse quest’uomo è assurdo.", "zh": "或许这个人有些疯狂。", "t": [100, 2188]}, {"it": "Però è meno assurdo del re, del vanitoso, dell’uomo d’affari e del bevitore.", "zh": "然而，他并不像国王、虚荣的人、商人、酒鬼那般荒谬。", "t": [2188, 7412]}, {"it": "Almeno il suo lavoro ha un senso.", "zh": "至少他的工作还有意义。", "t": [7412, 9538]}, {"it": "Quando accende il lampione, è come se facesse nascere una stella in più, o un fiore.", "zh": "点亮路灯，仿佛又诞生了一颗星星，或一朵鲜花。", "t": [9538, 14925]}, {"it": "Quando spegne il lampione, addormenta il fiore o la stella.", "zh": "熄灯之际，让花朵或星辰沉睡。", "t": [14925, 18675]}, {"it": "È una bellissima occupazione.", "zh": "这是一份美好的差事。", "t": [18675, 20712]}, {"it": "Ed è davvero utile perché è bella!”", "zh": "这真是有益，因为真美啊！", "t": [20712, 22513]}]}, {"id": "ch14p02", "audio": true, "sents": [{"it": "Quando giunse sul pianeta, salutò rispettosamente il lampionaio:", "zh": "他抵达那颗星球时，恭敬地向点灯人行礼： “你好。”", "t": [100, 4137]}]}, {"id": "ch14p03", "audio": true, "sents": [{"it": "“Buongiorno.", "zh": "你好。", "t": [100, 1150]}, {"it": "Perché hai spento il tuo lampione?”", "zh": "你为何熄灭了你的路灯？", "t": [1150, 2850]}]}, {"id": "ch14p04", "audio": true, "sents": [{"it": "“Sono le direttive,” rispose il lampionaio.", "zh": "“这是规定。”点灯人答道。", "t": [100, 2738]}, {"it": "“Buongiorno.”", "zh": "你好。", "t": [2738, 3526]}]}, {"id": "ch14p05", "audio": true, "sents": [{"it": "“Quali direttive?”", "zh": "“遵循哪些指令？”", "t": [100, 1200]}]}, {"id": "ch14p06", "audio": true, "sents": [{"it": "“Di spegnere il lampione.", "zh": "熄灭路灯。", "t": [100, 1800]}, {"it": "Buonasera.”", "zh": "晚安。", "t": [1800, 2588]}]}, {"id": "ch14p07", "audio": true, "sents": [{"it": "E lo riaccese.", "zh": "他又点亮了灯火。", "t": [100, 1038]}]}, {"id": "ch14p08", "audio": true, "sents": [{"it": "“Ma perché l’hai riacceso?”", "zh": "你为何又点上了？", "t": [100, 1474]}]}, {"id": "ch14p09", "audio": true, "sents": [{"it": "“Sono le direttive,” rispose il lampionaio.", "zh": "“这是规定，”点灯人答道。", "t": [100, 2476]}]}, {"id": "ch14p10", "audio": true, "sents": [{"it": "“Non capisco,” disse il piccolo principe.", "zh": "我不明白，小王子说。", "t": [100, 2375]}]}, {"id": "ch14p11", "audio": true, "sents": [{"it": "“Non c’è niente da capire,” disse il lampionaio.", "zh": "“这没什么好理解的，”点灯人说。", "t": [100, 2912]}, {"it": "“Le direttive sono queste.", "zh": "这些规定就是这样。", "t": [2912, 4738]}, {"it": "Buongiorno.”", "zh": "你好。", "t": [4738, 5526]}]}, {"id": "ch14p12", "audio": true, "sents": [{"it": "E spense il lampione.", "zh": "熄灭了灯火。", "t": [100, 1450]}]}, {"id": "ch14p13", "audio": true, "sents": [{"it": "Poi si asciugò la fronte con un fazzoletto a quadretti bianco e rosso.", "zh": "然后，他用红白格手帕擦拭额头。", "t": [100, 4074]}]}, {"id": "ch14p14", "audio": true, "sents": [{"it": "“Il mio è proprio un mestiere orribile.", "zh": "这真是一份讨厌的工作。", "t": [100, 2412]}, {"it": "Una volta era ancora fattibile.", "zh": "曾经尚可应对。", "t": [2412, 4500]}, {"it": "Spegnevo al mattino e accendevo alla sera.", "zh": "晨熄夜点。", "t": [4500, 7100]}, {"it": "Avevo il resto della giornata per riposarmi, e il resto della notte per dormire...”", "zh": "我有余下的白天来休息，余下的夜晚来睡眠……", "t": [7100, 11750]}]}, {"id": "ch14p15", "audio": true, "sents": [{"it": "“E da allora sono cambiate le direttive?”", "zh": "自那以后，规定改了？", "t": [100, 2237]}]}, {"id": "ch14p16", "audio": true, "sents": [{"it": "“Le direttive non sono cambiate,” disse il lampionaio.", "zh": "规定并未更改，点灯人说道。", "t": [100, 3562]}, {"it": "“È proprio questo il dramma!", "zh": "这正是悲剧所在！", "t": [3562, 5275]}, {"it": "Con il passare degli anni il pianeta ha cominciato a ruotare sempre più in fretta, ma le direttive non sono cambiate!”", "zh": "随着岁月流逝，这颗星球开始越转越快，但指令却未曾改变。", "t": [5275, 11812]}]}, {"id": "ch14p17", "audio": true, "sents": [{"it": "“E allora?” disse il piccolo principe.", "zh": "那么，小王子说。", "t": [100, 2550]}]}, {"id": "ch14p18", "audio": true, "sents": [{"it": "“Allora adesso che fa un giro al minuto non ho più un istante di riposo.", "zh": "现在它一分钟转一次，我连一秒钟的休息时间都没有。", "t": [100, 4612]}, {"it": "Accendo e spengo una volta al minuto!”", "zh": "每分钟点亮、熄灭一次灯火！", "t": [4612, 6725]}]}, {"id": "ch14p19", "audio": true, "sents": [{"it": "“Questo sì che è buffo!", "zh": "这真叫人好笑！", "t": [100, 1612]}, {"it": "Da te i giorni durano un minuto!”", "zh": "这儿的白天仅有一分钟。", "t": [1612, 3513]}]}, {"id": "ch14p20", "audio": true, "sents": [{"it": "“Non è affatto buffo,” disse il lampionaio.", "zh": "“这并不可笑，”点灯人说。", "t": [100, 2712]}, {"it": "“Noi due stiamo parlando già da un mese.”", "zh": "我们已交谈了一个月。", "t": [2712, 4912]}]}, {"id": "ch14p21", "audio": true, "sents": [{"it": "“Da un mese?”", "zh": "“一个月了？”", "t": [100, 850]}]}, {"id": "ch14p22", "audio": true, "sents": [{"it": "“Sì.", "zh": "是的。", "t": [100, 825]}, {"it": "Trenta minuti.", "zh": "三十分钟。", "t": [825, 1962]}, {"it": "Trenta giorni!", "zh": "三十天", "t": [1962, 3175]}, {"it": "Buonasera.”", "zh": "晚安。", "t": [3175, 3963]}]}, {"id": "ch14p23", "audio": true, "sents": [{"it": "E riaccese il lampione.", "zh": "他又点亮了灯火。", "t": [100, 1600]}]}, {"id": "ch14p24", "audio": true, "sents": [{"it": "Il piccolo principe lo guardò e provò simpatia per quel lampionaio così ligio alle direttive che aveva ricevuto.", "zh": "小王子看着他，对这个恪守指令的路灯工产生了同情。", "t": [100, 6137]}]}, {"id": "ch14p25", "audio": true, "sents": [{"it": "“Sai...", "zh": "你知道……", "t": [100, 812]}, {"it": "posso insegnarti un trucco per riposarti quando vuoi...”", "zh": "我可以教你一个休息的小窍门……", "t": [812, 3663]}]}, {"id": "ch14p26", "audio": true, "sents": [{"it": "“Io lo voglio sempre,” disse il lampionaio.", "zh": "“我总是想要它，”点灯人说。", "t": [100, 2313]}]}, {"id": "ch14p27", "audio": true, "sents": [{"it": "Un uomo, infatti, può essere contemporaneamente coscienzioso e pigro.", "zh": "一个人，其实可以同时既警觉又懒惰。", "t": [100, 5000]}]}, {"id": "ch14p28", "audio": true, "sents": [{"it": "Il piccolo principe proseguì:", "zh": "小王子继续说道：", "t": [100, 1913]}]}, {"id": "ch14p29", "audio": true, "sents": [{"it": "“Il tuo pianeta è talmente piccolo che in tre falcate ne fai il giro.", "zh": "你的星球如此之小，只需三步就能绕它一周。", "t": [100, 4212]}, {"it": "Per rimanere sempre al sole basta che cammini molto piano.", "zh": "只需缓缓前行，便能始终沐浴在阳光下。", "t": [4212, 7762]}, {"it": "Quando vorrai riposarti, dovrai solo camminare...", "zh": "当你想休息时，只需漫步而行……", "t": [7762, 10962]}, {"it": "e il giorno durerà tutto il tempo che vorrai.”", "zh": "白天将持续你想要的时间。", "t": [10962, 13350]}]}, {"id": "ch14p30", "audio": true, "sents": [{"it": "“Sai che m’importa!” disse il lampionaio.", "zh": "“你知道吗，这对我来说很重要！”点灯人说。", "t": [100, 3375]}, {"it": "“A me nella vita piace dormire.”", "zh": "我生平喜欢睡觉。", "t": [3375, 4900]}]}, {"id": "ch14p31", "audio": true, "sents": [{"it": "“Proprio una bella scalogna,” disse il piccolo principe.", "zh": "“这真是一道美味的蘑菇啊，”小王子说。", "t": [100, 3075]}]}, {"id": "ch14p32", "audio": true, "sents": [{"it": "“Sì, una bella scalogna davvero,” disse il lampionaio.", "zh": "“是啊，真是一道美味的蘑菇啊，”点灯人说。", "t": [100, 3875]}, {"it": "“Buongiorno.”", "zh": "你好。", "t": [3875, 4663]}]}, {"id": "ch14p33", "audio": true, "sents": [{"it": "E spense il lampione.", "zh": "熄灭了灯火。", "t": [100, 1450]}]}, {"id": "ch14p34", "audio": true, "sents": [{"it": "“Quell’uomo sarebbe disprezzato da tutti gli altri,” disse tra sé il piccolo principe, proseguendo il suo viaggio, “dal re, dal vanitoso, dal bevitore, dall’uomo d’affari.", "zh": "那个点灯人会被所有人轻视，”小王子在继续他的旅程时自言自语道，“会被国王、虚荣的人、酒鬼、商人轻视。", "t": [100, 10700]}, {"it": "Tuttavia è l’unico che non mi sembra ridicolo.", "zh": "然而，他似乎并不荒谬。", "t": [10700, 13325]}, {"it": "Forse perché si occupa di qualcos’altro che non sia se stesso.”", "zh": "或许是因为他忙于其他，而非自身之事。", "t": [13325, 16238]}]}, {"id": "ch14p35", "audio": true, "sents": [{"it": "Ebbe un sospiro di rammarico e si disse ancora:", "zh": "他叹了口气，又自言自语道：", "t": [100, 2825]}]}, {"id": "ch14p36", "audio": true, "sents": [{"it": "“Quell’uomo è l’unico che avrei potuto farmi amico.", "zh": "那人是唯一我能与之成为朋友的人。", "t": [100, 3000]}, {"it": "Ma il suo pianeta è davvero troppo piccolo.", "zh": "他的星球实在太小了。", "t": [3000, 5512]}, {"it": "Non c’è posto per due...”", "zh": "此处容不下两个人…", "t": [5512, 6912]}]}, {"id": "ch14p37", "audio": true, "sents": [{"it": "Il piccolo principe non osava ammettere che rimpiangeva quel pianeta benedetto soprattutto per i millequattrocento quaranta tramonti ogni ventiquattro ore!", "zh": "小王子不敢承认，他之所以怀念那颗幸福的星球，主要是因为那里每二十四小时就能观赏到一千四百四十次日落。", "t": [100, 8725]}]}]}, {"id": "ch15", "title_it": "XV", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"it": "Il sesto pianeta era un pianeta dieci volte più grande.", "zh": "第六颗星球比那颗大十倍。", "t": [100, 3800]}, {"it": "Era abitato da un anziano signore che scriveva certi enormi libri.", "zh": "住着一位老先生，正撰写那些庞大的著作。", "t": [3800, 7575]}]}, {"id": "ch15p01", "audio": true, "sents": [{"it": "“Toh!", "zh": "哟！", "t": [100, 625]}, {"it": "Ecco un esploratore!” esclamò quando vide il piccolo principe.", "zh": "来了一位探险家！", "t": [625, 4426]}]}, {"id": "ch15p02", "audio": true, "sents": [{"it": "Il piccolo principe si sedette sul tavolo e tirò il fiato.", "zh": "小王子坐在桌子上，呼出一口长气。", "t": [100, 4000]}, {"it": "Aveva già viaggiato così tanto!", "zh": "他已经旅行了这么远！", "t": [4000, 5737]}]}, {"id": "ch15p03", "audio": true, "sents": [{"it": "“Da dove vieni?” domandò l’anziano signore.", "zh": "您是从哪里来的？", "t": [100, 2788]}]}, {"id": "ch15p04", "audio": true, "sents": [{"it": "“Cos’è quel librone?” disse il piccolo principe.", "zh": "那本厚书是何物？小王子问道。", "t": [100, 3338]}, {"it": "“Che cosa fa qui?”", "zh": "他在这里做什么？", "t": [3338, 4187]}]}, {"id": "ch15p05", "audio": true, "sents": [{"it": "“Sono un geografo,” disse l’anziano signore.", "zh": "“我是一位地理学家，”那位老先生说道。", "t": [100, 2600]}]}, {"id": "ch15p06", "audio": true, "sents": [{"it": "“Che cos’è un geografo?”", "zh": "地理学家是何人？", "t": [100, 1388]}]}, {"id": "ch15p07", "audio": true, "sents": [{"it": "“È uno scienziato che sa dove si trovano i mari, i fiumi, le città, le montagne e i deserti.”", "zh": "这是一位科学家，他知道大海、江河、城市、山脉和沙漠在哪里。", "t": [100, 6225]}]}, {"id": "ch15p08", "audio": true, "sents": [{"it": "“Questo sì che è interessante,” disse il piccolo principe.", "zh": "这倒很有趣，小王子说。", "t": [100, 3412]}, {"it": "“Finalmente un vero mestiere!” E diede un’occhiata intorno a sé al pianeta del geografo.", "zh": "终于，一份真正的职业！他环顾四周，打量着地理学家的星球。", "t": [3412, 8938]}, {"it": "Non aveva mai visto un pianeta così maestoso.", "zh": "如此庄严的星球，他前所未见。", "t": [8938, 11475]}]}, {"id": "ch15p09", "audio": true, "sents": [{"it": "“È proprio bello il suo pianeta.", "zh": "他的星球真美。", "t": [100, 1975]}, {"it": "Ci sono degli oceani?”", "zh": "这里有大洋吗？", "t": [1975, 3187]}]}, {"id": "ch15p10", "audio": true, "sents": [{"it": "“Non posso saperlo,” disse il geografo.", "zh": "“这我可不知道，”地理学家说。", "t": [100, 2350]}]}, {"id": "ch15p11", "audio": true, "sents": [{"it": "“Ah!” (Il piccolo principe era deluso.) “E montagne?”", "zh": "啊！小王子失望地叹了口气，“有山吗？”", "t": [100, 3763]}]}, {"id": "ch15p12", "audio": true, "sents": [{"it": "“Non posso saperlo,” disse il geografo.", "zh": "“这我可不知道，”地理学家说。", "t": [100, 2350]}]}, {"id": "ch15p13", "audio": true, "sents": [{"it": "“E città e fiumi e deserti?”", "zh": "城市、河流、沙漠？", "t": [100, 1775]}]}, {"id": "ch15p14", "audio": true, "sents": [{"it": "“Non posso sapere neanche questo,” disse il geografo.", "zh": "“这我也无法知晓，”地理学家说。", "t": [100, 3074]}]}, {"id": "ch15p15", "audio": true, "sents": [{"it": "“Ma lei è un geografo!”", "zh": "他可是地理学家！", "t": [100, 1513]}]}, {"id": "ch15p16", "audio": true, "sents": [{"it": "“Certo,” disse il geografo, “ma non sono un esploratore.", "zh": "“当然，”地理学家说，“但我不是探险家。”", "t": [100, 3825]}, {"it": "Mi mancano gli esploratori.", "zh": "我缺少探险家。", "t": [3825, 5638]}, {"it": "Non è il geografo che fa il conto delle città, dei fiumi, delle montagne, dei mari, degli oceani e dei deserti.", "zh": "地理学家并非计数城市、江河、山脉、海洋、大洋与沙漠之人。", "t": [5638, 13288]}, {"it": "Il geografo è troppo importante e non può andare a zonzo.", "zh": "地理学家太过重要，不能随意闲逛。", "t": [13288, 16900]}, {"it": "Non esce mai dal suo studio.", "zh": "他从未离开过他的工作室。", "t": [16900, 18788]}, {"it": "Ma lì riceve gli esploratori.", "zh": "他接待探险家。", "t": [18788, 20725]}, {"it": "Li ascolta e trascrive i loro ricordi.", "zh": "他聆听并记录下他们的回忆。", "t": [20725, 23350]}, {"it": "E se i ricordi di uno di loro gli sembrano interessanti, il geografo fa fare un’indagine sulla moralità dell’esploratore.”", "zh": "若其中某位探险家的回忆引起了地理学家的兴趣，他便会调查这位探险者的品德。", "t": [23350, 30276]}]}, {"id": "ch15p17", "audio": true, "sents": [{"it": "“Per quale motivo?”", "zh": "为什么？", "t": [100, 1125]}]}, {"id": "ch15p18", "audio": true, "sents": [{"it": "“Perché se un esploratore dovesse mentire, provocherebbe dei pasticci nei libri di geografia.", "zh": "若那位探险家若是撒谎，定会在地理学书籍中惹出乱子。", "t": [100, 5638]}, {"it": "E lo stesso vale per un esploratore che bevesse troppo.”", "zh": "一个酒鬼探险家也同样不行。", "t": [5638, 8600]}]}, {"id": "ch15p19", "audio": true, "sents": [{"it": "“Per quale motivo?”", "zh": "为何如此？", "t": [100, 1125]}]}, {"id": "ch15p20", "audio": true, "sents": [{"it": "“Perché gli ubriaconi vedono doppio.", "zh": "酒鬼看到的总是一重影。", "t": [100, 2388]}, {"it": "Perciò l’esploratore segnerebbe due montagne dove invece ce n’è una sola.”", "zh": "因此，探险家会在只有一个山的地方标记出两座山。", "t": [2388, 6663]}]}, {"id": "ch15p21", "audio": true, "sents": [{"it": "“Conosco un tale,” disse il piccolo principe, “che sarebbe un pessimo esploratore.”", "zh": "我认识一个这样的人，他将成为一个糟糕的探险家。", "t": [100, 4863]}]}, {"id": "ch15p22", "audio": true, "sents": [{"it": "“È possibile.", "zh": "这是可能的。", "t": [100, 1238]}, {"it": "Poi, dopo aver verificato la moralità dell’esploratore, si fa un’indagine sulla sua scoperta.”", "zh": "然后，在核实探险家的品德之后，便对其发现进行考察。", "t": [1238, 6863]}]}, {"id": "ch15p23", "audio": true, "sents": [{"it": "“Andate a vedere?”", "zh": "去看看吧？", "t": [100, 975]}]}, {"id": "ch15p24", "audio": true, "sents": [{"it": "“No.", "zh": "不。", "t": [100, 400]}, {"it": "È troppo complicato.", "zh": "实在太过复杂了。", "t": [400, 1888]}, {"it": "Ma si chiede all’esploratore di fornire delle prove.", "zh": "他要求探险家提供证据。", "t": [1888, 4912]}, {"it": "Nel caso per esempio della scoperta di una grande montagna, si chiede che porti qualche grossa pietra.”", "zh": "若发现了一座大山，便要求他带来几块大石头。", "t": [4912, 10912]}]}, {"id": "ch15p25", "audio": true, "sents": [{"it": "Il geografo all’improvviso trasalì.", "zh": "地理学家突然激动起来。", "t": [100, 2162]}]}, {"id": "ch15p26", "audio": true, "sents": [{"it": "“Ma tu vieni da lontano!", "zh": "你从远方来！", "t": [100, 1825]}, {"it": "Sei un esploratore!", "zh": "你是一位探险家！", "t": [1825, 3475]}, {"it": "Devi assolutamente descrivermi il tuo pianeta!”", "zh": "您必须给我描述一下您的星球！", "t": [3475, 6150]}]}, {"id": "ch15p27", "audio": true, "sents": [{"it": "E dopo aver aperto il registro, il geografo temperò la matita.", "zh": "地理学家打开登记册，削尖了铅笔。", "t": [100, 4300]}, {"it": "I resoconti degli esploratori sono inizialmente scritti a matita.", "zh": "探险家的叙述起初是用铅笔写下的。", "t": [4300, 8325]}, {"it": "Poi, quando l’esploratore ha fornito le prove, sono ripassati a penna.", "zh": "然后，当探险家提供了证据，便用钢笔誊写。", "t": [8325, 12700]}]}, {"id": "ch15p28", "audio": true, "sents": [{"it": "“Allora?” interrogò il geografo.", "zh": "那么，地理学家问道。", "t": [100, 2300]}]}, {"id": "ch15p29", "audio": true, "sents": [{"it": "“Oh!", "zh": "哟！", "t": [100, 812]}, {"it": "Il posto dove sto io non è molto interessante,” disse il piccolo principe.", "zh": "那地方可没什么意思，小王子说。", "t": [812, 5288]}, {"it": "“È piccolissimo.", "zh": "它实在太小了。", "t": [5288, 6625]}, {"it": "Ho tre vulcani.", "zh": "我有三座火山。", "t": [6625, 7900]}, {"it": "Due attivi e uno spento.", "zh": "两座活火山，一座死火山。", "t": [7900, 9712]}, {"it": "Ma non si sa mai.”", "zh": "无人知晓。", "t": [9712, 10750]}]}, {"id": "ch15p30", "audio": true, "sents": [{"it": "“Non si sa mai,” disse il geografo.", "zh": "无人知晓，地理学家说。", "t": [100, 2150]}]}, {"id": "ch15p31", "audio": true, "sents": [{"it": "“Ho anche una rosa.”", "zh": "我还有一朵玫瑰。", "t": [100, 1163]}]}, {"id": "ch15p32", "audio": true, "sents": [{"it": "“Noi non registriamo i fiori,” disse il geografo.", "zh": "我们不记录花朵，地理学家说。", "t": [100, 2850]}]}, {"id": "ch15p33", "audio": true, "sents": [{"it": "“Perché mai!", "zh": "为什么啊！", "t": [100, 1112]}, {"it": "Sono la cosa più bella!”", "zh": "这是最美的东西！", "t": [1112, 2463]}]}, {"id": "ch15p34", "audio": true, "sents": [{"it": "“Perché i fiori sono effimeri!”", "zh": "花朵之所以短暂。", "t": [100, 1762]}]}, {"id": "ch15p35", "audio": true, "sents": [{"it": "“Che cosa vuol dire ‘effimero’?”", "zh": "“‘昙花一现’是什么意思？”", "t": [100, 1600]}]}, {"id": "ch15p36", "audio": true, "sents": [{"it": "“I libri di geografia,” disse il geografo, “sono i libri più seri che ci siano.", "zh": "地理书，地理学家说，“是世上最严肃的书。", "t": [100, 5050]}, {"it": "Non passano mai di moda.", "zh": "永不褪色。", "t": [5050, 6688]}, {"it": "È rarissimo che una montagna cambi posto.", "zh": "山移位，极为罕见。", "t": [6688, 9188]}, {"it": "È rarissimo che un oceano si prosciughi.", "zh": "海洋干涸极为罕见。", "t": [9188, 11625]}, {"it": "Noi scriviamo cose eterne.”", "zh": "我们记录永恒的事物。", "t": [11625, 13326]}]}, {"id": "ch15p37", "audio": true, "sents": [{"it": "“Ma i vulcani spenti possono risvegliarsi,” interruppe il piccolo principe.", "zh": "死火山也可能苏醒，小王子打断了他的话。", "t": [100, 4812]}, {"it": "“Che cosa significa ‘effimero’?”", "zh": "“‘昙花一现’是什么意思？”", "t": [4812, 6438]}]}, {"id": "ch15p38", "audio": true, "sents": [{"it": "“Che i vulcani siano spenti o attivi, per noialtri è lo stesso,” disse il geografo.", "zh": "火山熄灭与否，于我们而言并无二致。", "t": [100, 5400]}, {"it": "“Ciò che conta per noi è la montagna.", "zh": "对我们而言，重要的是山。", "t": [5400, 7588]}, {"it": "E quella non cambia!”", "zh": "那山永不改变。", "t": [7588, 8787]}]}, {"id": "ch15p39", "audio": true, "sents": [{"it": "“Ma che cosa vuol dire ‘effimero’?” ripeté il piccolo principe che in vita sua non aveva mai rinunciato a una domanda dopo che l’aveva fatta.", "zh": "“‘昙花一现’是什么意思？”小王子重复道，他一生中从未在提出问题后轻易放弃。", "t": [100, 7513]}]}, {"id": "ch15p40", "audio": true, "sents": [{"it": "“Vuol dire che è destinato a scomparire presto.”", "zh": "它注定很快就会消失。", "t": [100, 2688]}]}, {"id": "ch15p41", "audio": true, "sents": [{"it": "“La mia rosa è destinata a scomparire presto?”", "zh": "我的玫瑰注定要很快消失。", "t": [100, 2624]}]}, {"id": "ch15p42", "audio": true, "sents": [{"it": "“Certo.”", "zh": "当然。", "t": [100, 762]}]}, {"id": "ch15p43", "audio": true, "sents": [{"it": "“La mia rosa è effimera,” disse tra sé il piccolo principe, “e ha solo quattro spine per difendersi dal mondo!", "zh": "我的玫瑰是短暂的，小王子自言自语道，它只有四根刺来保护自己，抵御这个世界！", "t": [100, 6750]}, {"it": "E l’ho lasciata sola là dove sto io!”", "zh": "我让她孤零零地留在了那里！", "t": [6750, 8650]}]}, {"id": "ch15p44", "audio": true, "sents": [{"it": "Fu il suo primo moto di rammarico.", "zh": "他的第一个悔意之动。", "t": [100, 2288]}, {"it": "Ma si fece coraggio:", "zh": "鼓起勇气。", "t": [2288, 3600]}]}, {"id": "ch15p45", "audio": true, "sents": [{"it": "“Cosa mi consiglia di andare a visitare?” domandò.", "zh": "您能否指点我，我该去哪儿访问？", "t": [100, 2950]}]}, {"id": "ch15p46", "audio": true, "sents": [{"it": "“Il pianeta Terra,” gli rispose il geografo.", "zh": "“地球，”地理学家回答道。", "t": [100, 2838]}, {"it": "“Ne parlano molto bene...”", "zh": "他们谈得很好……", "t": [2838, 4238]}]}, {"id": "ch15p47", "audio": true, "sents": [{"it": "E il piccolo principe se ne andò, pensando alla sua rosa.", "zh": "小王子离去，心中想着他的玫瑰。", "t": [100, 3500]}]}]}, {"id": "ch16", "title_it": "XVI", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": [{"it": "Il settimo pianeta fu quindi la Terra.", "zh": "第七颗星球便是地球。", "t": [100, 2400]}]}, {"id": "ch16p01", "audio": true, "sents": [{"it": "La Terra non è un pianeta qualsiasi!", "zh": "地球并非普通行星。", "t": [100, 2612]}, {"it": "Conta centoundici re (fra cui ovviamente i re negri), settemila geografi, novecentomila uomini d’affari, sette milioni e mezzo di ubriaconi, trecentoundici milioni di vanitosi, che fanno in tutto circa due miliardi di adulti.", "zh": "一百一十一个国王（其中自然包括黑人国王）、七千位地理学家、九十万商人、七百五十万酒徒、三亿一千一百万自恋者，总计约二十亿成年人。", "t": [2612, 17750]}]}, {"id": "ch16p02", "audio": true, "sents": [{"it": "Per darvi un’idea delle dimensioni della Terra sappiate solo che, prima dell’invenzione dell’elettricità, nell’insieme dei sei continenti si doveva disporre di un vero e proprio esercito di quattrocento sessantaduemila cinquecento undici lampionai.", "zh": "为了使你们对地球的规模有所概念，须知在电发明之前，六大洲总共需部署一支由四万六千二百五十一名点灯人组成的庞大军队。", "t": [100, 14562]}]}, {"id": "ch16p03", "audio": true, "sents": [{"it": "Visto da una certa distanza, il tutto faceva un bellissimo effetto.", "zh": "从远处望去，这一切显得格外迷人。", "t": [100, 4525]}, {"it": "I movimenti di quell’esercito erano sincronizzati come quelli di un balletto.", "zh": "那支军队的动作如同芭蕾舞者般协调一致。", "t": [4525, 9138]}, {"it": "Prima toccava ai lampionai della Nuova Zelanda e dell’Australia.", "zh": "新西兰和澳大利亚的点灯人率先登场。", "t": [9138, 13338]}, {"it": "Quando questi avevano acceso i loro lampioni, se ne andavano a dormire.", "zh": "这些点灯人点亮了路灯，便去安睡了。", "t": [13338, 17588]}, {"it": "Allora entravano in scena i lampionai della Cina e della Siberia.", "zh": "中国和西伯利亚的点灯人粉墨登场。", "t": [17588, 21462]}, {"it": "Poi anche loro sparivano dietro le quinte.", "zh": "他们也悄然退场。", "t": [21462, 24012]}, {"it": "Allora toccava ai lampionai della Russia e delle Indie.", "zh": "轮到俄罗斯和印度的点灯人了。", "t": [24012, 27200]}, {"it": "Poi a quelli dell’Africa e dell’Europa.", "zh": "随后是非洲和欧洲的点灯人。", "t": [27200, 29550]}, {"it": "Poi a quelli del Sudamerica.", "zh": "接着是南美洲的点灯人。", "t": [29550, 31488]}, {"it": "Poi a quelli del Nordamerica.", "zh": "接着是北美洲的点灯人。", "t": [31488, 33488]}, {"it": "E mai che sbagliassero un’entrata in scena.", "zh": "舞台上的入场顺序从未出错。", "t": [33488, 35887]}]}, {"id": "ch16p04", "audio": true, "sents": [{"it": "Solo il lampionaio dell’unico lampione del Polo Nord e il suo collega dell’unico lampione del Polo Sud conducevano vite pigre e sfaccendate: lavoravano due volte l’anno.", "zh": "北极那盏孤灯的守灯人和南极同行的伙伴过着慵懒而无所事事的生活：他们一年只工作两次。", "t": [100, 9700]}]}]}, {"id": "ch17", "title_it": "XVII", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"it": "Quando uno vuole fare dello spirito, è facile che racconti qualche frottola.", "zh": "他若想卖弄风骚，难免会编些胡话。", "t": [100, 4600]}, {"it": "Parlandovi dei lampionai, non sono stato molto corretto.", "zh": "谈论点灯人时，我并未十分严谨。", "t": [4600, 8200]}, {"it": "Rischio di dare a quelli che non lo conoscono un’idea sbagliata del nostro pianeta.", "zh": "可能让不熟悉我们星球的人产生对它的错误印象。", "t": [8200, 12912]}, {"it": "Sulla Terra gli uomini occupano pochissimo spazio.", "zh": "地球上的人类占据的空间微不足道。", "t": [12912, 16238]}, {"it": "Se i due miliardi di abitanti che popolano la Terra stessero in piedi e un po’ pigiati, come a un comizio, potrebbero occupare una piazza pubblica di venti miglia per venti miglia.", "zh": "若地球上的二十亿居民站立并略微蜷缩，如同参加集会一般，他们便能占据一个二十英里长、二十英里宽的公共广场。", "t": [16238, 26275]}, {"it": "Si potrebbe ammassare l’umanità su un qualsiasi isolotto del Pacifico.", "zh": "人类可以挤在太平洋上任何一座小岛上。", "t": [26275, 30350]}]}, {"id": "ch17p01", "audio": true, "sents": [{"it": "Gli adulti ovviamente non vi crederanno.", "zh": "大人们当然不会相信你们。", "t": [100, 2675]}, {"it": "Pensano di occupare molto spazio.", "zh": "他们以为占据了很大的空间。", "t": [2675, 4988]}, {"it": "Si immaginano imponenti come baobab.", "zh": "他们自以为像猴面包树那样威严。", "t": [4988, 7700]}, {"it": "Consigliategli di fare il calcolo.", "zh": "建议他算一算。", "t": [7700, 9812]}, {"it": "Si divertiranno, perché adorano i numeri.", "zh": "他们定会高兴，因为数字正是他们所爱。", "t": [9812, 12525]}, {"it": "Ma voi non perdete tempo con questo compitino.", "zh": "你们别在这小题大做了。", "t": [12525, 15425]}, {"it": "È inutile.", "zh": "徒劳无功。", "t": [15425, 16425]}, {"it": "Fidatevi di me.", "zh": "请相信我。", "t": [16425, 17300]}]}, {"id": "ch17p02", "audio": true, "sents": [{"it": "Così, una volta giunto sulla Terra, il piccolo principe fu stupito di non vedere nessuno.", "zh": "小王子抵达地球后，惊讶地发现无人踪影。", "t": [100, 6200]}, {"it": "Temeva già di aver sbagliato pianeta quando un anello color della luna si mosse sulla sabbia.", "zh": "他担心自己误闯了星球，正当月白色圆环在沙地上移动时。", "t": [6200, 11276]}]}, {"id": "ch17p03", "audio": true, "sents": [{"it": "“Buona notte,” disse il piccolo principe a casaccio.", "zh": "“晚安，”小王子随口说道。", "t": [100, 3088]}]}, {"id": "ch17p04", "audio": true, "sents": [{"it": "“Buona notte,” fece il serpente.", "zh": "“晚安，”蛇说。", "t": [100, 1913]}]}, {"id": "ch17p05", "audio": true, "sents": [{"it": "“Su quale pianeta sono finito?” domandò il piccolo principe.", "zh": "小王子问道：“我究竟来到了哪个星球？”", "t": [100, 3787]}]}, {"id": "ch17p06", "audio": true, "sents": [{"it": "“Sulla Terra, in Africa,” rispose il serpente.", "zh": "“在非洲，地球之上，”蛇回答说。", "t": [100, 2974]}]}, {"id": "ch17p07", "audio": true, "sents": [{"it": "“Ah!...", "zh": "哦！", "t": [100, 750]}, {"it": "Ma non c’è nessuno sulla Terra?”", "zh": "地球上无人迹", "t": [750, 2412]}]}, {"id": "ch17p08", "audio": true, "sents": [{"it": "“Qui siamo nel deserto.", "zh": "我们身处沙漠之中。", "t": [100, 1775]}, {"it": "E nei deserti non c’è nessuno.", "zh": "沙漠中无人迹。", "t": [1775, 3812]}, {"it": "La Terra è grande,” disse il serpente.", "zh": "大地辽阔，蛇说。", "t": [3812, 6126]}]}, {"id": "ch17p09", "audio": true, "sents": [{"it": "Il piccolo principe si sedette su un sasso e levò gli occhi verso il cielo.", "zh": "小王子坐在一块石头上，仰望天空。", "t": [100, 4512]}]}, {"id": "ch17p10", "audio": true, "sents": [{"it": "“Mi domando,” disse, “se le stelle brillano perché un giorno ciascuno possa ritrovare la propria.", "zh": "我自言自语道：“星星之所以闪耀，或许是为了有一天每个人都能找到属于自己的那颗。”", "t": [100, 5462]}, {"it": "Guarda il mio pianeta.", "zh": "看我的星球。", "t": [5462, 6862]}, {"it": "È esattamente sopra di noi...", "zh": "它正悬于我们头顶之上……", "t": [6862, 8675]}, {"it": "Ma com’è lontano!”", "zh": "它多么遥远啊！", "t": [8675, 9850]}]}, {"id": "ch17p11", "audio": true, "sents": [{"it": "“È bello,” disse il serpente.", "zh": "“真美啊，”蛇说。", "t": [100, 1950]}, {"it": "“Che cosa sei venuto a fare qui?”", "zh": "你为何来到这里？", "t": [1950, 3526]}]}, {"id": "ch17p12", "audio": true, "sents": [{"it": "“Ho dei problemi con una rosa,” disse il piccolo principe.", "zh": "“我和一朵玫瑰闹了些别扭，”小王子说。", "t": [100, 3125]}]}, {"id": "ch17p13", "audio": true, "sents": [{"it": "“Ah!” fece il serpente.", "zh": "哦！蛇说。", "t": [100, 1588]}]}, {"id": "ch17p14", "audio": true, "sents": [{"it": "E tacquero.", "zh": "我这就去。", "t": [100, 862]}]}, {"id": "ch17p15", "audio": true, "sents": [{"it": "“Dove sono gli uomini?” riprese poi il piccolo principe.", "zh": "人们在哪里？小王子又问。", "t": [100, 3925]}, {"it": "“Si è un po’ soli nel deserto...”", "zh": "沙漠里有些孤单……", "t": [3925, 5650]}]}, {"id": "ch17p16", "audio": true, "sents": [{"it": "“Si è soli anche fra gli uomini,” disse il serpente.", "zh": "人与人之间，同样孤独。", "t": [100, 2900]}]}, {"id": "ch17p17", "audio": true, "sents": [{"it": "Il piccolo principe lo guardò lungamente:", "zh": "小王子久久地凝视着他。", "t": [100, 2450]}]}, {"id": "ch17p18", "audio": true, "sents": [{"it": "“Sei uno strano animale,” gli disse alla fine, “sottile come un dito...”", "zh": "你真是个奇怪的动物。", "t": [100, 4113]}]}, {"id": "ch17p19", "audio": true, "sents": [{"it": "“Ma sono più potente del dito di un re,” disse il serpente.", "zh": "“可我比国王的指头更有力量。”蛇说。", "t": [100, 3226]}]}, {"id": "ch17p20", "audio": true, "sents": [{"it": "Il piccolo principe sorrise:", "zh": "小王子微笑着：", "t": [100, 1874]}]}, {"id": "ch17p21", "audio": true, "sents": [{"it": "“Non si direbbe...", "zh": "这话说得未免太过分了……", "t": [100, 1325]}, {"it": "non hai neanche le zampe...", "zh": "你连脚都没有……", "t": [1325, 2975]}, {"it": "non puoi neanche viaggiare...”", "zh": "你甚至无法旅行……", "t": [2975, 4488]}]}, {"id": "ch17p22", "audio": true, "sents": [{"it": "“Ti posso portare più lontano di quanto possa fare una nave,” disse il serpente.", "zh": "“我能带你走得更远，比任何船只都要遥远，”蛇说。", "t": [100, 4350]}]}, {"id": "ch17p23", "audio": true, "sents": [{"it": "Si avvolse intorno alla caviglia del piccolo principe, come una catenina d’oro:", "zh": "它绕着小王子的脚踝盘旋，宛如一条金链。", "t": [100, 4537]}]}, {"id": "ch17p24", "audio": true, "sents": [{"it": "“Chiunque tocco, lo restituisco alla terra da cui proviene,” disse ancora.", "zh": "“我所触及的，都能送回它们起源之地。”", "t": [100, 4525]}, {"it": "“Ma tu sei puro e vieni da una stella...”", "zh": "你纯洁，来自一颗星星……", "t": [4525, 6837]}]}, {"id": "ch17p25", "audio": true, "sents": [{"it": "Il piccolo principe non disse nulla.", "zh": "小王子默默无言。", "t": [100, 2212]}]}, {"id": "ch17p26", "audio": true, "sents": [{"it": "“Mi fai pena, così fragile su questa Terra di granito.", "zh": "在这花岗岩构成的地球上，你如此脆弱，令人惋惜。", "t": [100, 3700]}, {"it": "Se un giorno dovessi rimpiangere troppo il tuo pianeta, posso aiutarti.", "zh": "若你某日过分思念你的星球，我可以助你一臂之力。", "t": [3700, 8062]}, {"it": "Posso...”", "zh": "我可以……", "t": [8062, 8624]}]}, {"id": "ch17p27", "audio": true, "sents": [{"it": "“Oh, ho capito benissimo,” fece il piccolo principe, “ma perché parli sempre per enigmi?”", "zh": "“哦，我完全明白了，”小王子说，“但你为何总是用谜语般的话语？”", "t": [100, 5075]}]}, {"id": "ch17p28", "audio": true, "sents": [{"it": "“Li risolvo tutti,” disse il serpente.", "zh": "“我解开所有的谜团，”蛇说。", "t": [100, 2324]}]}, {"id": "ch17p29", "audio": true, "sents": [{"it": "E tacquero.", "zh": "我这就去。", "t": [100, 862]}]}]}, {"id": "ch18", "title_it": "XVIII", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"it": "Il piccolo principe attraversò il deserto e incontrò soltanto un fiore.", "zh": "小王子穿越沙漠，只邂逅了一朵花。", "t": [100, 4500]}, {"it": "Un fiore con tre petali, un fiore da niente...", "zh": "一朵三瓣的花，一朵毫不起眼的花……", "t": [4500, 7337]}]}, {"id": "ch18p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe.", "zh": "你好，小王子说。", "t": [100, 2226]}]}, {"id": "ch18p02", "audio": true, "sents": [{"it": "“Buongiorno,” disse il fiore.", "zh": "你好，花儿说。", "t": [100, 1626]}]}, {"id": "ch18p03", "audio": true, "sents": [{"it": "“Dove sono gli uomini?” domandò gentilmente il piccolo principe.", "zh": "“人在何处？”小王子彬彬有礼地问道。", "t": [100, 4337]}]}, {"id": "ch18p04", "audio": true, "sents": [{"it": "Un giorno il fiore aveva visto passare una carovana:", "zh": "那天，花儿曾见过一队商队经过。", "t": [100, 3112]}]}, {"id": "ch18p05", "audio": true, "sents": [{"it": "“Gli uomini?", "zh": "人？", "t": [100, 1238]}, {"it": "Credo ce ne siano sei o sette.", "zh": "或许有六七个吧。", "t": [1238, 3250]}, {"it": "Li ho intravisti anni fa.", "zh": "几年前我曾见过他们。", "t": [3250, 4900]}, {"it": "Ma non si sa mai dove trovarli.", "zh": "不知他们在何方。", "t": [4900, 6912]}, {"it": "Vanno in balìa del vento.", "zh": "随风而去。", "t": [6912, 8638]}, {"it": "Non hanno radici, e questo per loro è un bel problema.”", "zh": "他们没有根，这可真是他们的难题。", "t": [8638, 12187]}]}, {"id": "ch18p06", "audio": true, "sents": [{"it": "“Addio,” fece il piccolo principe.", "zh": "“再见了，”小王子说。", "t": [100, 2112]}]}, {"id": "ch18p07", "audio": true, "sents": [{"it": "“Addio,” disse il fiore.", "zh": "“再见了，”花儿说。", "t": [100, 1488]}]}]}, {"id": "ch19", "title_it": "XIX", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": [{"it": "Il piccolo principe scalò un’alta montagna.", "zh": "小王子攀登上一座高山。", "t": [100, 2950]}, {"it": "Le uniche montagne che avesse mai conosciuto erano i tre vulcani che gli arrivavano al ginocchio.", "zh": "他认识的唯一山脉，不过是那些仅至膝盖的三座火山。", "t": [2950, 8550]}, {"it": "Adoperava il vulcano spento come uno sgabello.", "zh": "他用那座死火山当凳子。", "t": [8550, 11688]}, {"it": "“Da una montagna così alta,” si disse quindi, “vedrò l’intero pianeta e tutti gli uomini...” Ma vide soltanto alcuni picchi aguzzi.", "zh": "“从这么高的山上，”他自言自语，“我就能看到整个星球和所有的人了……”然而，他只见到了几座陡峭的山峰。", "t": [11688, 19412]}]}, {"id": "ch19p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse a casaccio.", "zh": "你好，他漫不经心地说。", "t": [100, 1812]}]}, {"id": "ch19p02", "audio": true, "sents": [{"it": "“Buongiorno...", "zh": "你好……", "t": [100, 1075]}, {"it": "buongiorno...", "zh": "你好……", "t": [1075, 2025]}, {"it": "buongiorno...” rispose l’eco.", "zh": "你好……回声答道。", "t": [2025, 3900]}]}, {"id": "ch19p03", "audio": true, "sents": [{"it": "“Chi siete?” disse il piccolo principe.", "zh": "你是谁？小王子问道。", "t": [100, 2675]}]}, {"id": "ch19p04", "audio": true, "sents": [{"it": "“Chi siete...", "zh": "你是谁……", "t": [100, 1062]}, {"it": "chi siete...", "zh": "你是谁……", "t": [1062, 2025]}, {"it": "chi siete...” rispose l’eco.", "zh": "你是谁……回声答道。", "t": [2025, 3875]}]}, {"id": "ch19p05", "audio": true, "sents": [{"it": "“Siate miei amici, sono solo,” disse.", "zh": "“成为我的朋友吧，我很孤单。”他说。", "t": [100, 2350]}]}, {"id": "ch19p06", "audio": true, "sents": [{"it": "“Sono solo...", "zh": "我只是一朵花。", "t": [100, 1125]}, {"it": "sono solo...", "zh": "我只是一朵花。", "t": [1125, 2088]}, {"it": "sono solo...” rispose l’eco.", "zh": "我只是……回声答道。", "t": [2088, 3950]}]}, {"id": "ch19p07", "audio": true, "sents": [{"it": "“Che strano pianeta!” pensò allora.", "zh": "多么奇异的星球啊！", "t": [100, 2725]}, {"it": "“È tutto secco, appuntito e salato.", "zh": "干枯尖利，带着咸味。", "t": [2725, 5450]}, {"it": "E gli uomini sono privi di immaginazione.", "zh": "人们缺乏想象力。", "t": [5450, 8075]}, {"it": "Ripetono tutto quello che gli dici...", "zh": "他们复述你所说的每一句话。", "t": [8075, 10638]}, {"it": "Dove stavo io avevo una rosa: era sempre lei la prima a parlare...”", "zh": "我在那颗星球上有一朵玫瑰：她总是抢先开口……", "t": [10638, 14500]}]}]}, {"id": "ch20", "title_it": "XX", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"it": "Ma un bel giorno, dopo aver camminato a lungo sulla sabbia, sulle rocce, sulla neve, il piccolo principe si imbatté finalmente in una strada.", "zh": "终于，在沙石与雪地长途跋涉之后，小王子邂逅了一条道路。", "t": [100, 9075]}, {"it": "E le strade vanno tutte dove ci sono gli uomini.", "zh": "道路通向人烟之处。", "t": [9075, 11588]}]}, {"id": "ch20p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse.", "zh": "你好，他说。", "t": [100, 1225]}]}, {"id": "ch20p02", "audio": true, "sents": [{"it": "Era un giardino di rose.", "zh": "这是一座玫瑰盛开的花园。", "t": [100, 1463]}]}, {"id": "ch20p03", "audio": true, "sents": [{"it": "“Buongiorno,” dissero le rose.", "zh": "玫瑰们说：“你好。”", "t": [100, 1800]}]}, {"id": "ch20p04", "audio": true, "sents": [{"it": "Il piccolo principe le guardò.", "zh": "小王子凝视着她们。", "t": [100, 2062]}, {"it": "Assomigliavano tutte al suo fiore.", "zh": "她们都像他自己的那朵花。", "t": [2062, 3900]}]}, {"id": "ch20p05", "audio": true, "sents": [{"it": "“Chi siete?” domandò stupefatto.", "zh": "他惊讶地问道：“你们是谁？”", "t": [100, 2450]}]}, {"id": "ch20p06", "audio": true, "sents": [{"it": "“Siamo le rose,” dissero le rose.", "zh": "“我们是玫瑰花，”玫瑰们说。", "t": [100, 2000]}]}, {"id": "ch20p07", "audio": true, "sents": [{"it": "“Ah!” fece il piccolo principe...", "zh": "啊！小王子说……", "t": [100, 2162]}]}, {"id": "ch20p08", "audio": true, "sents": [{"it": "E si sentì molto infelice.", "zh": "他感到非常难过。", "t": [100, 1988]}, {"it": "La sua rosa gli aveva detto di essere l’unica in tutto l’universo.", "zh": "他的玫瑰曾告诉他，她是宇宙间独一无二的。", "t": [1988, 6112]}, {"it": "E invece ce n’erano cinquemila, tutte uguali, in un solo giardino!", "zh": "然而，在这座花园里，却有五千朵，全都一模一样！", "t": [6112, 10526]}]}, {"id": "ch20p09", "audio": true, "sents": [{"it": "“Se le vedesse, ci rimarrebbe malissimo...” pensò, “tossirebbe a più non posso e farebbe finta di morire per levarsi dall’imbarazzo.", "zh": "他心想：“要是她看见这群玫瑰花，她准会气得要命……为了保全面子，她肯定会装作咳嗽，假装快要死了，我得好好照顾她，不然她为了羞辱我，真会寻死的……”", "t": [100, 7975]}, {"it": "E sarei costretto a far finta di curarla perché altrimenti, per umiliare anche me, si lascerebbe davvero morire...”", "zh": "只得假装呵护她，否则，她为了羞辱我，真的会让自己死去……", "t": [7975, 14326]}]}, {"id": "ch20p10", "audio": true, "sents": [{"it": "Poi si disse ancora: “Credevo di possedere un fiore unico, e invece ho solo una rosa uguale a tante altre.", "zh": "我以为我拥有独一无二的花，却原来只是一朵与众相同的玫瑰。", "t": [100, 6788]}, {"it": "Lei e i miei tre vulcani che mi arrivano al ginocchio, di cui uno forse spento per sempre, non fanno di me un gran principe...”.", "zh": "我的三座火山，虽至膝高，其中一座或许永逝，亦不能使我成为一位伟大的王子……", "t": [6788, 14050]}, {"it": "E steso sull’erba pianse.", "zh": "他躺在草地上，泪水涟涟。", "t": [14050, 15700]}]}]}, {"id": "ch21", "title_it": "XXI", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": [{"it": "Fu allora che comparve la volpe:", "zh": "于是，狐狸出现了。", "t": [100, 1900]}]}, {"id": "ch21p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse la volpe.", "zh": "“你好，”狐狸说。", "t": [100, 1688]}]}, {"id": "ch21p02", "audio": true, "sents": [{"it": "“Buongiorno,” rispose gentilmente il piccolo principe, che si voltò ma non vide nulla.", "zh": "“你好，”小王子彬彬有礼地回答，他转过身，却看不见有什么东西。", "t": [100, 5074]}]}, {"id": "ch21p03", "audio": true, "sents": [{"it": "“Sono qui,” disse la voce, “sotto il melo...”", "zh": "“我在这里，”那声音说，“在苹果树下……”", "t": [100, 2612]}]}, {"id": "ch21p04", "audio": true, "sents": [{"it": "“Chi sei?” disse il piccolo principe.", "zh": "你是谁？小王子说。", "t": [100, 2838]}, {"it": "“Sei proprio graziosa...”", "zh": "你真美……", "t": [2838, 4274]}]}, {"id": "ch21p05", "audio": true, "sents": [{"it": "“Sono una volpe,” disse la volpe.", "zh": "“我是狐狸，”狐狸说。", "t": [100, 2000]}]}, {"id": "ch21p06", "audio": true, "sents": [{"it": "“Vieni a giocare con me,” le propose il piccolo principe, “sono tanto triste.”", "zh": "“来和我一起玩吧，”小王子提议道，“我非常难过。”", "t": [100, 4362]}]}, {"id": "ch21p07", "audio": true, "sents": [{"it": "“Non posso giocare con te,” disse la volpe.", "zh": "“我不能和你一起玩，”狐狸说。", "t": [100, 2625]}, {"it": "“Non sono addomesticata.”", "zh": "我不是被驯养的。", "t": [2625, 4200]}]}, {"id": "ch21p08", "audio": true, "sents": [{"it": "“Ah!", "zh": "啊！", "t": [100, 750]}, {"it": "Scusa,” fece il piccolo principe.", "zh": "“对不起，”小王子说。", "t": [750, 2750]}]}, {"id": "ch21p09", "audio": true, "sents": [{"it": "Ma, dopo averci pensato un po’, aggiunse:", "zh": "“不过，经过一番思考，他又补充道：”", "t": [100, 2987]}]}, {"id": "ch21p10", "audio": true, "sents": [{"it": "“Che cosa significa ‘addomesticare’?”", "zh": "“‘驯养’是什么意思？”", "t": [100, 2026]}]}, {"id": "ch21p11", "audio": true, "sents": [{"it": "“Tu non sei di qui,” disse la volpe, “che cosa stai cercando?”", "zh": "“你不是本地人，你在寻找什么？”", "t": [100, 3537]}]}, {"id": "ch21p12", "audio": true, "sents": [{"it": "“Cerco gli uomini,” disse il piccolo principe.", "zh": "我在寻找人类，小王子说。", "t": [100, 2862]}, {"it": "“Che cosa significa ‘addomesticare’?”", "zh": "“‘驯养’是什么意思？”", "t": [2862, 4788]}]}, {"id": "ch21p13", "audio": true, "sents": [{"it": "“Gli uomini,” disse la volpe, “hanno i fucili e cacciano.", "zh": "人们啊，狐狸说，他们有枪，他们打猎。", "t": [100, 3900]}, {"it": "È una gran seccatura!", "zh": "真讨厌！", "t": [3900, 5550]}, {"it": "Allevano anche le galline.", "zh": "人们也养鸡。", "t": [5550, 7225]}, {"it": "È l’unica cosa interessante.", "zh": "这是人唯一的好处。", "t": [7225, 9138]}, {"it": "Cerchi delle galline?”", "zh": "你在找母鸡吗？", "t": [9138, 10300]}]}, {"id": "ch21p14", "audio": true, "sents": [{"it": "“No,” disse il piccolo principe.", "zh": "“不，”小王子说。", "t": [100, 2175]}, {"it": "“Cerco degli amici.", "zh": "我在寻找朋友。", "t": [2175, 4088]}, {"it": "Che cosa significa ‘addomesticare’?”", "zh": "“驯养”是什么意思？", "t": [4088, 6013]}]}, {"id": "ch21p15", "audio": true, "sents": [{"it": "“È una cosa troppo dimenticata,” disse la volpe.", "zh": "这是一件被人遗忘干净了的事情，狐狸说。", "t": [100, 2900]}, {"it": "“Significa ‘creare dei legami’...”", "zh": "意味着“建立联系”……", "t": [2900, 4787]}]}, {"id": "ch21p16", "audio": true, "sents": [{"it": "“Creare dei legami?”", "zh": "建立联系？", "t": [100, 1263]}]}, {"id": "ch21p17", "audio": true, "sents": [{"it": "“Certo,” disse la volpe.", "zh": "“当然，”狐狸说。", "t": [100, 1838]}, {"it": "“Per me, ora tu sei solo un bambino uguale a centomila altri bambini.", "zh": "对你而言，我现在只是一个和成千上万个孩子一样的男孩。", "t": [1838, 6112]}, {"it": "E non ho bisogno di te.", "zh": "我不需要你。", "t": [6112, 7575]}, {"it": "Né tu hai bisogno di me.", "zh": "你也需要我。", "t": [7575, 9275]}, {"it": "Per te, sono soltanto una volpe uguale a centomila altre volpi.", "zh": "对你而言，我不过是一只与众不同的狐狸。", "t": [9275, 13450]}, {"it": "Ma se mi addomestichi, avremo bisogno l’uno dell’altra.", "zh": "若你驯养了我，我们便彼此需要。", "t": [13450, 16838]}, {"it": "Per me tu sarai unico al mondo.", "zh": "你将是我世界上独一无二的人。", "t": [16838, 18762]}, {"it": "Per te io sarò unica al mondo...”", "zh": "你将是我世间唯一的珍宝……", "t": [18762, 20424]}]}, {"id": "ch21p18", "audio": true, "sents": [{"it": "“Comincio a capire,” disse il piccolo principe.", "zh": "我开始明白了，小王子说。", "t": [100, 2775]}, {"it": "“C’è una rosa...", "zh": "那朵玫瑰……", "t": [2775, 3850]}, {"it": "credo che mi abbia addomesticato...”", "zh": "我深信，它已将我驯养。", "t": [3850, 5613]}]}, {"id": "ch21p19", "audio": true, "sents": [{"it": "“È possibile,” disse la volpe.", "zh": "“或许吧，”狐狸说。", "t": [100, 2100]}, {"it": "“Sulla Terra capita di tutto...”", "zh": "世间万物皆有可能……", "t": [2100, 3700]}]}, {"id": "ch21p20", "audio": true, "sents": [{"it": "“Oh!", "zh": "哦！", "t": [100, 812]}, {"it": "Non è sulla Terra,” disse il piccolo principe.", "zh": "“它不在地球上，”小王子说。", "t": [812, 3312]}]}, {"id": "ch21p21", "audio": true, "sents": [{"it": "La volpe parve molto incuriosita:", "zh": "狐狸显得非常好奇。", "t": [100, 2326]}]}, {"id": "ch21p22", "audio": true, "sents": [{"it": "“Su un altro pianeta?”", "zh": "在另一个星球上？", "t": [100, 1300]}]}, {"id": "ch21p23", "audio": true, "sents": [{"it": "“Sì.”", "zh": "是的。", "t": [100, 562]}]}, {"id": "ch21p24", "audio": true, "sents": [{"it": "“E ci sono cacciatori, su quel pianeta?”", "zh": "那颗星球上有猎人吗？", "t": [100, 2626]}]}, {"id": "ch21p25", "audio": true, "sents": [{"it": "“No.”", "zh": "没有。", "t": [100, 462]}]}, {"id": "ch21p26", "audio": true, "sents": [{"it": "“Ah, molto interessante!", "zh": "哦！真有趣！", "t": [100, 2162]}, {"it": "E galline?”", "zh": "你在找母鸡吗？", "t": [2162, 2887]}]}, {"id": "ch21p27", "audio": true, "sents": [{"it": "“No.”", "zh": "不。", "t": [100, 462]}]}, {"id": "ch21p28", "audio": true, "sents": [{"it": "“Nulla è perfetto,” sospirò la volpe.", "zh": "世间万物皆不完美，狐狸叹了口气。", "t": [100, 2387]}]}, {"id": "ch21p29", "audio": true, "sents": [{"it": "Ma la volpe tornò alla sua idea:", "zh": "狐狸又回到了自己的想法。", "t": [100, 2000]}]}, {"id": "ch21p30", "audio": true, "sents": [{"it": "“Ho una vita monotona.", "zh": "我的生活单调乏味。", "t": [100, 1600]}, {"it": "Io do la caccia alle galline e gli uomini danno la caccia a me.", "zh": "我捕猎母鸡，人类捕猎我。", "t": [1600, 5175]}, {"it": "Tutte le galline si assomigliano, e tutti gli uomini si assomigliano.", "zh": "所有的鸡都长得一样，所有的人也都长得一样。", "t": [5175, 9350]}, {"it": "Quindi mi annoio un po’.", "zh": "于是，我有些无聊。", "t": [9350, 10850]}, {"it": "Ma se tu mi addomestichi, la mia vita sarà come inondata di luce.", "zh": "若你驯养了我，我的生活将如春潮涌动，充满光明。", "t": [10850, 14975]}, {"it": "Conoscerò un rumore di passi diverso da tutti gli altri.", "zh": "我将能辨识出与众不同的脚步声。", "t": [14975, 18550]}, {"it": "Gli altri passi mi fanno fuggire sotto terra.", "zh": "那些脚步声让我躲进土里。", "t": [18550, 21238]}, {"it": "Il tuo mi chiamerà fuori dalla tana, come una musica.", "zh": "你的脚步声将像音乐般唤我出洞。", "t": [21238, 24600]}, {"it": "E poi guarda!", "zh": "看那边！", "t": [24600, 25788]}, {"it": "Li vedi laggiù, i campi di grano?", "zh": "你瞧，那不是麦田吗？", "t": [25788, 28150]}, {"it": "Io non mangio pane.", "zh": "我不吃面包。", "t": [28150, 29500]}, {"it": "Quindi per me il grano è inutile.", "zh": "麦子对我毫无意义。", "t": [29500, 31812]}, {"it": "I campi di grano non mi dicono niente.", "zh": "麦田对我毫无意义。", "t": [31812, 34138]}, {"it": "E questo è molto triste!", "zh": "这实在令人悲伤！", "t": [34138, 36000]}, {"it": "Ma tu hai capelli color dell’oro.", "zh": "你的头发是金色的。", "t": [36000, 38000]}, {"it": "E allora sarà bellissimo quando mi avrai addomesticato!", "zh": "那时，你驯养了我，一切都将变得美好。", "t": [38000, 41375]}, {"it": "Il grano, che è dorato, mi farà pensare a te.", "zh": "金黄的麦子会让我想起你。", "t": [41375, 44600]}, {"it": "E mi piacerà il rumore del vento nel grano...”", "zh": "风拂麦浪声，我会感到欢喜。", "t": [44600, 47000]}]}, {"id": "ch21p31", "audio": true, "sents": [{"it": "La volpe tacque e guardò a lungo il piccolo principe.", "zh": "狐狸沉默了，久久地凝视着小王子。", "t": [100, 3188]}]}, {"id": "ch21p32", "audio": true, "sents": [{"it": "“Per favore...", "zh": "请……驯养我吧！", "t": [100, 1075]}, {"it": "addomesticami!” disse.", "zh": "请……驯养我吧！", "t": [1075, 2925]}]}, {"id": "ch21p33", "audio": true, "sents": [{"it": "“Lo farei volentieri,” rispose il piccolo principe, “ma non ho molto tempo.", "zh": "我非常愿意，但我的时间不多。", "t": [100, 4525]}, {"it": "Ho amici da scoprire e molte cose da conoscere.”", "zh": "我还有朋友要结识，许多事物要了解。", "t": [4525, 7088]}]}, {"id": "ch21p34", "audio": true, "sents": [{"it": "“Conosciamo soltanto le cose che addomestichiamo,” disse la volpe.", "zh": "我们只了解我们驯养的东西，狐狸说。", "t": [100, 3800]}, {"it": "“Gli uomini non hanno più tempo per conoscere nulla.", "zh": "人们不再有时间去了解任何事物。", "t": [3800, 6750]}, {"it": "Comprano le cose già fatte nei negozi.", "zh": "他们在商店里购买现成的东西。", "t": [6750, 9300]}, {"it": "Ma siccome non esistono negozi che vendono amici, gli uomini non hanno più amici.", "zh": "然而，既然没有商店出售朋友，人们便不再拥有朋友。", "t": [9300, 14950]}, {"it": "Se vuoi un amico, addomesticami!”", "zh": "若你想要朋友，就驯养我吧！", "t": [14950, 17387]}]}, {"id": "ch21p35", "audio": true, "sents": [{"it": "“Come si fa?” disse il piccolo principe.", "zh": "小王子问道：“怎么做？”", "t": [100, 2637]}]}, {"id": "ch21p36", "audio": true, "sents": [{"it": "“Ci vuole molta pazienza,” rispose la volpe.", "zh": "需要极大的耐心，狐狸回答道。", "t": [100, 2775]}, {"it": "“Prima dovrai sederti un po’ lontano da me, così, nell’erba.", "zh": "你先得坐远一点，在我这边草地上。", "t": [2775, 6738]}, {"it": "Io ti guarderò con la coda dell’occhio e tu non dirai niente.", "zh": "我斜眼打量着你，你却一言不发。", "t": [6738, 10525]}, {"it": "Il linguaggio è fonte di malintesi.", "zh": "语言是误会的根源。", "t": [10525, 12825]}, {"it": "Ma ogni giorno potrai sederti un po’ più vicino...”", "zh": "你每天可以坐得稍近一点……", "t": [12825, 15537]}]}, {"id": "ch21p37", "audio": true, "sents": [{"it": "L’indomani il piccolo principe tornò.", "zh": "小王子次日又来了。", "t": [100, 2312]}]}, {"id": "ch21p38", "audio": true, "sents": [{"it": "“Sarebbe stato meglio se fossi venuto alla stessa ora,” disse la volpe.", "zh": "“要是你每天都能按时来，”狐狸说。", "t": [100, 3875]}, {"it": "“Se per esempio verrai alle quattro del pomeriggio, già dalle tre io comincerò a essere felice.", "zh": "要是你下午四点钟来，那么从三点钟起，我就开始感到幸福了。", "t": [3875, 9438]}, {"it": "Più il tempo passerà e più mi sentirò felice.", "zh": "时间越久，我越感到快乐。", "t": [9438, 12300]}, {"it": "Finché alle quattro sarò tutta agitata e in apprensione: scoprirò il valore della felicità!", "zh": "直到四点钟，我才会心神不宁，意识到幸福的珍贵。", "t": [12300, 17762]}, {"it": "Ma se vieni quando capita, non saprò mai a che ora vestirmi il cuore...", "zh": "若你随意而来，我便不知何时装扮我的心灵。", "t": [17762, 21825]}, {"it": "I riti sono importanti.”", "zh": "仪式很重要。", "t": [21825, 23400]}]}, {"id": "ch21p39", "audio": true, "sents": [{"it": "“Che cos’è un rito?” disse il piccolo principe.", "zh": "“什么是仪式？”小王子问道。", "t": [100, 3188]}]}, {"id": "ch21p40", "audio": true, "sents": [{"it": "“Anche questa è una cosa troppo dimenticata,” disse la volpe.", "zh": "这也是一件被人遗忘的事了，狐狸说。", "t": [100, 3662]}, {"it": "“È ciò che rende un giorno diverso dagli altri giorni, un’ora diversa dalle altre ore.", "zh": "这是使一日不同于他日，一小时不同于其他小时的东西。", "t": [3662, 8762]}, {"it": "I miei cacciatori, per esempio, hanno un rito.", "zh": "我的猎人，比如，有仪式。", "t": [8762, 12188]}, {"it": "Il giovedì ballano con le ragazze del villaggio.", "zh": "星期四，他们与村里的姑娘们跳舞。", "t": [12188, 14888]}, {"it": "Allora il giovedì è una giornata meravigliosa!", "zh": "于是，星期四是个美好的日子。", "t": [14888, 17662]}, {"it": "E io vado a fare una passeggiata fino alla vigna.", "zh": "我将去葡萄园散步。", "t": [17662, 20362]}, {"it": "Se i cacciatori ballassero quando capita, i giorni sarebbero tutti uguali, e non avrei mai vacanza.”", "zh": "若猎人吹起号角，日子便都一样，我便永远没有假期。", "t": [20362, 26224]}]}, {"id": "ch21p41", "audio": true, "sents": [{"it": "Così il piccolo principe addomesticò la volpe.", "zh": "小王子驯服了狐狸。", "t": [100, 3238]}, {"it": "E quando si avvicinò il momento della partenza:", "zh": "当离别时刻临近：", "t": [3238, 5813]}]}, {"id": "ch21p42", "audio": true, "sents": [{"it": "“Ah!” disse la volpe...", "zh": "啊！\"狐狸说。", "t": [100, 2012]}, {"it": "“Piangerò.”", "zh": "我将哭泣。", "t": [2012, 2637]}]}, {"id": "ch21p43", "audio": true, "sents": [{"it": "“È colpa tua,” disse il piccolo principe, “io non volevo farti soffrire, ma tu mi hai chiesto di addomesticarti...”", "zh": "是你的错，小王子说，“我不想让你难过，但你却要求我驯服你……”", "t": [100, 6512]}]}, {"id": "ch21p44", "audio": true, "sents": [{"it": "“Certo,” disse la volpe.", "zh": "“当然，”狐狸说。", "t": [100, 1575]}]}, {"id": "ch21p45", "audio": true, "sents": [{"it": "“Però piangerai!” disse il piccolo principe.", "zh": "但你会哭的！小王子说。", "t": [100, 3213]}]}, {"id": "ch21p46", "audio": true, "sents": [{"it": "“Certo,” disse la volpe.", "zh": "“当然，”狐狸说。", "t": [100, 1575]}]}, {"id": "ch21p47", "audio": true, "sents": [{"it": "“Allora non ci guadagni niente!”", "zh": "那你也一无所获。", "t": [100, 1787]}]}, {"id": "ch21p48", "audio": true, "sents": [{"it": "“Ci guadagno,” disse la volpe, “a causa del colore del grano.”", "zh": "我得到了麦子的颜色。", "t": [100, 3588]}]}, {"id": "ch21p49", "audio": true, "sents": [{"it": "Poi aggiunse:", "zh": "然后他又说：", "t": [100, 1026]}]}, {"id": "ch21p50", "audio": true, "sents": [{"it": "“Vai a rivedere le rose.", "zh": "去再见那朵玫瑰。", "t": [100, 1650]}, {"it": "Capirai che la tua è unica al mondo.", "zh": "你的玫瑰是世界上独一无二的。", "t": [1650, 3850]}, {"it": "Quando tornerai a salutarmi, ti regalerò un segreto.”", "zh": "当我再次来向你道别时，我会送你一个秘密。", "t": [3850, 7062]}]}, {"id": "ch21p51", "audio": true, "sents": [{"it": "Il piccolo principe andò a rivedere le rose:", "zh": "小王子再次去探望玫瑰们。", "t": [100, 2463]}]}, {"id": "ch21p52", "audio": true, "sents": [{"it": "“Non assomigliate affatto alla mia rosa, non siete ancora niente,” disse loro.", "zh": "你们一点也不像我的玫瑰，你们还无足轻重。", "t": [100, 4712]}, {"it": "“Nessuno vi ha addomesticate e voi non avete addomesticato nessuno.", "zh": "无人曾驯养你们，你们亦未驯养任何人。", "t": [4712, 8725]}, {"it": "Siete com’era la mia volpe.", "zh": "你们就像我的狐狸。", "t": [8725, 10462]}, {"it": "Era solo una volpe uguale a centomila altre.", "zh": "这只狐狸与成千上万的狐狸并无二致。", "t": [10462, 13350]}, {"it": "Ma ho fatto di lei la mia amica e ora è unica al mondo.”", "zh": "我已将她变成我的朋友，如今她是世间独一无二的存在。", "t": [13350, 16625]}]}, {"id": "ch21p53", "audio": true, "sents": [{"it": "Le rose erano molto imbarazzate.", "zh": "玫瑰们感到十分尴尬。", "t": [100, 2162]}]}, {"id": "ch21p54", "audio": true, "sents": [{"it": "“Siete belle, ma siete vuote,” disse ancora.", "zh": "你们很美，但你们是空洞的。", "t": [100, 3188]}, {"it": "“Non si può morire per voi.", "zh": "你们不会为我而死。", "t": [3188, 4938]}, {"it": "Certo, un passante qualsiasi penserebbe che la mia rosa vi assomigli.", "zh": "当然，任何过路人都会认为我的玫瑰与你们相似。", "t": [4938, 9438]}, {"it": "Ma lei da sola è più importante di tutte voi, perché è quella che ho innaffiato.", "zh": "她独自一人就比你们都重要，因为是我浇灌的。", "t": [9438, 14450]}, {"it": "Perché l’ho messa sotto la campana di vetro.", "zh": "因为我想让她在玻璃罩下永存。", "t": [14450, 16962]}, {"it": "Perché l’ho protetta con il paravento.", "zh": "我以屏风庇护她。", "t": [16962, 19225]}, {"it": "Perché ho ucciso i bruchi (tranne due o tre per le farfalle).", "zh": "因为我杀死了毛虫（除了两三条变成蝴蝶的）。", "t": [19225, 23050]}, {"it": "Perché l’ho ascoltata lamentarsi, o vantarsi o a volte anche tacere.", "zh": "因为我曾聆听她的抱怨，或她的自诩，有时甚至默默不语。", "t": [23050, 27312]}, {"it": "Perché è la mia rosa.”", "zh": "因为那是我的玫瑰。", "t": [27312, 28512]}]}, {"id": "ch21p55", "audio": true, "sents": [{"it": "E tornò dalla volpe:", "zh": "狐狸又转向狐狸：", "t": [100, 1325]}]}, {"id": "ch21p56", "audio": true, "sents": [{"it": "“Addio...” disse.", "zh": "再见了……他说。", "t": [100, 1550]}]}, {"id": "ch21p57", "audio": true, "sents": [{"it": "“Addio,” disse la volpe.", "zh": "再见了，狐狸说。", "t": [100, 1788]}, {"it": "“Ecco il mio segreto.", "zh": "这是我的秘密。", "t": [1788, 3175]}, {"it": "È molto semplice: si vede solo con il cuore.", "zh": "用心去看，才能看得清。", "t": [3175, 6175]}, {"it": "L’essenziale è invisibile agli occhi.”", "zh": "肉眼难见其本质。", "t": [6175, 8250]}]}, {"id": "ch21p58", "audio": true, "sents": [{"it": "“L’essenziale è invisibile agli occhi,” ripeté il piccolo principe, per tenerlo a mente.", "zh": "“本质对眼睛来说是看不见的，”小王子反复念诵，以牢记于心。", "t": [100, 4912]}]}, {"id": "ch21p59", "audio": true, "sents": [{"it": "“Il tempo che hai perso per la tua rosa è ciò che fa la tua rosa tanto importante.”", "zh": "你为你的玫瑰所浪费的时间，让她变得如此重要。", "t": [100, 4763]}]}, {"id": "ch21p60", "audio": true, "sents": [{"it": "“Il tempo che ho perso per la mia rosa...” ripeté il piccolo principe, per tenerlo a mente.", "zh": "我为了我的玫瑰所浪费的时间……小王子反复念诵，以便牢记于心。", "t": [100, 5162]}]}, {"id": "ch21p61", "audio": true, "sents": [{"it": "“Gli uomini hanno dimenticato questa verità,” disse la volpe.", "zh": "人们已经忘记了这条真理，狐狸说。", "t": [100, 3625]}, {"it": "“Ma tu non devi dimenticarla.", "zh": "你切莫忘记它。", "t": [3625, 5538]}, {"it": "Diventi responsabile per sempre di ciò che hai addomesticato.", "zh": "你将永远对你所驯养之物负责。", "t": [5538, 9112]}, {"it": "Tu sei responsabile della tua rosa...”", "zh": "你对你那朵玫瑰负有责任……", "t": [9112, 11275]}]}, {"id": "ch21p62", "audio": true, "sents": [{"it": "“Sono responsabile della mia rosa...” ripeté il piccolo principe, per tenerlo a mente.", "zh": "小王子反复念诵：“我对我的玫瑰负有责任……”以便牢记于心。", "t": [100, 5100]}]}]}, {"id": "ch22", "title_it": "XXII", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe.", "zh": "你好，小王子说。", "t": [100, 2226]}]}, {"id": "ch22p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse l’addetto agli scambi.", "zh": "你好，扳道工说。", "t": [100, 2387]}]}, {"id": "ch22p02", "audio": true, "sents": [{"it": "“Che cosa fai qui?” disse il piccolo principe.", "zh": "你在做什么呢？小王子说。", "t": [100, 2800]}]}, {"id": "ch22p03", "audio": true, "sents": [{"it": "“Smisto i viaggiatori, a migliaia,” disse l’addetto agli scambi.", "zh": "“旅客们，分成了千千万万，”扳道工说。", "t": [100, 4288]}, {"it": "“Mando via i treni che li portano lontano, ora verso destra ora verso sinistra.”", "zh": "我调度着载他们远行的火车，时而向右，时而向左。", "t": [4288, 9087]}]}, {"id": "ch22p04", "audio": true, "sents": [{"it": "E un rapido tutto illuminato passò rombante come un tuono e fece tremare la cabina dell’addetto agli scambi.", "zh": "一列灯火通明的火车轰鸣着如雷贯耳，震得调度室摇曳不定。", "t": [100, 6387]}]}, {"id": "ch22p05", "audio": true, "sents": [{"it": "“Vanno proprio di fretta,” disse il piccolo principe.", "zh": "他们匆匆忙忙地，小王子说。", "t": [100, 3075]}, {"it": "“Che cosa cercano?”", "zh": "他们在寻找什么？", "t": [3075, 4124]}]}, {"id": "ch22p06", "audio": true, "sents": [{"it": "“Neanche l’uomo della locomotiva lo sa,” disse l’ad­detto agli scambi.", "zh": "连火车头上的司机也不知道他们要寻找什么。", "t": [100, 3762]}]}, {"id": "ch22p07", "audio": true, "sents": [{"it": "E in senso inverso arrivò rombando un secondo rapido illuminato.", "zh": "另一列灯火通明的快车轰鸣着逆向驶来。", "t": [100, 4025]}]}, {"id": "ch22p08", "audio": true, "sents": [{"it": "“Sono già di ritorno?” domandò il piccolo principe...", "zh": "小王子问道：“他们已经回来了吗？”", "t": [100, 3238]}]}, {"id": "ch22p09", "audio": true, "sents": [{"it": "“Non sono gli stessi,” disse l’addetto agli scambi.", "zh": "“他们不是同一拨人，”扳道工说。", "t": [100, 3125]}, {"it": "“Questo è uno scambio.”", "zh": "这是交换。", "t": [3125, 4400]}]}, {"id": "ch22p10", "audio": true, "sents": [{"it": "“Non erano contenti, dove stavano?”", "zh": "他们不满足，他们在哪里？", "t": [100, 2387]}]}, {"id": "ch22p11", "audio": true, "sents": [{"it": "“Nessuno è mai contento dove sta,” disse l’addetto allo scambio.", "zh": "他们总是对现状不满足。", "t": [100, 3750]}]}, {"id": "ch22p12", "audio": true, "sents": [{"it": "E come un tuono rombò un terzo rapido illuminato.", "zh": "轰鸣一声，第三列快车亮如白昼。", "t": [100, 3337]}]}, {"id": "ch22p13", "audio": true, "sents": [{"it": "“Inseguono i primi viaggiatori?” domandò il piccolo principe.", "zh": "他们在追赶第一批旅客吗？小王子问道。", "t": [100, 3774]}]}, {"id": "ch22p14", "audio": true, "sents": [{"it": "“Non inseguono un bel niente,” disse l’addetto allo scambio.", "zh": "他们从不追逐虚无缥缈之物，扳道工说。", "t": [100, 3762]}, {"it": "“Là dentro dormono, oppure sbadigliano.", "zh": "他们在车厢里打盹儿，或者打着哈欠。", "t": [3762, 6475]}, {"it": "Solo i bambini se ne stanno con il naso incollato al finestrino.”", "zh": "孩子们总是把鼻子贴在窗玻璃上。", "t": [6475, 10200]}]}, {"id": "ch22p15", "audio": true, "sents": [{"it": "“Solo i bambini sanno quello che cercano,” fece il piccolo principe.", "zh": "只有孩子才知道他们要寻找什么。", "t": [100, 3975]}, {"it": "“Perdono tempo per una bambola di pezza, che allora diventa importantissima, e se qualcuno gliela porta via piangono...”", "zh": "他们把时间花在布娃娃身上，那布娃娃于是变得极为重要，若有人夺走它，他们就哭泣……", "t": [3975, 10524]}]}, {"id": "ch22p16", "audio": true, "sents": [{"it": "“Sono fortunati,” disse l’addetto allo scambio.", "zh": "他们是幸运的，扳道工说。", "t": [100, 2725]}]}]}, {"id": "ch23", "title_it": "XXIII", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"it": "“Buongiorno,” disse il piccolo principe.", "zh": "你好，小王子说。", "t": [100, 2226]}]}, {"id": "ch23p01", "audio": true, "sents": [{"it": "“Buongiorno,” disse il negoziante.", "zh": "“你好，”商人说。", "t": [100, 2063]}]}, {"id": "ch23p02", "audio": true, "sents": [{"it": "Vendeva pillole speciali che placano la sete.", "zh": "贩卖着解渴的特殊药丸。", "t": [100, 2888]}, {"it": "Ne prendi una alla settimana e non provi più il desiderio di bere.", "zh": "每周只需服用一粒，便不再渴望饮水。", "t": [2888, 6725]}]}, {"id": "ch23p03", "audio": true, "sents": [{"it": "“Perché vendi queste pillole?” disse il piccolo principe.", "zh": "“你为何卖这些药丸？”小王子问道。", "t": [100, 3737]}]}, {"id": "ch23p04", "audio": true, "sents": [{"it": "“È un bel risparmio di tempo,” disse il negoziante.", "zh": "“这节省了不少时间呢，”商人说。", "t": [100, 3200]}, {"it": "“Gli esperti hanno calcolato che si guadagnano cinquantatré minuti alla settimana.”", "zh": "专家们算出，每周能赢得五十三分钟。", "t": [3200, 7563]}]}, {"id": "ch23p05", "audio": true, "sents": [{"it": "“E cosa si fa di quei cinquantatré minuti?”", "zh": "这节省下来的五十三分钟，又用来做什么呢？", "t": [100, 2437]}]}, {"id": "ch23p06", "audio": true, "sents": [{"it": "“Quello che si vuole...”", "zh": "那便是他想要的……", "t": [100, 1100]}]}, {"id": "ch23p07", "audio": true, "sents": [{"it": "“Se avessi cinquantatré minuti da spendere,” si disse il piccolo principe, “me ne andrei lentamente verso una fontana...”", "zh": "“若我有五十三分钟可以消磨，”小王子自言自语，“我会缓缓走向那泉边……”", "t": [100, 6576]}]}]}, {"id": "ch24", "title_it": "XXIV", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": [{"it": "Erano passati otto giorni da quando avevo avuto il guasto nel deserto, e avevo ascoltato la storia del negoziante bevendo la mia ultima goccia d’acqua:", "zh": "八天前飞机在沙漠中出了故障，我听完了商人的故事，喝完了最后一滴水。", "t": [100, 8326]}]}, {"id": "ch24p01", "audio": true, "sents": [{"it": "“Ah!” dissi al piccolo principe, “i tuoi ricordi sono proprio belli, ma non ho ancora riparato l’aereo, non ho più niente da bere, e sarei ben felice anch’io di poter camminare pian piano verso una fontana!”", "zh": "“啊！小王子，你的回忆真美，可我还没修好飞机，水也喝光了，若能悠然漫步至泉边，我也会感到无比幸福！”", "t": [100, 12437]}]}, {"id": "ch24p02", "audio": true, "sents": [{"it": "“La mia amica volpe...” mi disse.", "zh": "我的朋友狐狸说……", "t": [100, 2162]}]}, {"id": "ch24p03", "audio": true, "sents": [{"it": "“Caro il mio ometto, lascia stare la tua volpe!”", "zh": "亲爱的孩子，别再提你的狐狸了！", "t": [100, 2825]}]}, {"id": "ch24p04", "audio": true, "sents": [{"it": "“Perché?”", "zh": "“为什么？”", "t": [100, 588]}]}, {"id": "ch24p05", "audio": true, "sents": [{"it": "“Perché qui moriremo di sete...”", "zh": "我们在这里会因干渴而死……", "t": [100, 1738]}]}, {"id": "ch24p06", "audio": true, "sents": [{"it": "Non capì il mio ragionamento e mi rispose:", "zh": "他不理解我的话，便回答道：", "t": [100, 2437]}]}, {"id": "ch24p07", "audio": true, "sents": [{"it": "“È bello avere avuto un amico, anche se devi morire di sete.", "zh": "拥有一个朋友，纵使你需在干渴中死去，也是美好的。", "t": [100, 3775]}, {"it": "Io sono molto contento di avere avuto la mia amica volpe...”", "zh": "我很高兴能拥有我的狐狸朋友……", "t": [3775, 6863]}]}, {"id": "ch24p08", "audio": true, "sents": [{"it": "“Non si rende conto del pericolo,” pensai.", "zh": "他并未意识到危险。", "t": [100, 2700]}, {"it": "“Non ha mai né fame né sete.", "zh": "他从未尝过饥饿与干渴。", "t": [2700, 4462]}, {"it": "Gli basta un po’ di sole...”", "zh": "只需一点阳光。", "t": [4462, 5924]}]}, {"id": "ch24p09", "audio": true, "sents": [{"it": "Ma lui mi guardò e rispose al mio pensiero:", "zh": "他望着我，回应了我的所思。", "t": [100, 2450]}]}, {"id": "ch24p10", "audio": true, "sents": [{"it": "“Anch’io ho sete...", "zh": "我也渴……", "t": [100, 1450]}, {"it": "cerchiamo un pozzo...”", "zh": "我们去找一口井吧……", "t": [1450, 2512]}]}, {"id": "ch24p11", "audio": true, "sents": [{"it": "Ebbi un gesto di stanchezza: è assurdo cercare a caso un pozzo nell’immensità del deserto.", "zh": "在沙漠的浩瀚中随意寻找一口井，岂非荒谬至极？", "t": [100, 5825]}, {"it": "Tuttavia ci mettemmo in cammino.", "zh": "然而，我们还是出发了。", "t": [5825, 7612]}]}, {"id": "ch24p12", "audio": true, "sents": [{"it": "Dopo che avemmo camminato per ore, in silenzio, scese la notte, e cominciarono ad accendersi le stelle.", "zh": "夜幕降临，星辰初上。", "t": [100, 6762]}, {"it": "Le scorgevo come in sogno, poiché a causa della sete avevo un po’ di febbre.", "zh": "如同梦境般，因干渴而发烧。", "t": [6762, 11400]}, {"it": "Nella memoria mi danzavano le parole del piccolo principe:", "zh": "小王子的言语在我记忆中翩翩起舞。", "t": [11400, 14575]}]}, {"id": "ch24p13", "audio": true, "sents": [{"it": "“Allora anche tu hai sete?” gli domandai.", "zh": "你也渴了吗？", "t": [100, 2612]}]}, {"id": "ch24p14", "audio": true, "sents": [{"it": "Ma non rispose.", "zh": "他没有回答。", "t": [100, 1412]}, {"it": "Mi disse soltanto:", "zh": "他只说了：", "t": [1412, 2724]}]}, {"id": "ch24p15", "audio": true, "sents": [{"it": "“L’acqua può essere buona anche per il cuore...”", "zh": "水对心也有益……", "t": [100, 2188]}]}, {"id": "ch24p16", "audio": true, "sents": [{"it": "Non capii quella risposta, ma tacqui...", "zh": "我不懂那回答，却缄口不言……", "t": [100, 2862]}, {"it": "Sapevo che non bisognava fargli domande.", "zh": "我知道不该问他。", "t": [2862, 5000]}]}, {"id": "ch24p17", "audio": true, "sents": [{"it": "Era stanco.", "zh": "他疲惫不堪。", "t": [100, 1200]}, {"it": "Si sedette.", "zh": "他坐下了。", "t": [1200, 2350]}, {"it": "Mi sedetti accanto a lui.", "zh": "我坐在他身边。", "t": [2350, 4000]}, {"it": "Poi, dopo un momento di silenzio, disse ancora:", "zh": "然后，沉默片刻，他又说道：", "t": [4000, 7224]}]}, {"id": "ch24p18", "audio": true, "sents": [{"it": "“Le stelle sono belle grazie a un fiore che non vediamo...”", "zh": "星星之所以美丽，是因为其中藏有一朵我们看不见的花。", "t": [100, 3225]}]}, {"id": "ch24p19", "audio": true, "sents": [{"it": "Risposi “certo” e guardai, senza parlare, le pieghe della sabbia sotto la luna.", "zh": "我默默地看着月光下沙丘的皱褶。", "t": [100, 5212]}]}, {"id": "ch24p20", "audio": true, "sents": [{"it": "“Il deserto è bello...” aggiunse.", "zh": "沙漠真美……他补充道。", "t": [100, 2324]}]}, {"id": "ch24p21", "audio": true, "sents": [{"it": "Ed era vero.", "zh": "这确实是。", "t": [100, 1062]}, {"it": "Ho sempre amato il deserto.", "zh": "沙漠，我始终钟爱。", "t": [1062, 2875]}, {"it": "Ti siedi su una duna di sabbia.", "zh": "你坐在沙丘之上。", "t": [2875, 4975]}, {"it": "Non vedi niente.", "zh": "你什么也没看见。", "t": [4975, 6238]}, {"it": "Non senti niente.", "zh": "你什么也没听见。", "t": [6238, 7650]}, {"it": "E tuttavia qualcosa brilla in silenzio...", "zh": "然而，有什么东西在默默闪烁……", "t": [7650, 9912]}]}, {"id": "ch24p22", "audio": true, "sents": [{"it": "“Ciò che fa bello il deserto,” disse il piccolo principe, “è che da qualche parte nasconde un pozzo...”", "zh": "沙漠之所以美丽，是因为它某处藏有一口井……", "t": [100, 5500]}]}, {"id": "ch24p23", "audio": true, "sents": [{"it": "E con grande stupore capii d’un tratto il misterioso brillio della sabbia.", "zh": "我忽然惊觉，沙丘中那神秘的闪光原来是如此奇妙。", "t": [100, 4612]}, {"it": "Da bambino abitavo in una vecchia casa che la leggenda diceva celasse un tesoro.", "zh": "我童年时住在一座传说中藏有宝藏的古老房子里。", "t": [4612, 9388]}, {"it": "Ovviamente nessuno è mai riuscito a trovarlo, né forse l’ha mai cercato.", "zh": "显然，没有人成功找到过它，也许甚至没有人真正寻找过。", "t": [9388, 13938]}, {"it": "Ma esso rendeva quella casa come incantata.", "zh": "那座房子仿佛被施了魔法。", "t": [13938, 16712]}, {"it": "Il cuore della mia casa nascondeva un segreto...", "zh": "我家的心脏隐藏着一个秘密……", "t": [16712, 19313]}]}, {"id": "ch24p24", "audio": true, "sents": [{"it": "“Sì,” dissi al piccolo principe, “che si tratti della casa, delle stelle o del deserto, quel che fa la loro bellezza è invisibile!”", "zh": "是的，我对小王子说，“无论是房子、星星还是沙漠，赋予它们美丽的是肉眼无法看见的东西！”", "t": [100, 8200]}]}, {"id": "ch24p25", "audio": true, "sents": [{"it": "“Mi fa piacere,” disse, “che tu sia d’accordo con la mia volpe.”", "zh": "我很高兴，你同意我的狐狸的看法。", "t": [100, 3574]}]}, {"id": "ch24p26", "audio": true, "sents": [{"it": "Il piccolo principe si stava addormentando, allora lo presi in braccio e mi rimisi in cammino.", "zh": "小王子渐渐入睡，我便将他抱在怀里，继续前行。", "t": [100, 5775]}, {"it": "Provavo una grande emozione.", "zh": "心中涌起一股强烈的情感。", "t": [5775, 7712]}, {"it": "Mi sembrava di reggere un fragile tesoro.", "zh": "我仿佛抱着一件脆弱的珍宝。", "t": [7712, 10150]}, {"it": "Mi sembrava addirittura che non ci fosse nulla di più fragile sulla Terra.", "zh": "地球上似乎再没有比这更脆弱的东西了。", "t": [10150, 14475]}, {"it": "Alla luce della luna, guardavo quella fronte pallida, quegli occhi chiusi, quelle ciocche di capelli che tremavano al vento, e mi dicevo: “Io vedo soltanto la scorza.", "zh": "在月光下，我凝视着他那苍白的额头、紧闭的双眼、随风轻轻颤动的发丝，心中想道：“我只看到了外壳。”", "t": [14475, 24375]}, {"it": "Ciò che è davvero importante è invisibile...”.", "zh": "那至关重要的，是肉眼无法看见的……", "t": [24375, 26600]}]}, {"id": "ch24p27", "audio": true, "sents": [{"it": "Mentre le sue labbra socchiuse accennavano un mezzo sorriso, mi dissi ancora: “La cosa che più mi commuove di questo piccolo principe addormentato è la sua fedeltà a un fiore, è l’immagine di una rosa che brilla dentro di lui come la fiamma di una lampada, anche quando dorme...”.", "zh": "那沉睡的小王子微微一笑，我再次说道：“最令我感动的，是他对自己那朵花的忠诚，是那朵玫瑰在他心中如灯焰般闪耀，即便在梦乡……”", "t": [100, 16138]}, {"it": "E capii che era ancora più fragile.", "zh": "我意识到他更加脆弱。", "t": [16138, 18450]}, {"it": "Bisogna proteggere le lampade: un soffio di vento basta a spegnerle...", "zh": "灯是需要我们小心保护的，一丝风就能将其吹灭……", "t": [18450, 22650]}]}, {"id": "ch24p28", "audio": true, "sents": [{"it": "E, camminando così, all’alba trovai il pozzo.", "zh": "在行走中，破晓时分我找到了井。", "t": [100, 3374]}]}]}, {"id": "ch25", "title_it": "XXV", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": [{"it": "“Gli uomini,” disse il piccolo principe, “salgono sui treni ma non sanno più cosa cercano.", "zh": "人们登上火车，却不知在寻找什么。", "t": [100, 5538]}, {"it": "Allora si agitano e girano a vuoto...”", "zh": "于是他们焦躁不安，空转着圈子……", "t": [5538, 7776]}]}, {"id": "ch25p01", "audio": true, "sents": [{"it": "Quindi aggiunse:", "zh": "于是他又说：", "t": [100, 1138]}]}, {"id": "ch25p02", "audio": true, "sents": [{"it": "“E tutto questo non serve a niente...”", "zh": "这一切都毫无意义……", "t": [100, 2063]}]}, {"id": "ch25p03", "audio": true, "sents": [{"it": "Il pozzo cui eravamo giunti era diverso dai soliti pozzi del Sahara.", "zh": "这口井与撒哈拉沙漠的井大不相同。", "t": [100, 4188]}, {"it": "I pozzi del Sahara sono semplici buche scavate nella sabbia.", "zh": "撒哈拉沙漠的井只是沙中挖出的洞。", "t": [4188, 8012]}, {"it": "Questo era simile al pozzo di un villaggio.", "zh": "这口井仿佛村中的井。", "t": [8012, 10500]}, {"it": "Ma non c’era alcun villaggio, e credevo di sognare.", "zh": "然而这里并无村落，我仿佛置身梦境。", "t": [10500, 13576]}]}, {"id": "ch25p04", "audio": true, "sents": [{"it": "“È strano,” dissi al piccolo principe, “è tutto pronto: la carrucola, il secchio e la corda...”", "zh": "“这真奇怪，”我对小王子说，“一切准备就绪：辘轳、水桶和绳子……”", "t": [100, 6063]}]}, {"id": "ch25p05", "audio": true, "sents": [{"it": "Lui rise, toccò la corda, fece ruotare la carrucola.", "zh": "他提起绳子，转动着辘轳。", "t": [100, 3513]}]}, {"id": "ch25p06", "audio": true, "sents": [{"it": "E la carrucola gemette come geme una vecchia banderuola dopo che il vento ha dormito a lungo.", "zh": "辘轳如同老风信鸡在长睡的风中低鸣。", "t": [100, 5137]}]}, {"id": "ch25p07", "audio": true, "sents": [{"it": "“Lo senti?” disse il piccolo principe, “svegliamo il pozzo e lui canta...”", "zh": "“你听，”小王子说，“我们唤醒了这口井，它正在歌唱……”", "t": [100, 4650]}]}, {"id": "ch25p08", "audio": true, "sents": [{"it": "Non volevo che si stancasse:", "zh": "不愿让他劳累。", "t": [100, 1750]}]}, {"id": "ch25p09", "audio": true, "sents": [{"it": "“Lascia fare a me,” gli dissi, “per te è troppo pesante.”", "zh": "让我来吧，对你来说太沉重了。", "t": [100, 3350]}]}, {"id": "ch25p10", "audio": true, "sents": [{"it": "Tirai su adagio il secchio fino al bordo.", "zh": "缓缓提起水桶至井沿。", "t": [100, 2538]}, {"it": "Lo posai bene in equilibrio.", "zh": "我把它放得稳稳当当。", "t": [2538, 4450]}, {"it": "Nelle mie orecchie durava il canto della puleggia e, nell’acqua che ancora tremava, vedevo tremare il sole.", "zh": "辘轳之歌在我耳畔回响，井水中那颤动的阳光也随之摇曳。", "t": [4450, 10524]}]}, {"id": "ch25p11", "audio": true, "sents": [{"it": "“Ho sete di quell’acqua,” disse il piccolo principe, “dammi da bere...”", "zh": "“我渴望的就是这样的水，”小王子说，“让我喝上几口……”", "t": [100, 3800]}]}, {"id": "ch25p12", "audio": true, "sents": [{"it": "E capii che cosa aveva cercato!", "zh": "我明白了他在寻找什么。", "t": [100, 2050]}]}, {"id": "ch25p13", "audio": true, "sents": [{"it": "Gli sollevai il secchio fino alle labbra.", "zh": "我举桶至他唇边。", "t": [100, 2488]}, {"it": "Bevve, con gli occhi chiusi.", "zh": "闭目啜饮。", "t": [2488, 4538]}, {"it": "Era dolce come una festa.", "zh": "甜得像节日。", "t": [4538, 6250]}, {"it": "Quell’acqua era ben altro che un alimento.", "zh": "那水远非单纯的饮品。", "t": [6250, 8588]}, {"it": "Era nata dalla camminata sotto le stelle, dal canto della carrucola, dallo sforzo delle mie braccia.", "zh": "它诞生于星光下的跋涉，在辘轳的歌声中，在我双臂的努力下。", "t": [8588, 14788]}, {"it": "Era buona per il cuore, come un dono.", "zh": "它像礼物一样温暖心灵。", "t": [14788, 17200]}, {"it": "Quando ero piccolo, erano i lumini dell’albero di Natale, la musica della messa di mezzanotte, la dolcezza dei sorrisi a far risplendere il regalo che ricevevo.", "zh": "童年时，圣诞树上的灯光、午夜弥撒的乐声、甜蜜的微笑，照亮了我收到的礼物。", "t": [17200, 26425]}]}, {"id": "ch25p14", "audio": true, "sents": [{"it": "“Gli uomini di dove stai tu,” disse il piccolo principe, “coltivano cinquemila rose in un giardino e non trovano quello che cercano...”", "zh": "“你那里的居民啊，”小王子说，“他们在花园里培育了五千朵玫瑰，却找不到他们真正在寻找的东西……”", "t": [100, 7300]}]}, {"id": "ch25p15", "audio": true, "sents": [{"it": "“Non lo trovano...” risposi.", "zh": "他们没找到。", "t": [100, 1826]}]}, {"id": "ch25p16", "audio": true, "sents": [{"it": "“Eppure, quello che cercano potrebbero trovarlo in una sola rosa o in un po’ d’acqua...”", "zh": "然而，他们所寻找的或许只在一朵玫瑰或少许水中即可找到……", "t": [100, 4738]}]}, {"id": "ch25p17", "audio": true, "sents": [{"it": "“Certo,” risposi.", "zh": "当然，我答道。", "t": [100, 1300]}]}, {"id": "ch25p18", "audio": true, "sents": [{"it": "E il piccolo principe aggiunse:", "zh": "小王子接着说：", "t": [100, 1888]}]}, {"id": "ch25p19", "audio": true, "sents": [{"it": "“Ma gli occhi sono ciechi.", "zh": "但眼睛是盲的。", "t": [100, 1812]}, {"it": "Bisogna cercare con il cuore.”", "zh": "用心去寻找。", "t": [1812, 3400]}]}, {"id": "ch25p20", "audio": true, "sents": [{"it": "Avevo bevuto.", "zh": "我已饮过。", "t": [100, 1288]}, {"it": "Respiravo bene.", "zh": "呼吸顺畅了。", "t": [1288, 2575]}, {"it": "Al sorgere del sole la sabbia ha il colore del miele.", "zh": "日出时分，沙粒泛着蜜色。", "t": [2575, 6062]}, {"it": "Ero felice anche di quel color miele.", "zh": "我也为那蜜色而喜悦。", "t": [6062, 8312]}, {"it": "Perché mai dovevo essere triste...", "zh": "为何我总是感到忧伤……", "t": [8312, 10075]}]}, {"id": "ch25p21", "audio": true, "sents": [{"it": "“Devi mantenere la promessa,” mi disse dolcemente il piccolo principe, che di nuovo si era seduto accanto a me.", "zh": "“你得遵守诺言，”小王子温柔地对我说，他又在我身边坐下。", "t": [100, 5913]}]}, {"id": "ch25p22", "audio": true, "sents": [{"it": "“Quale promessa?”", "zh": "什么诺言？", "t": [100, 1037]}]}, {"id": "ch25p23", "audio": true, "sents": [{"it": "“Sai...", "zh": "你知道……", "t": [100, 838]}, {"it": "la museruola per la pecora...", "zh": "绵羊的口罩", "t": [838, 2662]}, {"it": "io sono responsabile di quella rosa!”", "zh": "我负责这朵玫瑰。", "t": [2662, 4737]}]}, {"id": "ch25p24", "audio": true, "sents": [{"it": "Tirai fuori di tasca i miei disegni.", "zh": "我从口袋里掏出我的画稿。", "t": [100, 2650]}, {"it": "Il piccolo principe li vide e disse ridendo:", "zh": "小王子瞥见他们，便笑着说道：", "t": [2650, 5176]}]}, {"id": "ch25p25", "audio": true, "sents": [{"it": "“I tuoi baobab sembrano un po’ dei cavoli...”", "zh": "你的猴面包树看起来有点像卷心菜……", "t": [100, 2612]}]}, {"id": "ch25p26", "audio": true, "sents": [{"it": "“Oh!”", "zh": "哦！", "t": [100, 562]}]}, {"id": "ch25p27", "audio": true, "sents": [{"it": "Io che ero così fiero dei baobab!", "zh": "我曾如此自豪于我的猴面包树。", "t": [100, 2213]}]}, {"id": "ch25p28", "audio": true, "sents": [{"it": "“La tua volpe...", "zh": "你的狐狸……", "t": [100, 1225]}, {"it": "ha certe orecchie...", "zh": "它有那样的耳朵……", "t": [1225, 2562]}, {"it": "che sembrano un po’ delle corna...", "zh": "它的耳朵似乎有点像角……", "t": [2562, 4362]}, {"it": "e sono troppo lunghe!”", "zh": "它的耳朵太长了！", "t": [4362, 5575]}]}, {"id": "ch25p29", "audio": true, "sents": [{"it": "E rise ancora:", "zh": "它又唱了起来：", "t": [100, 1138]}]}, {"id": "ch25p30", "audio": true, "sents": [{"it": "“Sei ingiusto, ometto, io sapevo disegnare soltanto i boa chiusi e i boa aperti.”", "zh": "你是不公平的，小家伙，我只会画闭着的蟒蛇和打开的蟒蛇。", "t": [100, 5524]}]}, {"id": "ch25p31", "audio": true, "sents": [{"it": "“Ma va benissimo, dai,” disse, “i bambini capiscono.”", "zh": "孩子们能看懂。", "t": [100, 3788]}]}, {"id": "ch25p32", "audio": true, "sents": [{"it": "Disegnai quindi una museruola.", "zh": "我画了一个口罩。", "t": [100, 2362]}, {"it": "E nel dargliela mi si stringeva il cuore:", "zh": "递给她时，我心头紧缩。", "t": [2362, 4438]}]}, {"id": "ch25p33", "audio": true, "sents": [{"it": "“Hai progetti che io ignoro...”", "zh": "你有所图，我却不晓。", "t": [100, 1724]}]}, {"id": "ch25p34", "audio": true, "sents": [{"it": "Ma non mi rispose.", "zh": "他没有回答我。", "t": [100, 1450]}, {"it": "Mi disse:", "zh": "他对我说道：", "t": [1450, 2200]}]}, {"id": "ch25p35", "audio": true, "sents": [{"it": "“Sai...", "zh": "你知道……", "t": [100, 850]}, {"it": "domani è l’anniversario della mia caduta sulla Terra...”", "zh": "明天是我降落到地球的日子……", "t": [850, 3750]}]}, {"id": "ch25p36", "audio": true, "sents": [{"it": "Poi, dopo un momento di silenzio:", "zh": "然后，沉默片刻。", "t": [100, 2224]}]}, {"id": "ch25p37", "audio": true, "sents": [{"it": "“Ero caduto proprio qui vicino...”", "zh": "我正巧降落在此附近……", "t": [100, 1776]}]}, {"id": "ch25p38", "audio": true, "sents": [{"it": "E arrossì.", "zh": "他脸红了。", "t": [100, 863]}]}, {"id": "ch25p39", "audio": true, "sents": [{"it": "E di nuovo, senza capirne il motivo, provai una strana pena.", "zh": "我又一次，不知何故，感到一种奇怪的忧伤。", "t": [100, 4275]}, {"it": "Mi sorse però una domanda:", "zh": "我心中突然冒出一个问题：", "t": [4275, 5862]}]}, {"id": "ch25p40", "audio": true, "sents": [{"it": "“Allora non è un caso se la mattina in cui ti ho conosciuto, otto giorni fa, te ne andavi in giro da solo, lontano mille miglia da qualunque terra abitata!", "zh": "那天早上，认识你的那天，八天前，你独自一人，远离任何有人居住的土地，这并非偶然！", "t": [100, 9238]}, {"it": "Tornavi verso il punto dov’eri caduto?”", "zh": "你回到了你坠落的地方吗？", "t": [9238, 11324]}]}, {"id": "ch25p41", "audio": true, "sents": [{"it": "Di nuovo il piccolo principe arrossì.", "zh": "小王子又红了脸。", "t": [100, 2263]}]}, {"id": "ch25p42", "audio": true, "sents": [{"it": "E io aggiunsi, titubante:", "zh": "我犹豫着补充道：", "t": [100, 1937]}]}, {"id": "ch25p43", "audio": true, "sents": [{"it": "“Era forse a causa dell’anniversario?”", "zh": "或许是因为周年纪念吧？", "t": [100, 2075]}]}, {"id": "ch25p44", "audio": true, "sents": [{"it": "Di nuovo il piccolo principe arrossì.", "zh": "小王子又脸红了。", "t": [100, 2525]}, {"it": "Non rispondeva mai alle domande, ma quando si arrossisce significa “sì”, vero?", "zh": "他从不回答问题，但当他脸红时，就意味着“是”，对吧？", "t": [2525, 7500]}]}, {"id": "ch25p45", "audio": true, "sents": [{"it": "“Ah!” gli dissi, “ho paura...”", "zh": "“啊！”我对他说，“我害怕……”", "t": [100, 2438]}]}, {"id": "ch25p46", "audio": true, "sents": [{"it": "Ma mi rispose:", "zh": "他回答道：", "t": [100, 1137]}]}, {"id": "ch25p47", "audio": true, "sents": [{"it": "“Adesso devi lavorare.", "zh": "现在你得工作了。", "t": [100, 1662]}, {"it": "Devi tornare al tuo aereo.", "zh": "你必须回到你的飞机上。", "t": [1662, 3638]}, {"it": "Io ti aspetto qui.", "zh": "我在这里等你。", "t": [3638, 4975]}, {"it": "Torna domani sera...”", "zh": "明天晚上再来……", "t": [4975, 6075]}]}, {"id": "ch25p48", "audio": true, "sents": [{"it": "Ma non ero tranquillo.", "zh": "我心神不宁。", "t": [100, 1725]}, {"it": "Pensavo alla volpe.", "zh": "我想起了狐狸。", "t": [1725, 3088]}, {"it": "Si corre il rischio di piangere un po’, quando ci si è lasciati addomesticare...", "zh": "若被驯养，难免会流几滴泪。", "t": [3088, 7662]}]}]}, {"id": "ch26", "title_it": "XXVI", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"it": "C’erano, accanto al pozzo, i resti di un vecchio muro di pietra.", "zh": "井边，石墙的残垣断壁。", "t": [100, 4525]}, {"it": "Quando l’indomani sera tornai, dopo aver lavorato, scorsi da lontano il mio piccolo principe seduto là sopra, con le gambe penzoloni.", "zh": "第二天晚上，我干完活回来，远远看见我的小王子坐在那残壁上，双腿悬空。", "t": [4525, 13112]}, {"it": "E lo sentii che parlava:", "zh": "我听见他在说：", "t": [13112, 14450]}]}, {"id": "ch26p01", "audio": true, "sents": [{"it": "“Ma non te lo ricordi?” diceva.", "zh": "你难道不记得了吗？", "t": [100, 2400]}, {"it": "“Non è mica qui!”", "zh": "这可不是这里！", "t": [2400, 3463]}]}, {"id": "ch26p02", "audio": true, "sents": [{"it": "Probabilmente un’altra voce gli rispose, poiché lui ribatté:", "zh": "或许有另一个声音回应了他，因为他反驳道：", "t": [100, 3675]}]}, {"id": "ch26p03", "audio": true, "sents": [{"it": "“Ma sì, invece!", "zh": "是的，但却是这样！", "t": [100, 1838]}, {"it": "Il giorno è giusto, ma il posto non è questo...”", "zh": "今日良辰，非此所在……", "t": [1838, 4875]}]}, {"id": "ch26p04", "audio": true, "sents": [{"it": "Continuai ad avvicinarmi al muro.", "zh": "继续向墙边靠近。", "t": [100, 2250]}, {"it": "Non sentivo né vedevo ancora nessuno.", "zh": "我既听不见也看不见任何人。", "t": [2250, 4650]}, {"it": "Tuttavia il piccolo principe di nuovo ribatté:", "zh": "然而小王子又反驳道：", "t": [4650, 7175]}]}, {"id": "ch26p05", "audio": true, "sents": [{"it": "“...Certo.", "zh": "当然。", "t": [100, 1025]}, {"it": "Guarda dove iniziano le mie impronte sulla sabbia.", "zh": "瞧瞧我的足迹在沙地上是从哪儿开始的。", "t": [1025, 4012]}, {"it": "Non devi fare altro che aspettarmi lì.", "zh": "你只需在那里等我。", "t": [4012, 6312]}, {"it": "Ci sarò.", "zh": "我会在那里。", "t": [6312, 7138]}, {"it": "Stanotte.”", "zh": "今夜。", "t": [7138, 7900]}]}, {"id": "ch26p06", "audio": true, "sents": [{"it": "Ero a venti metri dal muro e continuavo a non vedere niente.", "zh": "我离墙只有二十米，却依旧一无所见。", "t": [100, 3463]}]}, {"id": "ch26p07", "audio": true, "sents": [{"it": "Dopo una pausa, il piccolo principe disse ancora:", "zh": "停顿片刻后，小王子又说道：", "t": [100, 3387]}]}, {"id": "ch26p08", "audio": true, "sents": [{"it": "“È un buon veleno, il tuo?", "zh": "你有毒液吗？", "t": [100, 2125]}, {"it": "Sei sicuro di non farmi soffrire a lungo?”", "zh": "你能否肯定不会让我痛苦很久？", "t": [2125, 4263]}]}, {"id": "ch26p09", "audio": true, "sents": [{"it": "Mi fermai, con il cuore in gola, ma continuavo a non capire.", "zh": "我停住脚步，心揪成一团，却依旧不懂他的话。", "t": [100, 4026]}]}, {"id": "ch26p10", "audio": true, "sents": [{"it": "“Adesso vattene...” disse.", "zh": "现在你走吧……他说。", "t": [100, 2675]}, {"it": "“Voglio scendere!”", "zh": "我要跳下去！", "t": [2675, 3700]}]}, {"id": "ch26p11", "audio": true, "sents": [{"it": "Allora abbassai gli occhi ai piedi del muro e sobbalzai!", "zh": "于是，我低头看向墙脚，惊得跳了起来。", "t": [100, 3625]}, {"it": "Era lì, ritto verso il piccolo principe, uno di quei serpenti gialli che ammazzano in trenta secondi.", "zh": "那里，一条黄蛇直挺挺地对着小王子。", "t": [3625, 10000]}, {"it": "Mi ficcai una mano in tasca per tirar fuori la pistola e presi a correre, ma, al rumore che feci, il serpente scivolò piano nella sabbia, come un rigagnolo d’acqua che muore e, senza affrettarsi troppo, si infilò tra le pietre con un lieve rumore metallico.", "zh": "我伸手口袋掏出手枪，却听脚步声，蛇如水柱般悄无声息地钻入石缝，发出轻微的金属声响。", "t": [10000, 25900]}]}, {"id": "ch26p12", "audio": true, "sents": [{"it": "Giunsi al muro appena in tempo per ricevere fra le braccia il mio ometto, il mio principe, pallido come la neve.", "zh": "及时赶到墙边，将我的小家伙、我的王子接在怀中，他脸色苍白如雪。", "t": [100, 6400]}]}, {"id": "ch26p13", "audio": true, "sents": [{"it": "“Che storia è questa!", "zh": "这究竟是怎么回事！", "t": [100, 1600]}, {"it": "Adesso parli con i serpenti!”", "zh": "现在你竟与蛇说话了！", "t": [1600, 3437]}]}, {"id": "ch26p14", "audio": true, "sents": [{"it": "Avevo slacciato la sua eterna sciarpa color oro.", "zh": "我松开了他那永恒的金色围巾。", "t": [100, 2912]}, {"it": "Gli avevo bagnato le tempie e lo avevo fatto bere.", "zh": "我给他擦了额头，让他喝了水。", "t": [2912, 5900]}, {"it": "E adesso non osavo più domandargli nulla.", "zh": "如今我再也不敢向他提问。", "t": [5900, 8425]}, {"it": "Mi guardò con aria seria e mi mise le braccia intorno al collo.", "zh": "他严肃地望着我，将双臂绕过我的脖颈。", "t": [8425, 12212]}, {"it": "Gli sentivo battere il cuore come quello di un uccello morente dopo che gli hai sparato con la carabina.", "zh": "他心跳如中枪濒死鸟儿的心跳。", "t": [12212, 17738]}, {"it": "Mi disse:", "zh": "他对我说：", "t": [17738, 18487]}]}, {"id": "ch26p15", "audio": true, "sents": [{"it": "“Sono contento che tu abbia trovato quel che mancava al tuo aereo.", "zh": "我为你的飞机找到了缺失的部分，我很高兴。", "t": [100, 3862]}, {"it": "Adesso potrai tornare a casa...”", "zh": "现在你可以回家了……", "t": [3862, 5712]}]}, {"id": "ch26p16", "audio": true, "sents": [{"it": "“Come fai a saperlo!”", "zh": "你怎么知道的？", "t": [100, 1326]}]}, {"id": "ch26p17", "audio": true, "sents": [{"it": "Venivo proprio ad annunciargli che contro ogni speranza ero riuscito a finire il lavoro!", "zh": "我正是来告诉他，出乎意料地，我竟修好了飞机！", "t": [100, 4750]}]}, {"id": "ch26p18", "audio": true, "sents": [{"it": "Non rispose alla mia domanda, ma aggiunse:", "zh": "他没有回答我的问题，却接着说：", "t": [100, 2687]}]}, {"id": "ch26p19", "audio": true, "sents": [{"it": "“Anch’io oggi torno a casa...”", "zh": "今夜我也将回家……", "t": [100, 1688]}]}, {"id": "ch26p20", "audio": true, "sents": [{"it": "Poi, malinconico:", "zh": "然后，忧郁地：", "t": [100, 1750]}]}, {"id": "ch26p21", "audio": true, "sents": [{"it": "“È molto più lontano...", "zh": "那要远得多……", "t": [100, 1512]}, {"it": "è molto più complicato...”", "zh": "这……要复杂得多……", "t": [1512, 2862]}]}, {"id": "ch26p22", "audio": true, "sents": [{"it": "Sentivo che stava succedendo qualcosa di straordinario.", "zh": "我感觉到发生了非同寻常的事情。", "t": [100, 3562]}, {"it": "Lo strinsi fra le braccia, come fosse un bambino piccolo, e tuttavia mi sembrava che precipitasse in un abisso senza che potessi far nulla per trattenerlo...", "zh": "将他紧紧搂在怀里，仿佛他是个小孩子，然而我觉得他正坠入无底深渊，而我却无法拉住他……", "t": [3562, 12338]}]}, {"id": "ch26p23", "audio": true, "sents": [{"it": "Aveva lo sguardo serio, perso lontano:", "zh": "他目光严肃，投向远方。", "t": [100, 2700]}]}, {"id": "ch26p24", "audio": true, "sents": [{"it": "“Ho la tua pecora.", "zh": "我有你的绵羊。", "t": [100, 1350]}, {"it": "E ho la cassa per la pecora.", "zh": "我还有为绵羊准备的箱子。", "t": [1350, 3075]}, {"it": "E ho la museruola...”", "zh": "我有水壶……", "t": [3075, 4188]}]}, {"id": "ch26p25", "audio": true, "sents": [{"it": "E sorrise con malinconia.", "zh": "带着忧郁的微笑。", "t": [100, 1712]}]}, {"id": "ch26p26", "audio": true, "sents": [{"it": "Aspettai a lungo.", "zh": "我等了许久。", "t": [100, 1388]}, {"it": "Sentivo che pian piano si rianimava.", "zh": "他渐渐恢复了生机。", "t": [1388, 3387]}]}, {"id": "ch26p27", "audio": true, "sents": [{"it": "“Ometto, hai avuto paura...”", "zh": "小人儿，你害怕了……", "t": [100, 2063]}]}, {"id": "ch26p28", "audio": true, "sents": [{"it": "Certo che aveva avuto paura!", "zh": "当然，他害怕了！", "t": [100, 1938]}, {"it": "Ma rise dolcemente:", "zh": "他温柔地站起身来：", "t": [1938, 3275]}]}, {"id": "ch26p29", "audio": true, "sents": [{"it": "“Avrò molta più paura stasera...”", "zh": "今夜我会更害怕……", "t": [100, 1775]}]}, {"id": "ch26p30", "audio": true, "sents": [{"it": "Di nuovo fui raggelato da una sensazione d’ineluttabilità.", "zh": "又是一次，我感到一种无法抗拒的宿命感。", "t": [100, 3850]}, {"it": "E capii che non sopportavo l’idea di non udire più quella risata.", "zh": "我意识到自己无法忍受再听不到那笑声。", "t": [3850, 7675]}, {"it": "Per me era come una sorgente nel deserto.", "zh": "如同沙漠中的一口井。", "t": [7675, 10050]}]}, {"id": "ch26p31", "audio": true, "sents": [{"it": "“Ometto, voglio ancora sentirti ridere...”", "zh": "孩子，我还想再听到你的笑声……", "t": [100, 2575]}]}, {"id": "ch26p32", "audio": true, "sents": [{"it": "Ma lui mi disse:", "zh": "他对我说道：", "t": [100, 1175]}]}, {"id": "ch26p33", "audio": true, "sents": [{"it": "“Stanotte sarà trascorso un anno.", "zh": "今夜，一年已过。", "t": [100, 2312]}, {"it": "La mia stella si troverà proprio sopra il punto in cui sono caduto l’anno scorso...”", "zh": "我的星星将正好在我去年坠落的地方上方……", "t": [2312, 6975]}]}, {"id": "ch26p34", "audio": true, "sents": [{"it": "“Ometto, è vero che questa storia del serpente e dell’appuntamento e della stella è soltanto un brutto sogno...”", "zh": "这蛇、约会、星星的故事，莫非只是一场噩梦……", "t": [100, 6313]}]}, {"id": "ch26p35", "audio": true, "sents": [{"it": "Ma non rispose alla mia domanda.", "zh": "他没有回答我的问题。", "t": [100, 2062]}, {"it": "Mi disse:", "zh": "他对我说：", "t": [2062, 2813]}]}, {"id": "ch26p36", "audio": true, "sents": [{"it": "“Ciò che è importante non si vede...”", "zh": "肉眼难见，方显其重。", "t": [100, 1787]}]}, {"id": "ch26p37", "audio": true, "sents": [{"it": "“Certo...”", "zh": "当然……", "t": [100, 775]}]}, {"id": "ch26p38", "audio": true, "sents": [{"it": "“È come per la rosa.", "zh": "这就像我的玫瑰。", "t": [100, 1538]}, {"it": "Se ami una rosa che si trova su una stella, di notte è bello guardare il cielo.", "zh": "若你爱上了一朵长在星星上的玫瑰，夜晚仰望星空便是一种美。", "t": [1538, 6262]}, {"it": "Tutte le stelle sono fiorite.”", "zh": "所有的星星都开花了。", "t": [6262, 7887]}]}, {"id": "ch26p39", "audio": true, "sents": [{"it": "“Certo...”", "zh": "当然……", "t": [100, 775]}]}, {"id": "ch26p40", "audio": true, "sents": [{"it": "“È come per l’acqua.", "zh": "如同水一般。", "t": [100, 1450]}, {"it": "Quella che mi hai dato da bere era come una musica, per via della carrucola e della corda...", "zh": "那水，因着辘轳与绳索，便成了音乐。", "t": [1450, 6400]}, {"it": "ti ricordi...", "zh": "你记得吗？", "t": [6400, 7350]}, {"it": "com’era buona.”", "zh": "那真美味。", "t": [7350, 8188]}]}, {"id": "ch26p41", "audio": true, "sents": [{"it": "“Certo...”", "zh": "当然……", "t": [100, 775]}]}, {"id": "ch26p42", "audio": true, "sents": [{"it": "“Di notte, ricordati di guardare le stelle.", "zh": "夜晚，别忘了仰望星空。", "t": [100, 2962]}, {"it": "Dove sto io è troppo piccolo perché possa mostrarti dove si trova la mia.", "zh": "我在此太小，无法向你指出我的位置。", "t": [2962, 7412]}, {"it": "Meglio così.", "zh": "如此为佳。", "t": [7412, 8525]}, {"it": "La mia stella sarà per te una stella qualsiasi, e allora ti farà piacere guardarle tutte...", "zh": "你的星星将变成任何一颗星星，那时你便会喜欢看它们全部。", "t": [8525, 13862]}, {"it": "Saranno tutte tue amiche.", "zh": "都将成为你的朋友。", "t": [13862, 15550]}, {"it": "E poi ti farò un regalo...”", "zh": "然后，我将送你一份礼物……", "t": [15550, 16963]}]}, {"id": "ch26p43", "audio": true, "sents": [{"it": "Rise ancora.", "zh": "再站起来。", "t": [100, 1037]}]}, {"id": "ch26p44", "audio": true, "sents": [{"it": "“Ah!, ometto, ometto, come mi piace udire questa risata!”", "zh": "啊，小家伙，小家伙，我喜欢听你的笑声！", "t": [100, 4038]}]}, {"id": "ch26p45", "audio": true, "sents": [{"it": "“E infatti sarà il mio regalo...", "zh": "这将是我的礼物……", "t": [100, 2188]}, {"it": "sarà come per l’acqua...”", "zh": "宛如水一般……", "t": [2188, 3450]}]}, {"id": "ch26p46", "audio": true, "sents": [{"it": "“Che cosa vuoi dire?”", "zh": "你想说什么？", "t": [100, 1188]}]}, {"id": "ch26p47", "audio": true, "sents": [{"it": "“Le stelle sono diverse da persona a persona.", "zh": "星星对每个人而言各不相同。", "t": [100, 2862]}, {"it": "Per chi viaggia le stelle sono una guida.", "zh": "对旅行者而言，星星是向导。", "t": [2862, 5200]}, {"it": "Per altri sono soltanto lucine.", "zh": "对其他人来说，它们只是微光。", "t": [5200, 7362]}, {"it": "Per altri ancora, come gli scienziati, sono problemi.", "zh": "对其他人而言，它们只是问题。", "t": [7362, 11088]}, {"it": "Per il mio uomo d’affari erano oro.", "zh": "对那位商人来说，星星是金子。", "t": [11088, 13175]}, {"it": "Ma tutte queste stelle tacciono.", "zh": "所有的星星都沉默不语。", "t": [13175, 15112]}, {"it": "Tu invece avrai stelle che saranno qualcosa di completamente diverso...”", "zh": "你将拥有与众不同的星星……", "t": [15112, 18800]}]}, {"id": "ch26p48", "audio": true, "sents": [{"it": "“Cosa vuoi dire?”", "zh": "你想说什么？", "t": [100, 1000]}]}, {"id": "ch26p49", "audio": true, "sents": [{"it": "“Quando la notte guarderai il cielo, poiché io abiterò in una di esse, e riderò in una di esse, per te sarà come se ridessero tutte le stelle.", "zh": "当夜幕降临，仰望星空，因为我在其中一颗星星上居住，并在那里欢笑，对你而言，便如同所有的星星都在对你微笑。", "t": [100, 8388]}, {"it": "Avrai stelle che sapranno ridere!”", "zh": "你将拥有会笑的星星。", "t": [8388, 10113]}]}, {"id": "ch26p50", "audio": true, "sents": [{"it": "E rise ancora.", "zh": "他又站了起来。", "t": [100, 1113]}]}, {"id": "ch26p51", "audio": true, "sents": [{"it": "“E quando ti sarai consolato (poiché ci si consola sempre), sarai contento di avermi conosciuto.", "zh": "当你得到安慰之后（人常常自我安慰），你会为认识我而高兴。", "t": [100, 5962]}, {"it": "Sarai sempre mio amico.", "zh": "你将永远是我的朋友。", "t": [5962, 7562]}, {"it": "Avrai voglia di ridere con me.", "zh": "愿与你同笑。", "t": [7562, 9300]}, {"it": "E ogni tanto aprirai la finestra, così, per puro piacere...", "zh": "偶尔，你会只为愉悦而打开窗户。", "t": [9300, 13450]}, {"it": "E i tuoi amici saranno stupiti di vederti ridere guardando il cielo.", "zh": "你的朋友们会惊讶于你仰望星空时独自发笑。", "t": [13450, 17288]}, {"it": "Allora tu gli dirai: ‘Sì, le stelle mi fanno sempre ridere!’.", "zh": "是的，星星总是让我发笑！", "t": [17288, 21625]}, {"it": "E penseranno che sei pazzo.", "zh": "他们会以为你疯了。", "t": [21625, 23488]}, {"it": "Ti avrò fatto un bello scherzetto...”", "zh": "我给你开了一个小小的玩笑……", "t": [23488, 25237]}]}, {"id": "ch26p52", "audio": true, "sents": [{"it": "E rise ancora.", "zh": "他又站了起来。", "t": [100, 1113]}]}, {"id": "ch26p53", "audio": true, "sents": [{"it": "“Sarà come se, invece delle stelle, ti avessi dato tanti sonagli che sanno ridere...”", "zh": "仿佛我给了你许多会笑的铃铛……", "t": [100, 4887]}]}, {"id": "ch26p54", "audio": true, "sents": [{"it": "E rise ancora.", "zh": "他又站了起来。", "t": [100, 1375]}, {"it": "Poi tornò serio:", "zh": "然后，他变得严肃起来：", "t": [1375, 2576]}]}, {"id": "ch26p55", "audio": true, "sents": [{"it": "“Stanotte...", "zh": "今夜……", "t": [100, 1125]}, {"it": "sai...", "zh": "你说……", "t": [1125, 1788]}, {"it": "non venire.”", "zh": "别来。", "t": [1788, 2537]}]}, {"id": "ch26p56", "audio": true, "sents": [{"it": "“Non ti lascerò.”", "zh": "我不会离开你。", "t": [100, 975]}]}, {"id": "ch26p57", "audio": true, "sents": [{"it": "“Sembrerà che stia male...", "zh": "似乎他病了……", "t": [100, 1662]}, {"it": "che muoia.", "zh": "他将会死去。", "t": [1662, 2588]}, {"it": "È così.", "zh": "如此而已。", "t": [2588, 3488]}, {"it": "Non venire a vedere.", "zh": "别来看我。", "t": [3488, 4862]}, {"it": "Non è il caso...”", "zh": "这并非是时候……", "t": [4862, 5925]}]}, {"id": "ch26p58", "audio": true, "sents": [{"it": "“Non ti lascerò.”", "zh": "我不会离开你。", "t": [100, 975]}]}, {"id": "ch26p59", "audio": true, "sents": [{"it": "Ma era pensieroso.", "zh": "他心事重重。", "t": [100, 1338]}]}, {"id": "ch26p60", "audio": true, "sents": [{"it": "“Te lo dico...", "zh": "我告诉你……", "t": [100, 1150]}, {"it": "per via del serpente.", "zh": "因蛇之故。", "t": [1150, 2675]}, {"it": "Non deve morderti...", "zh": "它不会咬你……", "t": [2675, 4100]}, {"it": "I serpenti sono cattivi.", "zh": "蛇是恶毒的。", "t": [4100, 5950]}, {"it": "Possono mordere per il semplice gusto di farlo...”", "zh": "它们仅仅为了取乐而咬人……", "t": [5950, 8513]}]}, {"id": "ch26p61", "audio": true, "sents": [{"it": "“Non ti lascerò.”", "zh": "我不会离开你。", "t": [100, 975]}]}, {"id": "ch26p62", "audio": true, "sents": [{"it": "Ma qualcosa lo tranquillizzò:", "zh": "某种东西使他平静了下来：", "t": [100, 1763]}]}, {"id": "ch26p63", "audio": true, "sents": [{"it": "“È vero che non hanno veleno per un secondo morso...”", "zh": "蛇咬的第二口不再有毒液……", "t": [100, 2612]}]}, {"id": "ch26p64", "audio": true, "sents": [{"it": "Quella notte non lo vidi mettersi in cammino.", "zh": "那晚我没看到他动身。", "t": [100, 2700]}, {"it": "Se n’era andato senza far rumore.", "zh": "他悄然离去。", "t": [2700, 4900]}, {"it": "Quando riuscii a raggiungerlo, camminava deciso, di buon passo.", "zh": "当我终于追上他时，他步履坚定，大步流星。", "t": [4900, 9200]}, {"it": "Mi disse soltanto:", "zh": "他只说了这么一句：", "t": [9200, 10512]}]}, {"id": "ch26p65", "audio": true, "sents": [{"it": "“Ah!", "zh": "啊！", "t": [100, 750]}, {"it": "Sei qui...”", "zh": "你在这里……", "t": [750, 1463]}]}, {"id": "ch26p66", "audio": true, "sents": [{"it": "E mi prese per mano.", "zh": "他握住了我的手。", "t": [100, 1488]}, {"it": "Ma si tormentava ancora:", "zh": "他仍旧心绪不宁：", "t": [1488, 2987]}]}, {"id": "ch26p67", "audio": true, "sents": [{"it": "“Hai fatto male.", "zh": "你受伤了。", "t": [100, 1262]}, {"it": "Sarai triste.", "zh": "你会难过。", "t": [1262, 2462]}, {"it": "Sembrerà che sia morto e non sarà vero...”", "zh": "他似乎已死去，实则不然……", "t": [2462, 4612]}]}, {"id": "ch26p68", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "我沉默着。", "t": [100, 962]}]}, {"id": "ch26p69", "audio": true, "sents": [{"it": "“Capisci, è troppo lontano.", "zh": "你明白，太远了。", "t": [100, 2212]}, {"it": "Non posso portarmi dietro questo corpo.", "zh": "我无法带着这具身体离去。", "t": [2212, 4738]}, {"it": "È troppo pesante.”", "zh": "这副皮囊太沉重了。", "t": [4738, 5837]}]}, {"id": "ch26p70", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "我沉默着。", "t": [100, 962]}]}, {"id": "ch26p71", "audio": true, "sents": [{"it": "“Ma sarà come una vecchia scorza abbandonata.", "zh": "就像丢弃的旧皮壳。", "t": [100, 2812]}, {"it": "Non sono tristi, le vecchie scorze...”", "zh": "旧皮壳，我并不悲伤。", "t": [2812, 5074]}]}, {"id": "ch26p72", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "我沉默着。", "t": [100, 962]}]}, {"id": "ch26p73", "audio": true, "sents": [{"it": "Era un po’ scoraggiato.", "zh": "他有些泄气。", "t": [100, 1625]}, {"it": "Ma fece ancora uno sforzo:", "zh": "他又竭尽全力：", "t": [1625, 3288]}]}, {"id": "ch26p74", "audio": true, "sents": [{"it": "“Sarà carino, sai.", "zh": "那会很棒，你知道的。", "t": [100, 2112]}, {"it": "Anch’io guarderò le stelle.", "zh": "我也会仰望星空。", "t": [2112, 3975]}, {"it": "Tutte le stelle saranno pozzi con una carrucola arrugginita.", "zh": "所有的星星都将是带有生锈辘轳的井。", "t": [3975, 7612]}, {"it": "Tutte le stelle mi verseranno da bere...”", "zh": "所有的星星都会为我倒水喝……", "t": [7612, 9587]}]}, {"id": "ch26p75", "audio": true, "sents": [{"it": "Io tacevo.", "zh": "我沉默着。", "t": [100, 962]}]}, {"id": "ch26p76", "audio": true, "sents": [{"it": "“Sarà divertentissimo!", "zh": "那会非常有趣！", "t": [100, 1750]}, {"it": "Tu avrai cinquecento milioni di sonagli, io avrò cinquecento milioni di sorgenti...”", "zh": "你将拥有五亿个小铃铛，而我将拥有五亿个泉眼……", "t": [1750, 6638]}]}, {"id": "ch26p77", "audio": true, "sents": [{"it": "E anche lui tacque, perché piangeva...", "zh": "他也沉默了，因为他在哭泣……", "t": [100, 2425]}]}, {"id": "ch26p78", "audio": true, "sents": [{"it": "“Ecco, siamo arrivati.", "zh": "我们到了。", "t": [100, 2050]}, {"it": "Lasciami fare un passo da solo.”", "zh": "让我独自走一步。", "t": [2050, 3738]}]}, {"id": "ch26p79", "audio": true, "sents": [{"it": "E si sedette perché aveva paura.", "zh": "他坐下来，因为他害怕了。", "t": [100, 1963]}]}, {"id": "ch26p80", "audio": true, "sents": [{"it": "Disse ancora:", "zh": "他又说：", "t": [100, 1124]}]}, {"id": "ch26p81", "audio": true, "sents": [{"it": "“Sai...", "zh": "你难道不知道……", "t": [100, 750]}, {"it": "io sono responsabile della mia rosa!", "zh": "我对我那朵玫瑰负责！", "t": [750, 3038]}, {"it": "E lei è così delicata!", "zh": "她如此娇弱。", "t": [3038, 4788]}, {"it": "È così ingenua.", "zh": "如此天真。", "t": [4788, 6162]}, {"it": "Per proteggersi dal mondo ha solo quattro spine da niente...”", "zh": "仅凭四根无用的刺来保护自己，抵御世上的侵害……", "t": [6162, 9537]}]}, {"id": "ch26p82", "audio": true, "sents": [{"it": "Mi sedetti perché non riuscivo più a stare in piedi.", "zh": "我因无法站立而坐了下来。", "t": [100, 3338]}, {"it": "Disse:", "zh": "他说：", "t": [3338, 4026]}]}, {"id": "ch26p83", "audio": true, "sents": [{"it": "“Ecco...", "zh": "这是……", "t": [100, 950]}, {"it": "È tutto...”", "zh": "这便是全部……", "t": [950, 1588]}]}, {"id": "ch26p84", "audio": true, "sents": [{"it": "Esitò ancora un istante, poi si rialzò.", "zh": "他停顿片刻，然后站起身来。", "t": [100, 3238]}, {"it": "Fece un passo.", "zh": "他迈出了一步。", "t": [3238, 4438]}, {"it": "Io non potevo muovermi.", "zh": "我动弹不得。", "t": [4438, 5813]}]}, {"id": "ch26p85", "audio": true, "sents": [{"it": "Ci fu solo un lampo giallo vicino alla sua caviglia.", "zh": "一道黄光掠过他的脚踝。", "t": [100, 3138]}, {"it": "Rimase un secondo immobile.", "zh": "他愣住了片刻。", "t": [3138, 5088]}, {"it": "Non gridò.", "zh": "他没有喊叫。", "t": [5088, 6062]}, {"it": "Cadde piano come cade un albero.", "zh": "如树倒地般缓缓落下。", "t": [6062, 8188]}, {"it": "Non fece neppure rumore, a causa della sabbia.", "zh": "它连沙沙声都没有发出。", "t": [8188, 11024]}]}]}, {"id": "ch27", "title_it": "XXVII", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"it": "E adesso, certo, sono già passati sei anni...", "zh": "如今，当然，已是六年过去了……", "t": [100, 3675]}, {"it": "Non avevo mai raccontato questa storia.", "zh": "我从未讲述过这个故事。", "t": [3675, 6062]}, {"it": "Gli amici che ho ritrovato sono stati felici di rivedermi vivo.", "zh": "重逢的老友们见到我安然无恙，都喜出望外。", "t": [6062, 9600]}, {"it": "Ero triste, ma dicevo: “È la stanchezza...”.", "zh": "我心中忧伤，却总是说：“只因疲惫……”", "t": [9600, 12600]}]}, {"id": "ch27p01", "audio": true, "sents": [{"it": "Adesso mi sono un po’ consolato.", "zh": "如今，我已稍感慰藉。", "t": [100, 2238]}, {"it": "Insomma...", "zh": "也就是说", "t": [2238, 3088]}, {"it": "non del tutto.", "zh": "亦非全然。", "t": [3088, 4200]}, {"it": "Ma so che è tornato sul suo pianeta, perché al sorgere del sole non ho ritrovato il corpo.", "zh": "我知道他回到了自己的星球，因为太阳升起时我没有找到他的尸体。", "t": [4200, 9450]}, {"it": "Non era un corpo tanto pesante...", "zh": "他的身体并不沉重……", "t": [9450, 11538]}, {"it": "E di notte mi piace ascoltare le stelle.", "zh": "夜幕降临，我偏爱聆听星辰的低语。", "t": [11538, 14050]}, {"it": "Sono come cinquecento milioni di sonagli...", "zh": "它们如同五亿个小铃铛……", "t": [14050, 16400]}]}, {"id": "ch27p02", "audio": true, "sents": [{"it": "C’è però un fatto importante.", "zh": "然而，有一件重要的事。", "t": [100, 2000]}, {"it": "Ho dimenticato di aggiungere la cinghia di cuoio alla museruola che ho disegnato per il piccolo principe!", "zh": "我忘了给小王子画的口罩加上皮带！", "t": [2000, 7638]}, {"it": "Non avrà potuto metterla alla pecora.", "zh": "他无法给绵羊戴上口罩。", "t": [7638, 9938]}, {"it": "Allora mi chiedo: “Che cosa è successo sul suo pianeta?", "zh": "那么我想：“在他星球上发生了什么？”", "t": [9938, 13562]}, {"it": "Forse la pecora ha mangiato la rosa...?”.", "zh": "或许绵羊把花儿吃掉了……？", "t": [13562, 15663]}]}, {"id": "ch27p03", "audio": true, "sents": [{"it": "A volte mi dico: “Sicuramente no!", "zh": "我有时对自己说：“肯定不会的！”", "t": [100, 2612]}, {"it": "Ogni sera il piccolo principe copre la rosa con la campana di vetro e tiene d’occhio la pecora...”.", "zh": "每晚小王子用玻璃罩罩住他的玫瑰，并留意着那头绵羊。", "t": [2612, 8225]}, {"it": "Allora sono felice.", "zh": "那时我心怀喜悦。", "t": [8225, 9688]}, {"it": "E tutte le stelle ridono dolcemente.", "zh": "所有星星都在温柔地微笑。", "t": [9688, 11800]}]}, {"id": "ch27p04", "audio": true, "sents": [{"it": "Altre volte mi dico: “Prima o poi capita a tutti di distrarsi!", "zh": "有时我又对自己说：“终究，每个人都会偶尔分心！”", "t": [100, 4312]}, {"it": "Una sera ha dimenticato la campana di vetro, oppure la pecora è uscita senza far rumore durante la notte...”.", "zh": "那晚，他忘了玻璃罩，或是绵羊悄无声息地溜出了门……", "t": [4312, 10738]}, {"it": "Allora i sonagli si trasformano in lacrime!...", "zh": "铃铛化作泪滴……", "t": [10738, 13276]}]}, {"id": "ch27p05", "audio": true, "sents": [{"it": "È un mistero enorme.", "zh": "这是一个巨大的谜团。", "t": [100, 1625]}, {"it": "Per voi che come me amate il piccolo principe, tutto nell’universo cambia se da qualche parte, non si sa dove, una pecora che non conosciamo ha mangiato una rosa oppure no...", "zh": "对你们这些如同我一般深爱小王子的人来说，整个宇宙若是有不知名角落的绵羊吃掉了一朵玫瑰，或是没有，便会发生改变……", "t": [1625, 11513]}]}, {"id": "ch27p06", "audio": true, "sents": [{"it": "Guardate il cielo.", "zh": "仰望星空", "t": [100, 1300]}, {"it": "Domandatevi: “La pecora ha mangiato o non ha mangiato il fiore?”.", "zh": "你们可曾想过：“那朵花，绵羊是吃了还是没吃？”", "t": [1300, 5162]}, {"it": "E vedrete come tutto è diverso...", "zh": "你们会发现一切皆已不同。", "t": [5162, 6926]}]}, {"id": "ch27p07", "audio": true, "sents": [{"it": "E nessun adulto capirà mai quanto è importante!", "zh": "大人永远无法明白这有多么重要。", "t": [100, 2900]}]}, {"id": "ch27p08", "audio": true, "sents": [{"it": "Questo è per me il paesaggio più bello e più triste del mondo.", "zh": "这是世上最美又最凄凉的风光。", "t": [100, 3662]}, {"it": "È lo stesso paesaggio della pagina precedente, ma l’ho disegnato un’altra volta per mostrarvelo bene.", "zh": "这幅画与上一页相同，但我又画了一次，以便你们能看个清楚。", "t": [3662, 9475]}, {"it": "Qui il piccolo principe è apparso sulla Terra e qui è scomparso.", "zh": "小王子在这里降临地球，又在这里消失。", "t": [9475, 13387]}]}, {"id": "ch27p09", "audio": true, "sents": [{"it": "Guardate attentamente questo paesaggio per essere sicuri di riconoscerlo, se un giorno doveste viaggiare in Africa, nel deserto.", "zh": "仔细观察这幅风光，以便日后在非洲沙漠旅行时能认出它。", "t": [100, 7712]}, {"it": "E se vi capitasse di passare di lì, vi scongiuro, non tirate dritto, fermatevi un poco sotto la stella!", "zh": "若您路过此地，我恳求您，别径直前行，请在那颗星星下稍作停留！", "t": [7712, 14275]}, {"it": "Se allora vi viene incontro un bambino, se ride, se ha i capelli d’oro, se non risponde alle domande, voi sapete chi è.", "zh": "若有个孩子向你走来；他笑得灿烂；金发披肩；他不答你的问询；那你便知他是谁了。", "t": [14275, 21488]}, {"it": "Allora siate gentili, non lasciatemi alla mia tristezza: scrivetemi che è tornato...", "zh": "请你们别让我独自悲伤：写信告诉我，他回来了……", "t": [21488, 26500]}]}]}]}